// ==========================================
// ★ K 의 방 — B등급 직업 갈림길 · 행운
// ==========================================
//
// 노름꾼 · 행상 · 점술가 · 수집가 · 거지
// 탈출 · 스릴러 · 느와르 — 비 오는 밤, 잠긴 문, 쫓는 발소리, 줄어드는 시간.
// 'B' = 어느 B 던전에서나 · B1 항구 창고 · B2 폐쇄 병동 · B3 야간열차

// ==========================================
// 🎲 노름꾼 (gambler) · 자원 없음
// ==========================================
kJob('gambler', 'B', [

{ at:'B', t:'빗속 골목 — 앞면만 있는 동전',
  x:`비가 그치지 않는다. 처마 끝에서 물이 줄이 되어 떨어진다.<br><br>
    골목이 둘로 갈린다. 한쪽 끝에 붉은 네온, 한쪽 끝에 꺼진 가로등. 뒤에서 구두 소리가 온다. 서두르지 않는 걸음이다.<br>
    발밑 웅덩이에 동전 하나가 떨어져 있다. 주워서 뒤집었다. 양쪽이 다 앞면이다.<br><br>
    누가 일부러 흘린 동전이다. 이 동네는 골목도 그런 식으로 고르게 만든다.`,
  o:[
    { l:'① 동전을 던지지 않고 판을 뒤집는다.', k:'luck', dc:20, wake:1,
      ok:`던지지 않았다. 앞면만 있는 동전을 던지면 앞면을 고르라고 한 사람이 이긴다. 그 사람은 여기 없다. 그래도 판은 그 사람 것이다.<br><br>앞면이 가리킬 쪽, 네온 골목을 버렸다. 꺼진 가로등 쪽으로 갔다. 웅덩이를 피해 디뎠다.<br>등 뒤에서 구두 소리가 네온 골목으로 꺾여 들어갔다. 기다리던 쪽으로.<br><br>패를 읽던 눈이 판을 짠 손을 읽었다. 판 밖에 앉은 사람까지 셈에 넣는 버릇이 그날 손에 붙었다.`,
      ng:`던지지 않으려 했는데 손이 버릇대로 던졌다.<br><br>동전이 웅덩이에 떨어져 섰다. 모로. 양면이 앞면인 동전이 모로 섰다.<br>그걸 보는 사이 구두 소리가 바로 뒤까지 왔다. 돌아보지 않고 뛰었다. 가로등 기둥에 어깨를 찧었다. 쇠가 울리는 소리가 골목 끝까지 갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 구두 소리의 박자를 잰다.', k:'sense', dc:19,
      ok:`동전을 주머니에 넣고 귀를 기울였다.<br><br>구두 소리가 열 걸음마다 한 번 끊긴다. 끊길 때 물 밟는 소리가 안 난다. 웅덩이를 피해 걷는다. 이 골목을 잘 아는 발이다.<br>웅덩이가 많은 쪽으로 갔다. 꺼진 가로등 쪽. 구두 소리가 그 앞에서 한참 망설였다.<br><br>상대 버릇은 상대가 쥔 패다.`,
      ng:`세는데 빗소리가 박자를 덮는다.<br><br>열 걸음인지 열두 걸음인지 모르겠다. 모르는 채로 아무 쪽이나 들어갔다. 막다른 벽이었다.<br>돌아 나올 때 구두 소리는 골목 입구에 서 있었다. 그냥 서 있었다. 그게 더 나빴다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 하역부들의 판',
  x:`창고 구석, 팔레트 뒤에서 불빛이 샌다.<br><br>
    하역부 넷이 나무 상자를 상 삼아 패를 돌린다. 판돈은 돈이 아니다. 출근 카드다. 번호만 찍힌 카드가 상 가운데 수북하다.<br>
    하나가 고개도 안 들고 말한다. 다섯 시 십 분에 누가 남는지 거는 판이라고. 빈자리가 하나 있다.<br><br>
    상 밑 못에 쪽문 열쇠 꾸러미가 걸려 있다. 빈자리를 보니 손바닥이 간지럽다.`,
  o:[
    { l:'① 빈자리에 앉는다.', k:'luck', dc:21,
      doom:{ title:'다섯 시 십 분 판', what:'판에서 일어나지 못합니다', dc:17, sec:55,
        text:`앉았다. 패가 넘어온다. 나쁘지 않다. 첫 판을 땄다. 카드 한 장이 이쪽으로 밀려온다. 이쪽 번호가 찍힌 카드다.<br><br>일어서려는데 옆 사람이 어깨에 손을 얹는다. 젖은 손이다. 판은 다섯 시 십 분까지라고 한다.<br>셔터 밖에서 양동이 내려놓는 소리가 난다.<br><br>하역부들은 고개를 안 든다. 다들 이미 이쪽 카드에 걸었다.`,
        dieText:`다섯 시 십 분에 판이 끝났다.<br><br>하역부들이 카드를 나눠 가진다. 딴 사람도 잃은 사람도 표정이 같다.<br>빈자리가 하나 생겼다. 다음 판에 쓸 자리다.` },
      ok:`앉아서 첫 패를 받았다. 보지 않고 엎었다.<br><br>엎은 채로 판돈 위에 손을 얹었다가 뗐다. 손바닥에 카드 한 장이 붙어 나왔다. 붙어 나온 게 아니라 붙여 나왔다. 상 밑 열쇠 꾸러미는 무릎으로 걷어 올렸다.<br>"한 판만 보고 가지." 일어섰다. 아무도 붙잡지 않았다. 패를 안 본 사람은 판에 안 앉은 사람이다.<br><br>카드에는 오늘 날짜와 이쪽 번호가 찍혀 있었다. 판돈에서 제 이름을 빼 왔다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 등 뒤에 서서 판을 돌리는 손을 본다.', k:'gaze', dc:20,
      ok:`앉지 않고 등 뒤에 섰다. 구경꾼 자리다.<br><br>판이 세 번 돈다. 이기는 사람이 매번 다르다. 그런데 패를 돌리는 손은 매번 같다. 그 손은 한 번도 안 이겼다. 안 이기는 사람이 판을 연 사람이다.<br>그 사람 의자 등에 회색 비옷이 걸려 있다. 장화도 회색이다.<br><br>상 밑 꾸러미는 미끼였다. 진짜 쪽문 열쇠는 비옷 주머니에 있었다. 판이 한 바퀴 돌 동안 손가락 두 개로 집어 왔다.`,
      ng:`등 뒤에 섰는데 하역부 하나가 돌아본다.<br><br>구경꾼은 판에 안 건 사람이다. 안 건 사람은 이 창고에서 셀 것이 없다. 그가 패 대신 이쪽을 센다. 손가락 하나를 접는다.<br>물러나다 팔레트 모서리에 정강이를 찍었다. 상 위에서 카드 한 장이 저절로 뒤집혔다. 이쪽 번호였다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, spirit:-14 } },
    { l:'③ 그림자 속에서 손만 넣어 열쇠를 걷는다.', k:'hide', dc:21,
      ok:`팔레트 그림자에 엎드렸다. 상 밑까지 팔 하나 길이다.<br><br>패가 넘어갈 때 다들 패를 본다. 그때 손을 넣었다. 패 넘어가는 소리에 열쇠 걷히는 소리를 겹쳤다.<br>꾸러미가 손에 들어왔다. 아무도 상 밑을 안 봤다. 판에서는 다들 위만 본다.`,
      ng:`손을 넣는데 열쇠끼리 부딪쳤다.<br><br>패 넘기던 손이 멈춘다. 넷이 동시에 상 밑을 본다. 고개만 숙였다. 표정이 없다.<br>손을 빼고 굴렀다. 팔레트가 기울며 상자 하나가 등에 떨어졌다. 숨이 한참 안 쉬어졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-10 } }
  ] },

{ at:'B2', t:'휴게실 — 알약 내기',
  x:`휴게실 탁자에 환자 셋이 둘러앉았다. 패 대신 알약을 쥐었다.<br><br>
    하얀 것, 노란 것, 반으로 쪼갠 것. 한 판 질 때마다 하나씩 삼킨다. 이긴 사람은 안 삼킨다. 셋 다 눈꺼풀이 무겁다.<br>
    하나가 이쪽에 패를 내민다. 이기면 간호사실 문 번호를 알려 주겠다고 한다.<br><br>
    탁자 끝에 다 먹은 약 봉투가 쌓였다. 이름 칸이 다 비었다.`,
  o:[
    { l:'① 앉아서 지지 않을 만큼만 이긴다.', k:'luck', dc:20,
      ok:`앉았다. 첫 판은 졌다. 노란 것을 혀 밑에 넣고 삼키는 척했다.<br><br>둘째 판부터 패를 안 보고 상대 눈꺼풀을 봤다. 졸린 사람은 좋은 패를 쥐면 눈을 한 번 크게 뜬다. 아주 잠깐.<br>셋째 판에 이겼다. 넷째 판은 일부러 비겼다. 너무 많이 이기면 상대가 잠에서 깬다.<br><br>상대가 숫자 네 개를 불러 줬다. 혀 밑의 노란 것은 화분에 뱉었다.`,
      ng:`앉았다. 첫 판에 졌다. 혀 밑에 넣으려는데 맞은편이 이쪽 턱을 쥔다.<br><br>"삼켜." 웃으며 쥔다. 손힘이 환자 손힘이 아니다.<br>삼켰다. 탁자 모서리가 두 개로 보이기 시작했다. 그다음 판은 기억나지 않는다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 판 말고 약 봉투를 본다.', k:'gaze', dc:19,
      ok:`앉지 않고 탁자 끝 봉투 더미를 집었다.<br><br>봉투마다 처방 날짜가 찍혀 있다. 오늘, 오늘, 오늘. 셋이 오늘 먹은 양이 사흘 치다.<br>봉투 하나 귀퉁이에 볼펜으로 숫자 넷이 적혀 있다. 누가 판에서 따 놓고 못 쓴 것이다. 따 놓고 잠든 것이다.<br><br>판에 앉지 않고 판돈만 집어 왔다.`,
      ng:`봉투를 집는데 셋이 한꺼번에 고개를 든다.<br><br>판돈에 손을 댄 것이다. 셋의 눈이 갑자기 맑다. 아까까지 감기던 눈이다.<br>봉투를 내려놓고 물러났다. 등 뒤에서 패 섞는 소리가 다시 났다. 판이 이쪽 몫을 남겨 두고 돈다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-12 } }
  ] },

{ at:'B3', t:'식당칸 — 얼굴이 바뀌는 상대',
  x:`식당칸 맨 끝 식탁에 남자가 혼자 패를 섞는다.<br><br>
    맞은편 자리에 이미 패가 돌려져 있다. 이쪽이 올 줄 알았다는 듯이.<br>
    남자가 고개를 든다. 늙었다. 숙였다가 다시 든다. 젊다. 창에 비친 얼굴은 또 다르다.<br><br>
    판돈 자리에 연결문 열쇠가 놓여 있다. 노름꾼은 얼굴로 패를 읽는 사람이다. 그 얼굴이 판마다 바뀐다.`,
  o:[
    { l:'① 얼굴 대신 손을 본다.', k:'gaze', dc:21, wake:1,
      ok:`얼굴은 버렸다. 남자 손만 봤다.<br><br>얼굴은 판마다 바뀐다. 손은 안 바뀐다. 좋은 패를 쥐면 새끼손가락이 패 끝을 한 번 쓸어 본다. 늙은 얼굴일 때도 젊은 얼굴일 때도 똑같이.<br>세 판을 접고 넷째 판에 다 걸었다. 새끼손가락이 가만히 있던 판이다. 이겼다. 열쇠가 이쪽으로 밀려왔다.<br><br>얼굴 없는 상대를 손으로 읽었다. 버릇은 얼굴보다 깊이 박힌다. 그걸 보는 눈이 한 겹 더 깊어졌다.`,
      ng:`손을 보는데 남자도 이쪽 손을 본다.<br><br>새끼손가락이 움직였다. 이쪽 것이. 남자가 웃는다. 이번엔 이쪽과 똑같은 얼굴로.<br>판이 넘어갔다. 열쇠는 남자 주머니로 들어갔다. 창에 비친 이쪽 얼굴이 한 박자 늦게 웃었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 패도 안 보고 크게 건다.', k:'luck', dc:22,
      ok:`첫 판에 가진 걸 다 밀었다. 패는 엎은 채로 뒀다.<br><br>남자 얼굴이 세 번 바뀐다. 고민하는 얼굴이 셋이다. 결국 접었다.<br>얼굴을 몇 개 가졌든 큰 판 앞에서는 다 같은 얼굴이 된다. 겁먹은 얼굴.<br><br>열쇠를 쥐고 일어섰다. 이쪽 패는 끝까지 안 뒤집었다. 나중에 보니 아무것도 아니었다.`,
      ng:`다 밀었다. 남자가 바로 받는다. 망설임이 없다.<br><br>패를 뒤집었다. 졌다. 남자가 판돈을 쓸어 간다. 쓸어 가는 손에 이쪽 손목시계가 섞여 있다. 언제 밀었는지 모른다.<br>시계가 없으니 몇 시인지 모른다. 종착까지 얼마 남았는지도.`,
      win:{ exp:20, dream:4 }, lose:{ mind:-18, spirit:-12 } },
    { l:'③ 앉지 않고 판을 엎는다.', k:'break', dc:20,
      ok:`식탁 모서리를 잡아 엎었다.<br><br>패가 쏟아진다. 열쇠가 바닥으로 미끄러진다. 남자 얼굴이 일그러지다 만다. 일그러진 얼굴 몇 개가 겹쳐 보였다.<br>열쇠를 발로 끌어 뒤로 물러났다. 남자는 일어서지 않았다. 패를 다시 줍기 시작했다. 판은 다음 손님을 기다린다.`,
      ng:`잡았는데 식탁이 바닥에 박혀 있다. 열차 식탁이다.<br><br>안 움직인다. 남자가 천천히 이쪽 손목을 잡는다. 손이 차다. 얼굴은 웃는데 손은 안 웃는다.<br>뿌리치는 데 한참 걸렸다. 손목에 손가락 자국이 남았다. 다섯 개가 아니라 여섯 개.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B', t:'잠긴 방 — 세 개의 문',
  x:`문이 셋이다. 셋 다 같은 철문이다.<br><br>
    문 위에 벽시계가 걸렸다. 초침 소리가 크다. 바닥에 분필로 적혀 있다. 『하나만 열린다. 틀리면 셋 다 잠긴다.』<br>
    이런 판은 안다. 셋 중 하나. 처음 고른 걸 바꾸느냐 마느냐.<br><br>
    그런데 여기엔 문 하나를 먼저 열어 보여 줄 진행자가 없다. 시계만 있다.`,
  o:[
    { l:'① 초침의 떨림을 보고 고른다.', k:'luck', dc:20,
      ok:`초침을 봤다. 매초 조금씩 떤다. 아홉 시 쪽을 지날 때만 덜 떤다.<br><br>그쪽 벽 아래 문, 왼쪽 문을 골랐다. 시계 뒤로 줄이 이어져 있을 것이다. 줄이 당겨진 쪽은 덜 떤다.<br>손잡이를 돌렸다. 열렸다.<br><br>판을 연 사람이 남긴 흔적은 늘 판에 남는다. 시계도 판의 일부다.`,
      ng:`떨림을 보는데 초침이 멈춘다.<br><br>시계가 멈추자 방이 조용하다. 너무 조용해서 복도 발소리가 들린다. 이쪽으로 온다.<br>아무 문이나 잡았다. 잠겼다. 다른 문으로 뛰었다. 그 문은 열려 있었다. 문틀에 이마를 찧었다.`,
      win:{ exp:16, dream:3 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 분필 글씨를 의심한다.', k:'gaze', dc:19,
      ok:`글씨를 손가락으로 문질렀다. 잘 안 지워진다. 오래된 글씨다.<br><br>오래된 글씨라면 그동안 여러 사람이 이 앞에 섰다. 바닥 먼지를 봤다. 가운데 문 앞만 닳았다. 다들 가운데를 고른다.<br>가운데 문에 귀를 댔다. 안에서 누가 숨을 쉰다. 기다린다.<br><br>오른쪽 문으로 갔다. 열렸다. 다들 고르는 패는 판이 먹는 패다.`,
      ng:`문지르는데 분필이 아니다. 긁힌 자국이다.<br><br>누가 손톱으로 바닥을 긁어 쓴 글씨다. 손톱 자국이 문 쪽으로 끌려간다.<br>그걸 따라 보다 시간을 다 썼다. 초침이 열두 시에 닿았다. 철컥. 셋 다 잠겼다. 환풍구를 기어서 나오는 데 무릎이 다 까졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B1', t:'경매장 — 손가락 호가',
  x:`어시장 경매장. 비 새는 지붕 밑에 수조가 줄지어 섰다.<br><br>
    경매사가 종을 치고 빠르게 노래한다. 노란 비옷들이 손가락만 까딱인다. 목소리 없는 호가다.<br>
    오늘 올라온 물건은 생선이 아니다. 번호표가 붙은 빈 자루다. 맨 끝 자루 번호가 이쪽 출근 카드 번호와 같다. 비어 있다. 아직.<br><br>
    경매도 판이다. 판이면 끼어들 수 있다.`,
  o:[
    { l:'① 손가락 하나로 제 자루를 산다.', k:'luck', dc:21, wake:1,
      ok:`이쪽 번호가 불릴 때 손가락을 들었다. 경매사 노래가 한 박자 멈췄다가 이어진다.<br><br>노란 비옷 하나가 받는다. 이쪽이 또 든다. 셋째 호가에서 비옷이 머뭇거렸다. 이쪽은 안 머뭇거렸다. 판돈이 없는 사람은 머뭇거릴 이유가 없다.<br>종이 울렸다. 낙찰. 제 자루를 제가 샀다. 값은 나중에 치르겠다고 손짓했다. 외상은 판에서 제일 흔한 패다.<br><br>쥔 것 없이 쥔 척하는 손이 남의 판까지 움직였다. 손이 한 뼘 커진 것 같았다.`,
      ng:`손가락을 들었는데 아무도 안 받는다.<br><br>경매사가 바로 종을 친다. 낙찰. 노란 비옷들이 고개를 돌려 이쪽을 본다. 값을 받으러 온다.<br>값은 자루로 받는다. 비옷 둘이 팔을 잡았다. 수조 가장자리를 붙잡고 버티다 손바닥이 찢어졌다. 겨우 뿌리쳤다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 경매사의 노래를 받아 적는다.', k:'sense', dc:20,
      ok:`노래를 들었다. 빠르지만 숫자가 섞여 있다. 숫자 사이사이 시각이 섞여 있다. 넷 오십, 다섯 영오, 다섯 십.<br><br>자루마다 실릴 시각이다. 이쪽 번호는 다섯 시 십 분, 맨 마지막이다. 마지막 패가 제일 늦게 깔린다.<br>남은 시간을 셈하고 빠져나왔다. 나오는 길에 수조 하나 바닥에 민물고기 한 마리가 숨어 있었다. 경매에 안 올라간 놈이다.`,
      ng:`받아 적는데 노래가 갑자기 느려진다.<br><br>경매사가 이쪽을 보고 부른다. 천천히. 이쪽 번호를. 노란 비옷들이 손가락을 들기 시작한다.<br>뒷걸음질 치다 수조에 등이 부딪쳤다. 깨진 유리가 팔꿈치에 박혔다.`,
      win:{ exp:16, dream:2, item:'민물고기' }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B2', t:'정각 — 딸깍 세기',
  x:`정각이다. 복도에서 딸깍 소리가 온다. 간호사가 계수기를 누르며 병실을 돈다.<br><br>
    패를 셀 줄 알면 이것도 셀 수 있다. 나간 패를 세면 남은 패가 보인다.<br>
    딸깍도 패다. 병실마다 누르는 수가 다르다. 3호실 넷, 4호실 셋, 5호실 다섯.<br><br>
    이쪽 병실은 6호실이다. 침대가 다섯인데 사람은 일행까지 여섯이다.`,
  o:[
    { l:'① 딸깍을 끝까지 센다.', k:'luck', dc:21, wake:1,
      ok:`셌다. 복도 끝까지 서른한 번. 화이트보드 숫자는 서른둘이다.<br><br>하나가 빈다. 어느 병실에서 빈 건지도 셈이 선다. 2호실이다. 문이 열려 있고 침대 하나가 비었다.<br>간호사가 돌아오기 전에 일행 하나를 2호실 빈 침대로 보냈다. 다음 정각에 6호실도 2호실도 숫자가 맞았다.<br><br>남은 패로 판을 맞췄다. 이기는 셈이 아니라 안 들키는 셈. 셈이 하나 늘었다. 손가락이 저절로 접히고 펴진다.`,
      ng:`세는데 딸깍이 두 겹으로 들린다.<br><br>한 번 누를 때 소리가 두 번 난다. 계수기가 둘이다. 복도 반대편에서 또 하나가 오고 있다.<br>셈이 흐트러졌다. 6호실 문 앞에서 소리가 멈췄다. 일행 누군가 숨을 크게 쉬었다. 딸깍.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 침대 하나에 둘이 눕는다.', k:'hide', dc:20,
      ok:`일행 하나와 한 침대에 등을 붙이고 누웠다. 이불을 높이 올렸다.<br><br>간호사가 문 앞에 섰다. 계수기를 다섯 번 눌렀다. 침대 다섯, 볼록한 이불 다섯.<br>패가 한 장 더 있어도 겹쳐 두면 안 보인다. 밑장은 늘 윗장 밑에 있다.`,
      ng:`둘이 눕는데 침대 다리가 삐걱한다.<br><br>간호사가 그 침대 앞에서 멈췄다. 이불을 한 겹 들춘다. 얼굴 하나. 덮는다. 다시 들춘다.<br>두 번째 들출 때 숨을 참았다. 너무 오래 참았다. 간호사가 떠난 뒤 기침이 한참 멈추지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'서지 않는 역 — 일곱 초',
  x:`창밖으로 역이 다가온다. 열차는 속도를 늦추지 않는다.<br><br>
    승강장 불빛이 지나가는 데 몇 초가 걸리는지 세어 봤다. 지난 역은 여덟. 그 전은 아홉.<br>
    승강장마다 우산 든 사람이 하나씩 서 있다. 같은 사람 같다. 역 이름판은 너무 빨라 못 읽었다.<br><br>
    화장실 창 하나가 반쯤 열린다. 몸을 내밀면 이름판이 손 닿는 데로 지나간다.`,
  o:[
    { l:'① 창밖으로 몸을 내밀어 이름판을 읽는다.', k:'luck', dc:22,
      doom:{ title:'일곱 초', what:'승강장 쪽으로 끌려 나갑니다', dc:17, sec:50,
        text:`몸을 내밀었다. 비가 얼굴을 때린다. 승강장이 온다. 하나, 둘.<br><br>셋째 초에 이름판이 지나간다. 글자가 없다. 넷째 초에 우산 든 사람이 지나간다. 지나가지 않는다. 손이 이쪽 옷깃을 잡았다.<br>열차는 앞으로 가고 손은 뒤로 당긴다. 상반신이 창틀 밖으로 미끄러진다.<br><br>초를 셀 줄 아는 사람이다. 승강장이 끝나기까지 남은 초도 안다.`,
        dieText:`열차가 다 지나갔다.<br><br>승강장에 우산 든 사람이 둘 서 있다. 둘 다 기다리는 얼굴이다.<br>다음 열차가 오면 둘 중 하나는 화장실 창 쪽으로 손을 내밀 것이다.` },
      ok:`일곱을 셀 수 있는 판이다. 셋만 쓰기로 했다. 몸을 내밀었다.<br><br>둘째 초에 이름판. 글자가 없다. 대신 숫자가 있다. 3. 셋째 초에 몸을 뺐다. 우산 든 사람 손이 창틀을 스치고 지나갔다.<br>숫자는 남은 역의 수다. 시간표 칸과 맞춰 보니 맞다.<br><br>남은 넷째 초는 안 썼다. 안 쓴 초가 목숨이었다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 역과 역 사이를 센다.', k:'sense', dc:20,
      ok:`창에서 떨어져 앉았다. 승강장이 지나가는 초 말고, 역과 역 사이를 셌다.<br><br>여덟 분, 일곱 분, 여섯 분. 역마다 일 분씩 준다. 열차가 빨라지는 게 아니라 역이 가까워진다.<br>남은 역과 남은 분을 맞춰 봤다. 기관실까지 갈 시간이 셈으로 나왔다. 빠듯하다. 빠듯한 판은 아는 것만으로 반은 이긴다.`,
      ng:`세다가 졸았다. 열차 흔들림이 박자를 지운다.<br><br>깨어 보니 몇 역을 지났는지 모른다. 시간표 칸 하나가 지워져 있다. 누가 지웠는지 모른다.<br>모르는 판에서 셈하는 것만큼 지치는 일은 없다.`,
      win:{ exp:16, dream:3 }, lose:{ mind:-16, spirit:-12 } },
    { l:'③ 창을 닫고 승강장을 보지 않는다.', k:'steady', dc:19,
      ok:`창을 닫고 등을 돌렸다. 역이 지나갈 때 눈을 감았다.<br><br>안 보는 패에는 안 걸린다. 승강장 불빛이 눈꺼풀 위로 지나갔다. 일곱 초.<br>눈을 떴을 때 창유리에 손자국이 하나 찍혀 있었다. 바깥쪽에.`,
      ng:`창을 닫는데 틀이 걸린다. 안 닫힌다.<br><br>눈을 감았는데 감은 눈 위로 우산이 보인다. 다음 역에도, 그다음 역에도.<br>세 역을 지나는 동안 눈을 못 떴다. 뜨기가 무서웠다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B', t:'골목 끝 — 빈손',
  x:`골목 끝에 누가 서 있다. 비옷 모자를 깊이 눌러썼다.<br><br>
    손이 주머니에 들어가 있다. 주머니가 무겁게 처졌다. 이쪽도 손을 주머니에 넣었다. 이쪽 주머니엔 동전 두 닢뿐이다.<br>
    빈손으로 큰 판을 많이 해 봤다. 빈손은 숨기기만 하면 제일 센 패다.<br><br>
    저쪽 손도 빈손일 수 있다. 아닐 수도 있다.`,
  o:[
    { l:'① 걸음을 늦추지 않고 다가간다.', k:'luck', dc:21,
      ok:`주머니 속 동전 두 닢을 쥐어 무게를 만들었다. 걸음을 늦추지 않았다.<br><br>열 걸음. 다섯 걸음. 저쪽 어깨가 아주 조금 뒤로 간다. 몸이 먼저 접은 것이다.<br>스쳐 지나갔다. 지나가며 저쪽 주머니를 봤다. 처진 주머니에 든 건 물 먹은 장갑이었다.<br><br>둘 다 빈손이었다. 먼저 다가간 쪽이 이겼다.`,
      ng:`다가가는데 저쪽도 다가온다. 같은 속도로.<br><br>허세가 허세를 만났다. 다섯 걸음 앞에서 저쪽이 주머니에서 손을 뺐다. 빈손이 아니었다.<br>뒤로 뛰었다. 등 뒤로 무엇인가 날아와 벽에 박혔다. 귀 옆이 뜨겁다. 피가 목을 타고 흘렀다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 판을 접고 왔던 길로 돌아간다.', k:'evade', dc:19,
      ok:`돌아섰다. 서두르지 않고. 서두르면 쫓긴다.<br><br>골목 둘을 돌아 다른 길로 나왔다. 반 시간을 잃었다. 반 시간으로 목을 샀다.<br>나중에 멀리서 그 골목 끝을 봤다. 사람이 아직 서 있다. 이쪽이 올 줄 알고 서 있던 자리다.`,
      ng:`돌아섰는데 등 뒤 발소리가 따라온다.<br><br>접는 걸 본 것이다. 접은 쪽은 쫓긴다. 젖은 계단에서 미끄러졌다. 무릎이 깨졌다.<br>발소리는 계단 위에서 멈췄다. 내려오지는 않았다. 위에서 내려다보는 숨소리만 들렸다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-22, spirit:-12 } }
  ] },

{ at:'B1', t:'야적장 — 컨테이너 섞기',
  x:`야적장에 비가 퍼붓는다. 크레인이 컨테이너를 들었다 놓는다. 쉬지 않는다.<br><br>
    똑같은 회색 컨테이너 셋. 그중 하나에 일행 하나가 숨었다. 크레인이 셋을 하나씩 들어 자리를 바꾼다. 천천히, 그다음 빠르게.<br>
    이 판은 안다. 장터에서 컵 셋으로 하던 것이다. 판을 돌리는 손은 늘 보는 사람보다 빠르다.<br><br>
    크레인 운전석 유리에 회색 비옷이 비친다. 셋 중 하나가 바다 쪽 끝으로 가고 있다.`,
  o:[
    { l:'① 컨테이너 말고 갈고리를 따라간다.', k:'gaze', dc:21,
      ok:`눈을 컨테이너에 두지 않았다. 크레인 갈고리에 뒀다.<br><br>컵 판에서도 컵은 안 본다. 손을 본다. 갈고리가 무거운 걸 들 때 사슬이 한 번 더 처진다. 사람 하나 무게만큼.<br>세 번 바뀐 뒤 가운데 것을 골랐다. 문을 열었다. 일행이 웅크리고 있었다. 바다 끝으로 간 컨테이너는 비어 있었다. 아직은.`,
      ng:`따라가는데 빗발이 눈을 친다.<br><br>한 번 깜박였다. 컵 판은 한 번 깜박이면 끝이다. 고른 컨테이너는 비어 있었다.<br>다른 걸 열러 뛰는 사이 크레인 갈고리가 머리 위로 지나갔다. 몸을 던졌다. 어깨가 철판 모서리에 찢겼다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 바다 끝으로 가는 것에 건다.', k:'luck', dc:22,
      doom:{ title:'바다 쪽 끝', what:'컨테이너째 들려 갑니다', dc:17, sec:50,
        text:`바다 끝 컨테이너에 뛰어들었다. 문을 열었다. 비었다.<br><br>문이 등 뒤에서 닫힌다. 바깥에서 빗장 소리. 바닥이 기운다. 들린다.<br>철벽 너머로 사슬 감기는 소리. 크레인이 이쪽을 바다 위로 옮긴다.<br><br>판을 돌리는 쪽은 언제나 남은 패를 안다. 제일 잘 알던 말이다.`,
        dieText:`해무호 갑판에 컨테이너 하나가 내려앉았다.<br><br>전량 적재. 칠판의 숫자에서 하나가 지워졌다.<br>안에서 두드리는 소리는 엔진 소리에 묻혔다.` },
      ok:`바다 끝으로 가는 것에 뛰었다. 판을 돌리는 쪽은 꼭 가져갈 패를 마지막에 옮긴다.<br><br>문을 열었다. 일행이 있었다. 끌어냈다. 빈 컨테이너가 등 뒤에서 들린다.<br>운전석의 비옷이 이쪽을 내려다본다. 한참. 다시 일을 시작했다.<br><br>가져갈 쪽이 제일 마지막에 움직인 패를 잡았다.`,
      win:{ exp:22, dream:4 } },
    { l:'③ 크레인 전원을 내린다.', k:'break', dc:20,
      ok:`크레인 다리 밑 배전함을 찾았다. 녹슨 걸쇠를 비틀어 열었다.<br><br>손잡이를 내렸다. 크레인이 멈춘다. 컨테이너 하나가 허공에 매달린 채 흔들린다.<br>판을 멈추면 섞이지 않는다. 셋을 다 열었다. 시간은 걸렸다. 다 열었다.`,
      ng:`걸쇠를 비트는데 빗물이 손을 타고 들어간다.<br><br>손끝이 튀었다. 팔이 저리다. 손잡이를 반만 내렸다. 크레인이 더 빨라졌다.<br>컨테이너 셋이 비를 뚫고 돌았다. 어느 것도 못 따라갔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-10 } }
  ] },

{ at:'B2', t:'밤 배식 — 컵 셋',
  x:`밤 배식 수레가 온다. 종이컵 셋에 알약이 하나씩.<br><br>
    배식원이 컵을 섞는다. 웃는 눈으로, 아주 빠르게. 하나는 잠자는 약이라고 한다. 잠들면 아침 점검까지 못 깬다.<br>
    웃음이 났다. 병원에서 컵 판을 볼 줄은 몰랐다.<br><br>
    판을 알면 판 돌리는 손도 안다.`,
  o:[
    { l:'① 배식원의 엄지를 본다.', k:'luck', dc:20,
      ok:`컵 말고 엄지를 봤다. 컵 판에서 속이는 손가락은 엄지다.<br><br>섞기가 끝날 때 엄지가 오른쪽 컵 바닥을 한 번 눌렀다. 컵 밑에 무엇인가를 붙인 것이다.<br>왼쪽을 집었다. 삼켰다. 그냥 진통제다. 배식원 웃는 눈이 처음으로 웃지 않았다.<br><br>수레가 떠날 때 밑칸 꿀 봉지 하나가 이쪽 소매로 들어왔다. 판에서 딴 몫이다.`,
      ng:`엄지를 보는데 엄지가 둘이다. 배식원 한 손에 엄지가 둘이다.<br><br>어느 엄지를 봐야 하는지 모르는 사이 컵이 섰다. 아무거나 집었다.<br>삼키고 열을 세기도 전에 다리가 풀렸다. 깨어 보니 복도 바닥이었다. 계수기 소리가 머리 위를 지나갔다.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ hp:-20, mind:-16 } },
    { l:'② 셋 다 받고 하나도 안 삼킨다.', k:'hide', dc:19,
      ok:`셋 다 받았다. 혀 밑에 하나, 볼 안쪽에 하나, 손바닥에 하나.<br><br>삼키는 척을 세 번 했다. 배식원이 고개를 끄덕이고 수레를 민다. 끝까지 안 고르면 진 판도 없다.<br>세 알을 휴지에 뱉었다. 잠자는 약은 남을 재울 수도 있다. 언젠가 쓸 패다.`,
      ng:`볼 안쪽에 넣은 것이 녹는다. 쓰다.<br><br>쓴맛이 목으로 넘어갔다. 셋 중 어느 것이었는지 모른다. 그 뒤로 한 시간이 비었다.<br>깨어 보니 손등에 볼펜으로 번호가 적혀 있다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B3', t:'검표 — 구멍 하나',
  x:`검표원이 온다. 모자를 깊이 눌러썼다. 손에 펀치를 들었다.<br><br>
    앞 좌석 손님이 표를 내민다. 검표원이 구멍을 뚫는다. 손님 고개가 앞으로 떨어진다. 잠든 것처럼.<br>
    이쪽 손에도 표가 있다. 구멍이 이미 하나다. 하나 더 뚫리면 어떻게 되는지 앞 좌석이 보여 줬다.<br><br>
    검표원이 두 칸 앞까지 왔다. 펀치 소리가 일정하다.`,
  o:[
    { l:'① 표를 바꿔치기한다.', k:'luck', dc:21,
      ok:`앞 좌석 손님 무릎 위 표를 집었다. 이미 두 번 뚫린 표다. 이쪽 표는 그 손에 쥐여 줬다.<br><br>검표원이 이쪽 표를 본다. 구멍 둘. 끝난 표다. 지나간다.<br>밑장 빼기는 판 위에서만 하는 게 아니다.<br><br>앞 좌석 손님은 이제 구멍 하나짜리 표를 쥐고 잔다. 깨어날지는 모른다. 판에서는 누군가 그 값을 치른다.`,
      ng:`집으려는데 앞 좌석 손이 표를 꽉 쥐고 있다. 잠든 손인데.<br><br>검표원이 이쪽에 섰다. 이쪽 표를 뚫는다. 딸깍. 머리가 앞으로 쏟아진다. 졸음이 아니라 무게다.<br>일행이 어깨를 흔들어 깨웠다. 몇 분이 사라졌다. 표에 구멍이 둘이다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-14 } },
    { l:'② 화장실에 들어가 노크를 센다.', k:'hide', dc:20,
      ok:`화장실 문을 잠갔다. 사용 중 표시가 붉게 켜진다.<br><br>발소리가 문 앞에서 멈춘다. 노크 한 번. 대답하지 않았다. 두 번. 상대가 몇 번까지 두드리는지 셌다. 판마다 상대는 정해 둔 횟수가 있다. 세 번째는 없었다.<br>문틈 밑으로 펀치 그림자가 지나갔다. 다음 칸으로.`,
      ng:`잠그고 숨을 죽였는데 문틈 밑으로 표가 들어온다. 이쪽 것이 아니다.<br><br>밀어내려는데 문 밖에서 펀치 소리가 난다. 딸깍. 손바닥이 뜨겁다. 손등에 동그란 구멍 자국이 생겼다. 피가 안 나는 구멍이다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B', t:'숨은 방 — 귀를 만지는 일행',
  x:`쉬는 사이 일행 하나가 자꾸 시계를 본다.<br><br>
    밖에서 누가 오기로 했다면 몇 시에 올지 아는 사람처럼. 볼 때마다 왼쪽 귀를 만진다.<br>
    사람 버릇으로 패를 읽는 일을 오래 했다. 귀를 만지는 사람은 거짓말을 앞두고 있다. 판에서 열 번 봤으면 아홉 번은 그랬다.<br><br>
    열 번째가 지금일 수도 있다.`,
  o:[
    { l:'① 동전 판을 벌여 떠본다.', k:'luck', dc:21, wake:1,
      ok:`동전을 꺼냈다. 앞뒤 맞히기. 심심풀이라고 했다.<br><br>세 판 동안 그는 앞만 불렀다. 넷째 판에서 시계를 보고 뒤를 불렀다. 그리고 귀를 만졌다. 시계를 볼 때 마음이 바뀌는 사람이다. 시계가 그에게 무엇을 시킨다.<br>그 뒤로 그를 맨 앞에 세웠다. 등을 보이는 쪽이 이쪽이 아니라 그쪽이 되게.<br><br>패 대신 사람을 읽었다. 판 바깥의 판까지 셈하는 버릇이 손끝에서 머리로 올라왔다.`,
      ng:`동전을 꺼냈는데 그가 웃으며 손을 젓는다.<br><br>판을 거절하는 사람은 이미 다른 판에 앉아 있다. 그걸 알았을 때는 늦었다. 그가 먼저 일어섰다. 문 쪽으로. 문 밖 무엇인가에게 신호를 보냈다.<br>다들 흩어졌다. 흩어진 채로 한참 헤맸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 몇 시냐고 바로 묻는다.', k:'bond', dc:20,
      ok:`"몇 시에 오기로 했나."<br><br>그가 굳는다. 귀를 만지려다 멈춘다. 오래 말이 없다가 털어놓는다. 들어오기 전에 누가 시계를 쥐여 줬다고. 그 시각에 문을 열어 두면 혼자는 내보내 준다고.<br>시계를 받아 창밖으로 던졌다. 그는 막지 않았다. 혼자 나가는 판은 원래 없다.`,
      ng:`물었다. 그가 웃는다. 귀는 안 만진다.<br><br>이쪽이 틀렸나 싶은 순간 그가 시계를 본다. 정각이다. 문 밖에서 무엇인가 문고리를 돌렸다. 열려 있었다.<br>싸우며 빠져나왔다. 그는 끝까지 맨 뒤에 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'③ 모르는 척하고 그가 고른 반대로 간다.', k:'steady', dc:19,
      ok:`아무 말도 안 했다. 그가 길을 고를 때마다 반대를 골랐다. 다른 이유를 대면서.<br><br>그가 가자고 한 세 길은 다 막혀 있었을 것이다. 확인은 안 했다. 확인하는 것도 판돈이다.<br>그는 끝까지 아무것도 눈치 못 챈 척했다. 그도 판을 아는 사람이다. 그건 인정했다.`,
      ng:`반대로 가는데 그가 그걸 읽는다. 그다음부터 그는 가기 싫은 길만 가리켰다.<br><br>이쪽은 그가 바란 길로 들어섰다. 문이 바깥에서 잠겼다. 반대쪽 벽을 부수고 나오는 데 손이 다 까졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-12 } }
  ] },

{ at:'B1', t:'방파제 — 마지막 동전',
  x:`방파제 끝이다. 다섯 시가 넘었다. 비가 가늘어진다.<br><br>
    배가 두 척이다. 한 척은 우산 쓴 남자가 대 놓겠다던 작은 배다. 한 척은 해무호다. 해무호 쪽은 사다리가 내려와 있다. 작은 배엔 사람이 없다.<br>
    뒤에서 양동이 소리가 온다. 하나 고를 시간밖에 없다.<br><br>
    노름꾼은 동전을 꺼냈다. 이번엔 앞뒤가 있는 동전이다.`,
  o:[
    { l:'① 동전에 맡긴다.', k:'luck', dc:22,
      ok:`던졌다. 손등에 받아 덮었다. 펴지 않았다.<br><br>펴지 않고 작은 배로 뛰었다. 동전은 고르는 데 쓰는 게 아니다. 마음이 어느 쪽을 바라는지 보는 데 쓴다. 덮는 순간 바란 쪽이 작은 배였다.<br>밧줄을 풀었다. 배 바닥 물통에 맑은 물이 반쯤 있었다.<br><br>동전은 끝까지 안 폈다. 펴 보면 아깝거나 무섭다.`,
      ng:`던졌는데 동전이 손에서 미끄러졌다. 방파제 돌 틈으로 굴러간다.<br><br>쫓아 손을 넣었다. 그만큼 늦었다. 양동이 소리가 바로 뒤에 섰다. 뒤도 안 보고 작은 배로 뛰었다. 뱃전에 갈비뼈를 찧었다.<br>돌아보니 회색 비옷이 방파제 끝에 서서 무엇인가 적는다.`,
      win:{ exp:20, dream:3, item:'맑은 물' }, lose:{ hp:-26, mind:-12 } },
    { l:'② 해무호 사다리의 발자국을 본다.', k:'gaze', dc:20,
      ok:`사다리 칸을 봤다. 칸마다 진흙 발자국이 있다. 올라간 자국만 있다. 내려온 자국이 없다.<br><br>해무호는 사람을 안 내린다. 작은 배로 갔다. 배 바닥에 물이 찼지만 뜬다.<br>내려오는 사람이 없는 판에는 앉지 않는다.`,
      ng:`보다가 사다리 위에서 누가 내려다보는 것과 눈이 마주쳤다.<br><br>판이 이쪽을 알아봤다. 사다리 위에서 갈고리 장대가 내려온다. 피하다 방파제 돌에 손목이 꺾였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-12 } }
  ] },

{ at:'B2', t:'승강기 앞 — 위로만 가는 판',
  x:`승강기 앞이다. 단추는 위쪽 화살표 하나뿐이다.<br><br>
    층수 표시판이 깜빡인다. 7, 8, 9, 그 위에 숫자가 없는 칸 하나. 승강기는 늘 그 칸에서 내려온다.<br>
    옆에 환자 하나가 쪼그려 앉아 표시판을 보며 손가락을 접는다. 승강기가 서는 층에 거는 것이다. 종이 접은 딱지를 내밀며 같이 걸자고 한다.<br><br>
    판을 보면 판이 몇 번 돌았는지부터 센다.`,
  o:[
    { l:'① 표시판이 도는 박자에 건다.', k:'luck', dc:20,
      ok:`표시판을 셌다. 올라갈 때 일곱 박, 내려올 때 다섯 박. 내려올 때 빠르다. 내려오는 동안은 아무도 안 탄다는 뜻이다.<br><br>내려오는 다섯 박 동안 단추를 누르지 않았다. 문이 7층에서 저절로 열린다. 비었다. 안에 들어가 바닥 판을 들췄다. 비상 사다리 칸이 있다. 아래로.<br>환자가 손가락을 펴 이쪽 판을 인정했다.`,
      ng:`세다가 표시판이 숫자 없는 칸에서 오래 멈춘다.<br><br>판이 바뀌었다. 문이 열린다. 안에 흰 옷들이 서 있다. 계수기를 쥐었다. 이쪽을 센다.<br>뒷걸음질 치다 환자를 밟았다. 둘이 같이 넘어졌다. 계수기 소리가 두 번 났다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 환자에게 이 판의 규칙을 묻는다.', k:'bond', dc:19,
      ok:`같이 쪼그려 앉았다. 판을 묻는 건 판에 앉는 것보다 싸다.<br><br>환자가 속삭인다. 아무도 안 이긴다고. 이긴 사람은 타고 올라간다고. 그래서 아무도 안 이기게 건다고.<br>지는 데만 걸어 여기 남은 사람이다. 지는 쪽에 건 사람이 판에 제일 오래 남는다. 그가 비상계단 열쇠를 묻어 둔 화분을 알려 줬다. 진 값이라고.`,
      ng:`묻는데 환자가 고개를 젓는다. 판 얘기는 판에서만 한다고.<br><br>환자가 손가락 하나를 이쪽에 건다. 이쪽이 탈 거라고. 그때 승강기 문이 열렸다. 몸이 저절로 한 걸음 나간다. 일행이 뒷덜미를 잡아당겼다. 목이 꺾였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-12 } }
  ] },

{ at:'B3', t:'특실 복도 — 여덟째 문',
  x:`특실 복도에 1호부터 7호까지 문이 있다. 그런데 문은 여덟이다.<br><br>
    여덟째 문에는 번호가 없다. 문틈으로 연기 같은 것이 샌다. 안에서 패 섞는 소리가 난다.<br>
    판이 서는 소리는 문 너머로도 안다.<br><br>
    판이 있으면 판돈이 있다. 기관실 쪽 연결문 열쇠일 수도 있다.`,
  o:[
    { l:'① 판방 식으로 두드리고 들어간다.', k:'luck', dc:21,
      ok:`두 번 두드리고 한 번 쉬고 한 번. 판방 두드리는 법은 어디나 같다.<br><br>문이 열린다. 안에 넷이 앉았다. 얼굴이 넷 다 같다. 이쪽이 앉자 넷이 이쪽 얼굴로 바뀌었다.<br>한 판만 했다. 이쪽 얼굴 넷을 상대로. 제 버릇은 제가 제일 잘 안다. 이겼다. 판돈 대신 연결문 열쇠를 받았다.<br><br>나올 때 넷이 동시에 이쪽 버릇대로 코끝을 긁었다.`,
      ng:`두드렸는데 문이 안 열린다. 대신 문틈으로 패 한 장이 나온다.<br><br>집어 보니 이쪽 얼굴이 그려진 패다. 쥔 손이 차가워진다. 놓으려는데 안 떨어진다.<br>한참 문 앞에 서 있었다. 패는 결국 떨어졌다. 손가락 끝 감각이 같이 떨어져 나갔다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 패 소리를 세어 몇이 앉았는지 안다.', k:'sense', dc:20,
      ok:`문에 귀를 댔다. 패 넘기는 소리를 셌다. 넷. 넘길 때마다 넷. 그런데 숨소리는 하나다.<br><br>한 사람이 네 자리에 앉아 혼자 돌린다. 혼자 하는 판은 끝나지 않는다. 그런 판에는 끼지 않는다.<br>문 대신 문 옆 환기구를 봤다. 손을 넣으니 열쇠가 걸렸다. 판 밖으로 굴러 나온 패다.`,
      ng:`귀를 댔는데 패 소리가 멈춘다.<br><br>안에서도 귀를 댄 것이다. 문 하나를 사이에 두고 숨이 겹쳤다. 문이 안쪽에서 확 열렸다. 넘어지며 복도 바닥에 이마를 찧었다. 열린 방은 비어 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'쉬는 자리 — 젖은 패',
  x:`비 안 드는 데를 찾아 다들 주저앉았다.<br><br>
    먹을 것을 꺼냈다. 말린 고기 반 줄, 물 한 병. 다섯이 나누기엔 모자라다. 다들 이쪽을 본다. 패 돌리는 손이 제일 공평하다고.<br>
    품에 젖은 패 한 벌이 있다. 이걸로 나누는 법도 있다.<br><br>
    다친 사람이 하나 있다. 다리를 절고 말을 안 한다.`,
  o:[
    { l:'① 패로 몫을 돌리고 밑장을 다친 사람에게 준다.', k:'luck', dc:20, wake:1,
      ok:`패를 돌렸다. 높은 패가 큰 몫을 가진다. 다들 웃으며 패를 받는다.<br><br>다친 사람에게 간 패는 맨 밑장이다. 제일 높은 패다. 아무도 몰랐다. 다친 사람은 운이 좋았다고만 생각한다. 고기를 받고 처음으로 입을 열었다. 고맙다고.<br><br>속이는 손으로 살렸다. 같은 손인데 쓰는 데가 달라졌다. 손이 판보다 사람을 먼저 보기 시작했다.`,
      ng:`젖은 패가 손에 붙는다. 밑장이 안 빠진다.<br><br>엉뚱한 패가 갔다. 다친 사람 몫이 제일 작다. 그 사람은 아무 말 없이 받았다. 그 침묵이 자리 전체를 무겁게 했다. 아무도 쉬지 못했다.`,
      win:{ exp:22, dream:3, hp:8 }, lose:{ mind:-14, spirit:-12 } },
    { l:'② 판 없이 똑같이 자른다.', k:'fix', dc:19,
      ok:`패는 집어넣었다. 칼로 고기를 다섯으로 잘랐다. 저울 대신 손바닥에 올려 봤다.<br><br>판이 없으면 다툼도 없다. 다들 조용히 먹었다. 물은 한 모금씩 두 바퀴 돌았다.<br>판을 안 벌이는 것도 판을 아는 사람의 일이다. 남은 한 조각은 다친 사람 주머니에 넣어 줬다.`,
      ng:`자르는데 칼이 미끄러졌다. 하나가 눈에 띄게 작다.<br><br>작은 것을 제가 가졌다. 그래도 눈길이 남았다. 다친 사람이 큰 쪽을 쳐다보는 눈길. 그 눈길 때문에 고기 맛이 안 났다. 칼에 벤 손가락이 한참 욱신거렸다.`,
      win:{ exp:14, dream:2, item:'말린 고기' }, lose:{ hp:-20, mind:-12 } }
  ] },

{ at:'B', t:'벽시계 — 십 분',
  x:`벽시계가 손목시계보다 십 분 빠르다.<br><br>
    어느 쪽이 맞는지에 따라 남은 시간이 다르다. 다들 손목시계를 믿고 싶어 한다. 늦은 쪽이 시간을 더 주니까.<br>
    시계 둘이 다르면 둘 다 의심한다. 판에서 시계를 쥔 쪽은 늘 판을 연 쪽이다.<br><br>
    창밖 하늘은 아직 검다. 빗소리 사이로 멀리서 무엇인가 시간을 알릴 것이다.`,
  o:[
    { l:'① 빠른 쪽에 걸고 서두른다.', k:'luck', dc:21, wake:1,
      ok:`빠른 쪽에 걸었다. 틀리면 십 분을 버리고 맞으면 십 분을 산다. 버리는 쪽이 싸다.<br><br>서둘렀다. 문 앞에 닿았을 때 멀리서 종이 울렸다. 벽시계가 맞았다. 손목시계는 누가 늦춰 놓은 것이다. 들어오기 전에 누군가 친절하게 맞춰 준 시계다.<br><br>잃어도 되는 쪽과 잃으면 안 되는 쪽을 한눈에 갈랐다. 판을 고르는 눈이 하나 더 생겼다. 이기는 판이 아니라 덜 지는 판을 보는 눈.`,
      ng:`서둘렀는데 서두르다 문 하나를 잘못 열었다.<br><br>안에 누가 있었다. 기다리고 있었다. 빠른 쪽에 건 사람을. 시계를 빠르게 맞춘 것도 판이었다.<br>문을 닫고 등으로 막았다. 문 너머에서 민다. 어깨가 빠질 것 같았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 빗소리로 시간을 잰다.', k:'sense', dc:20,
      ok:`시계 둘을 다 등지고 창에 귀를 댔다.<br><br>빗소리에 섞여 멀리 바퀴 지나는 소리가 난다. 간격이 줄고 있다. 새벽이 가까우면 길에 바퀴가 는다.<br>둘 다 틀렸다. 남은 시간은 둘보다 적다. 바로 출발했다. 그게 맞았다.`,
      ng:`귀를 대는데 빗소리만 난다.<br><br>빗소리에는 시간이 없다. 한참 듣는 사이 다른 사람들이 손목시계를 믿고 출발했다. 뒤따라가느라 숨이 찼다. 계단 하나를 헛디뎌 발목을 접질렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-12 } },
    { l:'③ 벽시계를 떼어 뒤를 본다.', k:'gaze', dc:19,
      ok:`벽시계를 떼어 뒤집었다. 뒤판에 태엽 열쇠가 꽂혀 있다. 누가 오늘 감았다.<br><br>오늘 감았다면 오늘 맞췄다. 손목시계는 들어오기 전에 받은 것이다. 판 안에서 맞춘 시계를 믿기로 했다.<br>시계를 다시 걸기 전에 바늘을 손으로 오 분 돌려 놓았다. 이제 이 판 시계는 이쪽도 조금 쥐었다.`,
      ng:`떼는데 시계 뒤에서 쪽지가 떨어진다. 이쪽 이름이 적혀 있다. 시각과 함께.<br><br>그 시각이 몇 분 남지 않았다. 쪽지를 쥐고 굳었다. 다들 이쪽을 본다. 무엇을 셈했는지 아무도 묻지 않았다. 손이 한참 떨렸다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'비 새는 방 — 넷째 의자',
  x:`비 새는 방 한가운데 둥근 상이 있다. 의자가 넷이다.<br><br>
    셋에 사람이 앉아 있다. 젖은 외투, 젖은 모자. 고개를 숙였다. 패를 쥔 채로 움직이지 않는다. 넷째 의자 앞에도 패가 돌려져 있다.<br>
    판돈 자리에 출구 쪽 문 열쇠가 있다. 열쇠 밑에 사진이 한 장 깔렸다. 이쪽 일행 사진이다. 언제 찍혔는지 모른다.<br><br>
    노름꾼은 안다. 이 판은 오래 기다렸다.`,
  o:[
    { l:'① 앉아서 한 판만 한다.', k:'luck', dc:22,
      doom:{ title:'넷째 의자', what:'판에서 일어나지 못합니다', dc:18, sec:50,
        text:`앉았다. 패를 집었다. 셋이 동시에 고개를 든다. 얼굴이 젖어 있다. 빗물이 아니다.<br><br>한 판을 이겼다. 열쇠가 이쪽으로 온다. 일어서려는데 셋 중 하나가 패를 돌린다. 다음 판이다. 손이 패를 집는다.<br>이긴 판에서 일어나는 게 제일 어렵다는 걸 안다. 알면서 손이 집는다.<br><br>사진 속 일행 얼굴이 하나씩 젖어 간다.`,
        dieText:`상 위에 패가 돈다.<br><br>의자가 넷이다. 넷 다 찼다. 넷 다 고개를 숙였다.<br>판돈 자리에 새 사진이 깔렸다. 다음에 올 사람들 사진이다.` },
      ok:`앉았다. 패는 안 집었다. 패 위에 손바닥을 얹고 그대로 엎었다.<br><br>판에 앉아 패를 안 보는 사람은 판이 셀 수 없다. 셋이 고개를 들기 전에 열쇠와 사진을 쓸어 일어섰다.<br>의자를 상 밑으로 밀어 넣었다. 넷째 의자는 다시 비었다. 다음 사람을 기다릴 것이다. 이쪽 몫은 아니다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 상을 기울여 열쇠만 미끄러뜨린다.', k:'hide', dc:21,
      ok:`상 가장자리에 손가락 하나를 댔다. 셋은 패만 본다.<br><br>상을 아주 조금씩 기울였다. 열쇠가 미끄러진다. 사진은 두었다. 사진까지 욕심내면 손이 보인다.<br>열쇠가 손바닥에 떨어졌다. 아무도 안 봤다.`,
      ng:`기울이는데 패 한 장이 미끄러졌다. 넷째 자리 패다.<br><br>셋이 그 패를 본다. 그리고 이쪽을 본다. 판이 시작된 것이다. 앉지도 않았는데.<br>물러났다. 셋의 손이 상 위로 길게 뻗어 왔다. 소매가 찢기고 팔뚝에 손톱 자국이 세 줄 남았다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, spirit:-16 } },
    { l:'③ 사진만 보고 판을 지나친다.', k:'steady', dc:19,
      ok:`사진만 보고도 알 건 다 알았다. 일행 중 하나가 사진에 없다. 찍은 사람이다.<br><br>판에는 손대지 않았다. 출구는 다른 데로 찾았다. 시간이 오래 걸렸다.<br>그 뒤로 사진에 없던 일행 곁에서는 등을 돌리지 않았다.`,
      ng:`지나치려는데 다리가 의자 쪽으로 간다. 판이 사람을 부른다.<br><br>상 모서리를 붙잡고 버텼다. 손톱이 상판에 박혔다. 발을 떼는 데 한참 걸렸다. 방을 나와서도 다리가 계속 떨렸다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-18 } }
  ] },

{ at:'B', t:'내려가는 계단 — 판돈 셈',
  x:`내려가기 전에 주머니를 털었다.<br><br>
    여기까지 딴 것, 주운 것, 남은 것. 판이 끝나면 반드시 센다.<br>
    동전 두 닢, 젖은 패 한 벌, 열쇠 하나, 이름 없는 쪽지.<br><br>
    하나가 더 있다. 넣은 기억이 없는 주사위 하나.`,
  o:[
    { l:'① 주사위를 굴려 본다.', k:'luck', dc:20, wake:1,
      ok:`손바닥에서 굴렸다. 여섯. 다시. 하나. 다시. 넷.<br><br>고르다. 납을 넣은 것이 아니다. 진짜 주사위다. 진짜 주사위는 누구 편도 아니다.<br>속이는 판 한복판에서 누구 편도 아닌 것을 쥐었다. 그 무게가 손에 익었다.<br><br>속지 않는 패 하나를 품고 판에 들어가는 법. 그 셈이 오늘 손바닥에 붙었다.`,
      ng:`굴리니 손바닥에서 안 멈춘다. 계속 돈다.<br><br>멈추라고 손을 덮었다. 손바닥 밑에서 계속 돈다. 간지럽다가 뜨겁다. 계단 아래로 던졌다. 굴러 내려가는 소리가 끝나지 않았다.`,
      win:{ exp:22, dream:4 }, lose:{ mind:-14, spirit:-14 } },
    { l:'② 셈에 안 맞는 것은 두고 간다.', k:'steady', dc:19,
      ok:`셈에 안 맞는 주사위를 계단 첫 칸에 올려 두었다.<br><br>모르는 판돈은 모르는 빚이다. 빚을 지고 내려가느니 하나 덜 가지고 내려간다.<br>계단을 내려가는데 등 뒤에서 주사위가 한 번 구르는 소리가 났다. 돌아보지 않았다.`,
      ng:`내려놓으려는데 손이 안 펴진다.<br><br>판이 준 것을 안 받으면 판이 서운해한다. 손을 펴는 데 한참 걸렸다. 손바닥에 주사위 눈 자국이 여섯 개 찍혔다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-12, spirit:-14 } }
  ] }

]);

// ==========================================
// 🎒 행상 (peddler) · 자원 없음
// ==========================================
kJob('peddler', 'B', [

{ at:'B', t:'처마 밑 — 젖는 보따리',
  x:`비가 옆으로 친다. 처마 밑이 좁다. 보따리 반이 처마 밖으로 나가 젖는다.<br><br>
    뒤쪽 어디선가 문 잠기는 소리가 차례로 난다. 하나씩, 이쪽으로 다가온다.<br>
    곧 뛰어야 한다. 행상은 뛰는 짐은 따로 싼다.<br><br>
    등에 진 것은 평생 지고 다닌 가게다. 다 지고는 못 뛴다.`,
  o:[
    { l:'① 뛰는 짐으로 다시 싼다.', k:'luck', dc:20, wake:1,
      ok:`보따리를 풀었다. 값나가는 것 셋, 먹을 것 둘, 끈 한 타래. 나머지는 처마 밑에 두었다.<br><br>등에 진 짐이 반으로 줄었다. 값은 반도 안 줄었다. 비에 젖어 무거워질 것은 애초에 다 뺐다.<br>잠기는 소리가 처마 앞에 왔을 때 이미 골목 둘을 지났다.<br><br>덜어 내는 손이 값을 매기는 손보다 빨라졌다. 무엇을 버려야 하는지 아는 셈이 하나 붙었다.`,
      ng:`풀다가 손이 망설였다. 다 값이 있다.<br><br>반을 빼고 반을 도로 넣었다. 그사이 잠기는 소리가 바로 옆 문까지 왔다.<br>젖은 보따리를 안고 뛰었다. 무거웠다. 무릎이 먼저 나갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 보따리를 등에 붙이고 기둥이 된다.', k:'steady', dc:19,
      ok:`기름천을 꺼내 보따리를 싸고 등에 붙였다. 처마 기둥에 등을 박았다.<br><br>잠기는 소리가 이 문 앞에서 멈췄다가 지나갔다. 사람 하나 보따리 하나가 기둥 그림자 하나로 보였다.<br>짐이 사람을 숨겨 줄 때도 있다.`,
      ng:`등을 붙였는데 보따리가 처마 밖으로 튀어나온다.<br><br>문 잠그던 손이 멈춘다. 보따리 끝을 본다. 손전등이 이쪽으로 올라왔다. 뛰었다. 젖은 바닥에 손바닥을 갈았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-12 } }
  ] },

{ at:'B1', t:'3번 창고 사무실 — 적하 목록',
  x:`창고 사무실 벽에 적하 목록이 붙어 있다. 상자 번호, 무게, 내용물. 건어물, 소금, 통조림.<br><br>
    남의 목록을 보면 그 집 창고가 보인다.<br>
    무게 칸 하나가 이상하다. 『건어물 한 상자 — 70근』. 건어물은 그렇게 안 무겁다.<br><br>
    상자 하나에 사람 하나 무게다.`,
  o:[
    { l:'① 70근짜리 상자를 찾아 연다.', k:'luck', dc:21,
      doom:{ title:'칠십 근', what:'상자 속에 갇혔습니다', dc:17, sec:55,
        text:`상자를 찾았다. 못이 반쯤 빠져 있다. 뚜껑을 들었다.<br><br>안이 비었다. 바닥에 저울추가 하나 있다. 칠십 근짜리. 들여다보는 사이 뒤에서 누가 어깨를 민다.<br>상자 안으로 고꾸라졌다. 뚜껑이 덮인다. 못 박는 소리. 하나, 둘.<br><br>무게를 맞추는 건 행상도 잘한다. 이번엔 이쪽이 무게다.`,
        dieText:`적하 목록의 무게 칸이 맞았다.<br><br>칠십 근. 건어물 한 상자.<br>해무호에 실린 상자 중에 안에서 두드리는 것은 그 하나뿐이었다. 다섯 시 십 분이 지나자 그것도 멈췄다.` },
      ok:`상자를 찾았다. 못이 반쯤 빠져 있다. 뚜껑을 들기 전에 등 뒤부터 봤다.<br><br>아무도 없다. 뚜껑을 들었다. 안에 사람이 웅크리고 있다. 산 사람이다. 입이 묶였다.<br>풀어 주니 그가 덜덜 떨며 목록을 가리킨다. 70근이 석 줄 더 있다고.<br><br>무게가 안 맞는 물건은 물건이 아니다. 목록 넉 줄에 줄을 그었다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 목록 숫자를 다시 더한다.', k:'gaze', dc:20,
      ok:`무게를 다 더했다. 배 한 척 실을 양보다 이백팔십 근이 많다. 70근 넷.<br><br>창고에 있는 70근 상자는 셋이다. 하나는 아직 안 채웠다.<br>목록 맨 밑에 볼펜으로 작게 적혀 있다. 『나머지는 현장에서.』 현장이 여기다.<br><br>목록을 접어 품에 넣었다. 증거는 무게가 제일 정직하다.`,
      ng:`더하는데 숫자가 자꾸 바뀐다. 볼펜 자국 위에 덧쓴 숫자가 겹쳤다.<br><br>셈이 안 선다. 셈에 매달린 사이 사무실 문손잡이가 돌아갔다. 책상 밑으로 들어가 숨을 참았다. 장화가 한참 책상 앞에 서 있었다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-12 } },
    { l:'③ 진짜 건어물 상자만 골라 챙긴다.', k:'sense', dc:19,
      ok:`70근은 피했다. 진짜 건어물 상자를 골랐다. 냄새로 안다. 짠 냄새, 마른 냄새.<br><br>못을 빼고 손을 넣었다. 말린 고기 꾸러미가 나왔다. 장부에 안 적힌 덤까지 들었다. 밀수꾼들도 덤을 준다.<br>상자를 다시 닫았다. 무게가 줄면 누가 안다. 빈자리에 소금 자루에서 한 줌을 덜어 넣었다.`,
      ng:`냄새를 따라갔는데 냄새가 둘이다. 짠 냄새, 그 밑에 다른 냄새.<br><br>연 상자에서 무엇인가 이쪽 손목을 잡았다. 빼냈다. 손등이 못에 길게 그였다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ hp:-24, mind:-10 } }
  ] },

{ at:'B2', t:'6호실 — 단추 장',
  x:`병동에서는 돈이 안 돈다. 단추가 돈다.<br><br>
    환자복에 단추가 다섯. 하나 떼면 종이딱지 한 장, 셋이면 간호사실 열쇠 시간표.<br>
    장터마다 돈이 다르다. 돈이 다르면 셈도 다르다.<br><br>
    6호실 노인이 단추를 한 움큼 쥐고 침대 위에 장을 열었다.`,
  o:[
    { l:'① 단추 셋짜리를 단추 둘에 산다.', k:'luck', dc:20, wake:1,
      ok:`셋을 떼어 내밀지 않았다. 하나만 내밀었다. 노인이 웃는다. 하나로는 안 된다고.<br><br>하나를 더 보탰다. 대신 실이 길게 달린 단추로. 여기서는 실이 귀하다. 단추보다 귀하다. 노인이 실을 손가락에 감아 본다. 고개를 끄덕인다.<br>시간표가 넘어왔다. 단추 둘에 셋짜리 물건을 샀다.<br><br>처음 보는 장에서 처음 보는 돈으로 값을 깎았다. 셈이 장을 가리지 않게 됐다.`,
      ng:`셋을 떼어 내밀었다. 노인이 받는다. 그리고 하나를 더 달라고 한다. 값이 올랐다고.<br><br>흥정하는 사이 정각이 됐다. 계수기 소리가 복도에서 온다. 단추 없는 환자복 앞섶이 벌어졌다. 간호사가 그 앞섶을 오래 봤다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-12 } },
    { l:'② 노인의 장부를 훔쳐본다.', k:'gaze', dc:19,
      ok:`노인 베개 밑에 종이가 있다. 누가 단추를 얼마에 냈는지 적었다. 장사꾼은 장부를 꼭 둔다.<br><br>지난주 줄에 이름 대신 번호가 적혀 있다. 번호 옆에 『퇴원』. 퇴원한 번호는 다 같은 시각이다. 정각.<br>장부를 덮어 돌려줬다. 노인이 단추 하나를 거저 줬다. 아무 말도 안 했다는 값이다.`,
      ng:`베개 밑에 손을 넣는데 노인이 손목을 잡는다. 늙은 손이 아니다.<br><br>남의 장부를 보는 건 장사꾼끼리 제일 큰 실례다. 노인이 손목을 놓을 때까지 손이 하얗게 질렸다. 손가락이 한참 펴지지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-12 } }
  ] },

{ at:'B3', t:'통로 — 판매 수레',
  x:`판매 수레가 통로를 밀고 온다. 삶은 달걀, 김밥, 말린 고기.<br><br>
    수레 미는 사람은 앞치마를 둘렀다. 칸을 넘을 때마다 얼굴이 바뀐다. 그런데 수레 미는 손목 힘은 같다. 같은 업이다.<br>
    가격표 맨 밑 줄에 이렇게 적혀 있다. 『내리는 문 — 시가』.<br><br>
    시가는 파는 사람이 사는 사람을 보고 정하는 값이다.`,
  o:[
    { l:'① 시가를 묻는다.', k:'luck', dc:21,
      ok:`얼마냐고 물었다. 수레 미는 사람이 웃는다. 얼굴이 하나 바뀐다.<br><br>"얼마 내실 수 있는데요." 장사꾼은 그 말을 할 때 손님 주머니를 본다. 이쪽 주머니를 봤다.<br>주머니를 털어 보이지 않았다. 대신 보따리를 반만 열어 보였다. 반만 보이면 사는 쪽이 값을 쥔다.<br><br>수레 미는 사람이 밑칸에서 종이 한 장을 꺼냈다. 기관실까지 연결문 여는 순서가 적혀 있다. 문은 안 팔고 순서를 팔았다.`,
      ng:`물었다. 수레 미는 사람이 값을 부른다. 이쪽 얼굴이라고.<br><br>거절했다. 수레가 지나간다. 지나가며 바퀴가 발등을 밟았다. 한참 걸었는데 발등이 계속 아팠다.<br>수레 손잡이에 손거울이 하나 달려 있었다. 이쪽 얼굴이 거기 남아 있는 것 같았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-20, spirit:-16 } },
    { l:'② 등짐 매듭을 보여 같은 업으로 인사한다.', k:'bond', dc:20, wake:1,
      ok:`보따리 끈을 풀어 매듭을 보였다. 등짐 지는 사람끼리 쓰는 매듭이다.<br><br>수레 미는 사람 손이 멈춘다. 얼굴이 바뀌다 만다. 처음으로 한 얼굴로 오래 있었다. 지친 얼굴이다.<br>밑칸에서 말린 고기 한 줄을 꺼내 준다. 값은 안 받는다. 내리는 문은 판 적이 없다고 한다. 시가는 미끼라고.<br><br>얼굴은 바뀌어도 매듭은 안 바뀐다. 물건이 아니라 업을 알아보는 눈이 하나 생겼다.`,
      ng:`매듭을 보였는데 수레 미는 사람이 그 매듭을 그대로 따라 묶는다. 이쪽보다 잘.<br><br>얼굴이 이쪽 얼굴로 바뀐다. 같은 업이 아니라 같은 사람이 되려는 것이다. 보따리를 끌어안고 물러섰다. 등에 식탁 모서리가 박혔다.`,
      win:{ exp:22, dream:3, item:'말린 고기' }, lose:{ hp:-22, mind:-14 } },
    { l:'③ 수레 밑칸을 턴다.', k:'hide', dc:21,
      ok:`수레가 식탁 사이에 끼어 멈출 때를 기다렸다. 몸을 낮췄다.<br><br>밑칸에 손을 넣었다. 장사꾼은 진짜 물건을 밑칸에 둔다. 손에 걸린 건 승무원 열쇠 하나와 접힌 시간표 한 장. 위칸 달걀보다 비싼 물건이다.`,
      ng:`손을 넣는데 수레가 다시 움직인다. 손목이 바퀴 축에 끼었다.<br><br>수레 미는 사람이 내려다본다. 얼굴이 여럿 겹쳐 보인다. 수레를 뒤로 한 번 민다. 축이 풀렸다. 손목이 퉁퉁 부었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-10 } }
  ] },

{ at:'B', t:'철문 앞 — 펴진 손바닥',
  x:`잠긴 철문 앞에 문지기가 앉았다. 모자를 눌러썼다.<br><br>
    손바닥이 위로 펴져 있다. 무엇을 달라는 말은 안 한다. 손바닥만 편다.<br>
    그 손은 매일 봤다. 장터 입구마다 그런 손이 있다.<br><br>
    너무 많이 주면 더 달라 하고, 너무 적게 주면 문을 안 연다.`,
  o:[
    { l:'① 손바닥에 맞는 것을 얹는다.', k:'luck', dc:21,
      ok:`손바닥을 봤다. 굳은살이 엄지 밑에만 있다. 동전을 세는 손이 아니다. 무엇인가 쥐는 손이다. 돈은 안 받는다.<br><br>보따리에서 끈 한 타래를 꺼내 얹었다. 쥘 것을 줬다. 손이 끈을 쥐고 오므라든다. 문이 열린다.<br><br>값은 물건이 아니라 받는 손이 정한다.`,
      ng:`동전을 얹었다. 손이 그대로 펴져 있다. 하나 더. 그대로.<br><br>다섯 닢째에 손이 움직였다. 동전을 쥐지 않고 이쪽 손목을 쥐었다. 모자 밑에서 웃는다.<br>손목을 빼는 데 보따리 끈이 다 끊어졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 손바닥을 두고 짐 들이는 문을 찾는다.', k:'sense', dc:20,
      ok:`돌아섰다. 문지기가 있는 문은 정문이다. 장터엔 늘 뒷문이 있다. 짐 들이는 문.<br><br>벽을 따라 돌았다. 바닥에 수레 바퀴 자국이 난 데가 있다. 바퀴 자국 끝에 낮은 쪽문. 잠기지 않았다.<br>정문 값은 손님이 치르고 뒷문은 장사꾼이 안다.`,
      ng:`돌았는데 뒷문 앞에도 손바닥이 있다. 같은 모자, 같은 손.<br><br>정문 손바닥과 같은 사람인지 모르겠다. 되돌아가는 사이 정문 손바닥이 사라졌다. 문이 잠겼다. 둘 다 놓쳤다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-12 } }
  ] },

{ at:'B1', t:'어시장 — 큰 저울',
  x:`어시장 바닥에 큰 저울이 있다. 생선 상자를 올려 근을 다는 저울이다.<br><br>
    저울 옆에 노란 비옷 하나가 서서 일행을 하나씩 본다. 올라가 보라고 턱짓한다.<br>
    저울을 보면 추부터 본다. 속이는 저울은 추가 다르다.<br><br>
    아무것도 안 올렸는데 바늘이 반 근 위에 서 있다.`,
  o:[
    { l:'① 비옷 몰래 추를 바꿔 건다.', k:'fix', dc:20,
      ok:`비옷이 다른 데를 볼 때 추 하나를 집어 들었다. 생긴 것보다 가볍다. 속이 비었다.<br><br>보따리에서 비슷한 크기 돌을 꺼내 바꿔 걸었다. 바늘이 영으로 돌아왔다.<br>일행이 하나씩 올라섰다. 다 『빈 상자』 무게로 달렸다. 비옷이 고개를 갸웃하며 다른 데로 갔다.<br><br>저울이 정직하면 사람은 생선 값도 안 나간다.`,
      ng:`추를 집는데 생각보다 무겁다. 손목이 꺾였다.<br><br>추가 바닥에 떨어졌다. 시장 전체가 울렸다. 비옷이 천천히 돌아본다.<br>그 뒤로 일행 모두 저울에 올라가야 했다. 바늘이 일행 하나에서 오래 멈췄다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 턱짓보다 먼저 생선 상자를 올린다.', k:'luck', dc:20,
      ok:`비옷이 턱짓하기 전에 옆 생선 상자를 번쩍 들어 저울에 올렸다. 장터에서는 먼저 올리는 쪽이 셈을 쥔다.<br><br>바늘이 돈다. 비옷이 바늘을 본다. 이쪽은 비옷 손의 장부를 봤다. 근 수 옆에 번호. 번호가 일행 수만큼이다.<br>상자 하나 값에 번호 하나를 지우자고 손짓했다. 비옷이 상자를 끌고 갔다. 번호 하나에 줄이 갔다.<br><br>상자 바닥에서 떨어진 민물고기 하나가 이쪽 발밑에서 팔딱였다.`,
      ng:`상자를 들었는데 바닥이 터졌다. 얼음과 생선이 쏟아진다.<br><br>비옷이 얼음 위에 선 이쪽을 내려다본다. 바늘 대신 이쪽 발목을 본다. 미끄러지며 수조 모서리에 옆구리를 찧었다.`,
      win:{ exp:20, dream:3, item:'민물고기' }, lose:{ hp:-24, mind:-10 } }
  ] },

{ at:'B2', t:'세탁실 — 흰 옷 한 벌',
  x:`세탁실 선반에 흰 옷이 개켜져 있다. 직원복이다. 크기별로, 번호별로.<br><br>
    옷을 보면 옷감부터 본다. 다 같은 흰 천인데 하나만 결이 다르다. 오래 입은 것이다.<br>
    직원복을 입으면 복도를 걸어도 아무도 안 센다. 아마.<br><br>
    구석에서 세탁부가 다림질을 한다. 이쪽을 안 본다.`,
  o:[
    { l:'① 새 옷을 골라 입는다.', k:'luck', dc:22,
      doom:{ title:'몸에 맞는 옷', what:'직원으로 세어지고 있습니다', dc:17, sec:55,
        text:`새 옷을 입었다. 몸에 꼭 맞는다. 너무 꼭 맞는다. 재 본 것처럼.<br><br>단추를 채우자 가슴 명찰에 숫자가 떠오른다. 이쪽 숫자다. 복도에서 딸깍 소리가 온다. 간호사가 이쪽을 보고 고개를 끄덕인다. 동료를 보는 눈이다.<br>소매를 벗으려는데 소매가 팔을 놓지 않는다.<br><br>평생 옷을 팔았다. 사람이 옷에 팔리는 건 처음 본다.`,
        dieText:`정각 점검이 돌았다. 숫자가 맞았다.<br><br>복도 끝에 흰 옷 하나가 더 섰다. 계수기를 쥐었다. 엄지가 자연스럽다.<br>세탁실 선반에 빈칸이 하나 생겼다. 다음 사람 크기로.` },
      ok:`새 옷을 펼쳤다. 입지는 않았다. 몸에 대 보기만 했다. 꼭 맞는다. 너무 꼭 맞는다.<br><br>장사꾼은 맞춘 것처럼 맞는 물건을 의심한다. 누가 이쪽 치수를 먼저 쟀다.<br>새 옷은 개켜 놓고 빨래 바구니에서 직원복 단추 하나만 떼 왔다. 명찰 숫자가 찍힌 단추다.<br><br>복도에서 그걸 쥐고 걸으면 간호사가 고개를 한 번 덜 돌린다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 결이 다른 헌 옷을 집는다.', k:'gaze', dc:20,
      ok:`결이 다른 옷을 집었다. 무릎이 닳았고 소매 끝이 해졌다. 사람이 입었던 옷이다.<br><br>주머니에 쪽지가 있다. 『계단은 4층에서 한 번 끊긴다. 세탁물 투입구.』 옷 주인은 나갔거나 못 나갔다. 어느 쪽이든 쪽지를 남겼다.<br>옷은 입지 않았다. 쪽지만 챙겼다. 쪽지가 옷보다 비쌌다.`,
      ng:`집었는데 옷이 축축하다. 빨지 않은 옷이다. 손바닥에 무엇인가 묻는다.<br><br>냄새를 맡는 순간 세탁부가 고개를 든다. 내려놓으라고 손짓한다. 내려놓기 전에 손등을 빨래 집게로 찍혔다. 집게가 살을 물고 안 놓았다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, mind:-12 } },
    { l:'③ 세탁부와 바깥 옷을 바꾼다.', k:'bond', dc:21,
      ok:`세탁부에게 보따리를 열어 보였다. 바깥 옷 한 벌. 비에 젖었지만 여기 없는 옷이다.<br><br>세탁부가 오래 만진다. 바깥 냄새가 난다. 직원복 하나와 바꿔 줬다. 오래 입은 쪽으로. 새 옷은 주지 말라고 누가 일러둔 것처럼.<br>바깥 옷을 품에 넣는 세탁부 손이 떨렸다. 여기 사람도 바깥을 산다.`,
      ng:`보따리를 열었는데 세탁부가 고개를 젓는다. 바깥 옷은 여기서 값이 없다고. 바깥은 없다고.<br><br>대신 이쪽 소매를 만진다. 지금 입은 것을 원한다. 거절하자 세탁부가 문을 잠근다. 창틀을 넘어 나오다 팔꿈치가 찢어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B3', t:'우편칸 — 무게가 안 맞는 소포',
  x:`우편칸 선반에 소포가 가득하다. 끈으로 묶고 무게를 적었다.<br><br>
    소포는 들어 보면 무게 표가 맞는지 안다. 손이 저울이다.<br>
    하나가 표보다 무겁다. 표에는 『편지 — 두 냥』. 들어 보니 두 근이다.<br><br>
    매듭이 눈에 익다. 등짐 매듭이다.`,
  o:[
    { l:'① 매듭을 풀어 본다.', k:'luck', dc:21, wake:1,
      ok:`등짐 매듭은 한 군데만 당기면 풀린다. 당겼다.<br><br>안에 편지 대신 차표 뭉치가 있다. 다 이 열차 표다. 구멍 하나짜리, 둘짜리. 맨 위에 구멍 없는 표가 한 장. 행선지 칸에 역 이름이 적혀 있다. 끝에서 두 번째 역.<br>그 한 장을 품에 넣고 끈을 다시 묶었다. 조금 가벼워졌다. 손이 저울이니 손이 안다.<br><br>무게가 거짓말을 하는 자리에 물건이 숨는다. 손바닥 저울의 눈금이 한 칸 더 잘아졌다.`,
      ng:`당겼는데 안 풀린다. 당길수록 조인다. 등짐 매듭을 거꾸로 묶었다.<br><br>칼로 끊었다. 안에서 바스락거린다. 편지다. 수백 장. 다 같은 글씨로 『내려 줘』.<br>한 장이 손바닥에 붙었다. 떼어 내는 데 살갗이 같이 벗겨졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-20, spirit:-16 } },
    { l:'② 무게 표를 바꿔 붙인다.', k:'fix', dc:20,
      ok:`무거운 소포 표를 떼어 가벼운 소포에 옮겨 붙였다. 무게가 바뀌면 분류가 바뀐다. 분류가 바뀌면 내리는 역이 바뀐다.<br><br>분류함 행선지 쪽지를 봤다. 무거운 소포는 종착. 가벼운 소포는 그 전 역.<br>일행 짐에도 가벼운 표를 붙였다. 짐이 먼저 내리면 사람도 따라 내릴 구실이 생긴다. 짐 부치는 법은 손이 안다.`,
      ng:`떼는데 표 뒤에 이쪽 이름이 적혀 있다.<br><br>이쪽이 소포였다. 아니면 소포가 될 사람이다. 손이 떨려 표를 떨어뜨렸다. 줍는 사이 분류칸 문이 닫혔다. 문을 여는 데 손톱이 다 깨졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B', t:'긴 계단 — 흘리는 물건',
  x:`뒤에서 발소리가 따라온다. 여럿이다. 가까워진다.<br><br>
    계단이 길다. 등에는 보따리가 있다. 무겁다.<br>
    장터에서 도둑을 만나면 보따리를 안 버린다. 대신 푼다.<br><br>
    쫓는 놈들도 사람이면 줍는다.`,
  o:[
    { l:'① 값나가 보이는 것부터 흘린다.', k:'luck', dc:21,
      ok:`반짝이는 것부터 흘렸다. 유리구슬, 깡통 뚜껑, 닳은 동전. 값나가 보이는 것. 값은 없다.<br><br>발소리가 계단 중간에서 엉킨다. 줍는 소리가 난다. 줍는 손은 못 쫓는다.<br>진짜 값나가는 건 다 등에 남았다. 보이는 값과 진짜 값은 다르다.`,
      ng:`흘렸는데 발소리가 안 멈춘다. 밟고 온다.<br><br>줍지 않는 놈들이다. 시킨 대로만 하는 놈들. 그런 놈들하고는 장사가 안 된다.<br>계단 모서리에 정강이를 찍고 굴렀다. 보따리가 등을 눌렀다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 보따리를 통째로 계단참에 끼운다.', k:'break', dc:20,
      ok:`보따리를 벗어 계단참에 던졌다. 계단 폭에 꼭 맞게 끼었다.<br><br>발소리가 그 앞에서 멈춘다. 넘는 데 시간이 걸린다. 그사이 두 층을 내려갔다.<br>평생 진 가게를 처음으로 내려놓았다. 몸이 가볍다. 아까운 건 나중에 셀 것이다.`,
      ng:`던졌는데 계단참에 안 끼고 굴러 내려간다. 이쪽보다 먼저.<br><br>보따리를 쫓아 뛰다 보따리에 걸렸다. 같이 굴렀다. 일어났을 때 발소리는 바로 위 계단참이었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B1', t:'야적장 — 밀수품 컨테이너',
  x:`열린 컨테이너 안에 물건이 쌓였다. 시계, 라디오, 비단 두루마리. 밀수품이다.<br><br>
    한눈에 값이 보인다. 이 한 칸이면 평생 등짐을 안 져도 된다.<br>
    문에 분필로 적혀 있다. 『05:10 적재』.<br><br>
    문턱 안쪽에 고무장화 발자국이 있다. 들어간 자국만.`,
  o:[
    { l:'① 한 짐 지고 나온다.', k:'luck', dc:22,
      doom:{ title:'한 짐', what:'컨테이너에 갇혔습니다', dc:17, sec:50,
        text:`들어갔다. 비단 한 필, 시계 몇 개. 보따리를 채운다. 손이 멈추지 않는다. 값이 보이면 손이 멈추지 않는다.<br><br>등 뒤에서 문이 밀린다. 바깥에서 빗장 걸리는 소리. 어둠 속에서 시계들이 째깍거린다. 다 같은 시각을 가리키며.<br><br>평생 물건을 졌다. 오늘은 물건과 함께 실린다.`,
        dieText:`해무호 화물칸에 컨테이너 하나가 실렸다.<br><br>적하 목록과 무게가 맞는다. 비단, 시계, 라디오, 그리고 보따리 하나.<br>안에서 시계들이 째깍거렸다. 하나만 멈춰 있었다.` },
      ok:`들어가기 전에 문을 괴었다. 쐐기를 하나 박았다. 남의 창고에 들어갈 때는 먼저 나갈 길을 산다.<br><br>시계 셋만 집었다. 셋 다 같은 시각에 멈춰 있다. 다섯 시 십 분. 고장 난 게 아니라 맞춰 둔 것이다.<br>나오자마자 문이 쐐기를 밀어내며 닫혔다. 아무도 밀지 않았는데.<br><br>쓸모없는 것을 비싸게 들고 나왔다. 그래도 나왔다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 값만 매기고 손대지 않는다.', k:'steady', dc:20,
      ok:`문 밖에서 둘러보기만 했다. 값을 매겼다. 머릿속 장부에 적었다.<br><br>손대지 않은 물건도 쓸 데가 있다. 누가 무엇을 달라고 하면 어디에 무엇이 있는지 안다. 그것도 밑천이다.<br>발자국이 들어가기만 한 문에는 들어가지 않는다.`,
      ng:`둘러보다 발이 저절로 문턱을 넘었다. 한 발.<br><br>문이 움직이는 소리에 뒤로 몸을 던졌다. 문짝 끝이 발등을 찍고 닫혔다. 발등이 시퍼렇게 부었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-12 } },
    { l:'③ 비단 한 필을 경첩 틈에 쑤셔 넣는다.', k:'fix', dc:21,
      ok:`비단 한 필을 꺼내 문 경첩 틈에 쑤셔 넣었다. 문이 끝까지 닫히지 않게.<br><br>05:10에 누군가 이 문을 닫으러 올 것이다. 닫히지 않는 문에는 손이 한 번 더 간다. 한 번 더 가는 손은 시간이 걸린다. 그만큼 배가 늦게 뜬다.<br>남의 장사를 한 시간 늦추는 것도 장사꾼의 수다.`,
      ng:`쑤셔 넣는데 비단이 틈에서 미끄러져 나온다. 너무 매끄럽다.<br><br>그 소리에 컨테이너 안쪽 어둠에서 무엇인가 움직였다. 물건 사이에 회색 비옷이 서 있었다. 처음부터 거기 있었다.<br>뛰었다. 비옷은 뛰지 않았다. 그게 더 무서웠다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B2', t:'매점 창구 — 외상 장부',
  x:`병동 끝 매점 창구가 열려 있다. 아무도 없다. 진열대에 비스킷 봉지, 우유갑, 꿀 봉지.<br><br>
    창구 위에 외상 장부가 펼쳐져 있다. 번호마다 줄이 그어졌다. 다 갚았다는 줄이 아니다. 줄 끝에 『퇴원』.<br>
    맨 끝에 이쪽 번호가 있다. 외상이 적혀 있다.<br><br>
    이쪽은 여기서 아무것도 산 적이 없다.`,
  o:[
    { l:'① 외상을 제값에 갚는다.', k:'luck', dc:20, wake:1,
      ok:`보따리에서 물건 하나를 꺼내 창구에 올렸다. 외상 값에 맞는 것으로. 값은 손이 맞췄다.<br><br>장부 이쪽 번호 옆에 저절로 줄이 그어진다. 『퇴원』이 아니라 『완납』. 처음 보는 줄이다.<br>창구 밑에서 꿀 봉지 하나가 굴러 나왔다. 덤이다. 이 매점도 덤을 준다.<br><br>갚을 까닭 없는 빚을 값으로 지웠다. 빚에도 값이 있다는 걸 손이 알았다. 셈하는 손이 한 뼘 넓어졌다.`,
      ng:`올렸는데 장부 숫자가 오른다. 이자다.<br><br>하나 더 올렸다. 또 오른다. 보따리 반이 창구 위로 갔다. 숫자는 끝내 안 줄었다. 외상은 장사꾼을 제일 빨리 죽인다.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 장부에서 제 장만 뜯어 간다.', k:'hide', dc:20,
      ok:`창구 너머로 몸을 넣어 장부 마지막 장을 조용히 뜯었다. 접어서 신발 속에 넣었다.<br><br>장부에 없는 사람에게는 빚도 없다. 진열대 물은 제값을 놓고 한 병 집었다. 빚 없이 나가려면 빚 없이 사야 한다.`,
      ng:`뜯는데 종이가 질기다. 소리가 크게 났다.<br><br>창구 안쪽 어둠에서 누가 일어선다. 앞치마에 번호가 찍혔다. 이쪽 손을 잡아 장부에 대고 꾹 누른다. 손바닥에 잉크가 묻었다. 아무리 문질러도 안 지워진다.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B3', t:'차장실 — 구간 변경',
  x:`차장실 창구가 반쯤 열려 있다. 안에서 차장이 표 묶음을 센다.<br><br>
    창구에 종이가 붙었다. 『차내 발권. 구간 변경 가능.』 구간 변경이면 내리는 역을 바꿀 수 있다는 뜻이다.<br>
    값은 안 적혀 있다.<br><br>
    행상은 값이 안 적힌 창구 앞에서 제일 오래 서 있는다.`,
  o:[
    { l:'① 구간을 반만 바꿔 달라고 흥정한다.', k:'luck', dc:21,
      ok:`종착까지 말고 그 전 역까지만 바꿔 달라고 했다. 반 구간이면 반값이다.<br><br>차장이 고개를 든다. 얼굴이 흐리다. 흥정해 오는 손님은 처음 본다는 얼굴이다. 반값으로 무엇을 낼 거냐고 묻는다.<br>보따리에서 말린 고기 한 줄을 꺼냈다. 이 열차에서 제일 귀한 것은 밥이다. 식당칸 음식은 아무도 안 먹는다.<br><br>차장이 받는다. 표에 새 구멍이 하나 뚫렸다. 다른 모양 구멍이다.`,
      ng:`반만 바꿔 달라고 했다. 차장이 웃는다. 반 구간은 반 사람이 내리는 표라고.<br><br>표에 구멍이 반쯤 뚫린다. 몸이 반쯤 저리다. 왼팔이 한참 남의 팔 같았다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 표 세는 소리로 손님 수를 셈한다.', k:'sense', dc:20,
      ok:`창구 앞에서 표 세는 소리를 들었다. 남의 돈 세는 소리로 그날 장사를 안다.<br><br>한 묶음에 서른. 묶음이 일곱. 이 열차 표가 이백십 장이다. 객차 좌석은 백팔십. 서른 장이 남는다. 서른은 좌석 없는 손님이다.<br>서른이 어디 앉았을지 생각했다. 객차 사이, 화물칸, 지붕. 일행에게 칸 사이를 지날 때 뒤를 보라고 일렀다.`,
      ng:`듣는데 세는 소리가 멈춘다. 차장이 창구 너머로 이쪽을 센다.<br><br>하나. 이쪽 표에 손이 뻗는다. 물러서다 객차 문에 손가락이 끼었다. 손톱이 들렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B', t:'은신처 — 새 동전 일곱 닢',
  x:`일행 하나 주머니에서 짤랑 소리가 난다. 들어올 때는 빈 주머니였다.<br><br>
    동전 소리로 몇 닢인지 안다. 일곱 닢. 새 동전 소리다. 닳은 동전과 새 동전은 소리가 다르다.<br>
    아까 문지기 손바닥 옆에 놓여 있던 동전도 새것이었다.<br><br>
    누가 그를 샀다. 얼마에 샀는지는 안다.`,
  o:[
    { l:'① 장사꾼 버릇이라며 한 닢만 바꾸자고 한다.', k:'luck', dc:21, wake:1,
      ok:`닳은 동전 하나를 꺼내 보였다. 새것과 바꾸자고, 장사꾼 버릇이라고.<br><br>그가 망설이다 하나를 꺼낸다. 받아서 손톱으로 테두리를 긁었다. 테두리에 숫자가 새겨져 있다. 문 번호다. 동전이 아니라 표식이다.<br>바꾼 동전은 돌려주지 않았다. 그는 아무 말도 못 했다. 그를 산 쪽의 표식을 이쪽이 쥐었다.<br><br>값으로 사람 속을 셌다. 사람도 사고 팔린다. 그 값을 읽는 손이 하나 생겼다.`,
      ng:`바꾸자고 했는데 그가 웃으며 주머니를 누른다. 소리가 멎는다.<br><br>그다음부터 그는 주머니를 쥐고 걸었다. 쥐고 걷는 사람은 언젠가 놓는다. 그때가 문 앞이었다. 동전이 바닥에 떨어지자 문 너머가 조용해졌다. 다들 뛰었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 그보다 비싼 값을 부른다.', k:'bond', dc:20,
      ok:`따로 불러 말했다. 일곱 닢이면 싸게 팔린 거라고. 이쪽이 더 주겠다고.<br><br>그가 놀란다. 팔린 걸 들킨 것보다 싸게 팔렸다는 말에 더 놀란다. 사람은 제 값이 깎이면 화가 난다.<br>그가 털어놓았다. 정각에 문 하나를 열어 두라고 했다고. 그 문을 거꾸로 썼다. 열어 둔 문으로 이쪽이 먼저 나갔다.`,
      ng:`더 주겠다고 했다. 그가 얼마냐고 묻는다. 이쪽 보따리를 본다. 보따리 전부를 달라고 한다.<br><br>거절했다. 그는 원래 값으로 돌아갔다. 정각에 등 뒤 문이 열렸다. 등에 무엇인가 날아와 꽂혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'③ 그가 조는 사이 동전을 바꿔치기한다.', k:'hide', dc:19,
      ok:`그가 조는 사이 주머니에 손가락 둘을 넣었다. 새 동전 일곱 닢을 꺼내고 닳은 동전 일곱 닢을 넣었다. 소리는 같다. 무게는 조금 다르다.<br><br>그가 깨서 주머니를 만진다. 모른다. 정각에 그가 동전을 내밀었을 때 문 너머 손은 받지 않았다. 표식이 아니니까.<br>새 동전은 이쪽이 쥐었다. 언제 내밀지는 이쪽이 정한다.`,
      ng:`손가락을 넣는데 그가 눈을 뜬다. 자는 척이었다.<br><br>둘 다 아무 말 안 했다. 그 뒤로 둘 다 안 잤다. 밤이 길었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B1', t:'방파제 아래 — 뱃삯',
  x:`방파제 아래 작은 배에 사공이 앉아 있다. 우산 쓴 남자가 댄다던 배가 아니다. 다른 배다.<br><br>
    사공이 손가락 다섯을 편다. 다섯 시가 넘었다. 해무호 고동이 한 번 운다.<br>
    일행은 다섯이다.<br><br>
    다섯이 값인지, 다섯이 물건인지 아직 모른다.`,
  o:[
    { l:'① 타기 전에 내리는 값까지 정한다.', k:'luck', dc:21,
      ok:`오르기 전에 값을 물었다. 내리는 값까지. 배는 탈 때보다 내릴 때 비싸다.<br><br>사공이 웃는다. 처음 묻는 놈이라고. 손가락 다섯을 하나씩 접는다. 남은 건 엄지 하나. 하나 값이면 다섯을 내려 주겠다고.<br>보따리에서 값나가는 마지막 것을 꺼냈다. 탈 때 반, 내릴 때 반이라고 했다. 사공이 고개를 끄덕였다.<br><br>반을 뒤에 받는 사공은 끝까지 노를 젓는다.`,
      ng:`묻기 전에 일행이 먼저 올라탔다. 값을 안 정한 배다.<br><br>배가 방파제에서 떨어지자 사공이 손을 편다. 바다 한가운데 값은 사공이 부른다. 보따리를 통째로 내줬다. 내주다 손가락이 노에 찧였다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 사공의 손을 본다.', k:'gaze', dc:20,
      ok:`사공 손을 봤다. 노를 쥔 굳은살이 없다. 손바닥이 하얗다. 물에 오래 불은 손이다.<br><br>노 젓는 손이 아니다. 사람을 물에 내리는 손이다. 이 배에는 안 탔다.<br>방파제를 따라 걸었다. 우산 쓴 남자의 배는 반대편 끝에 매여 있었다. 비었지만 노는 있었다.`,
      ng:`손을 보다 눈이 마주쳤다. 사공이 손을 거둔다. 그리고 배에서 일어선다. 키가 크다.<br><br>방파제 돌 위로 올라온다. 물이 따라 올라온다. 뒷걸음질 치다 미끄러졌다. 바닷물에 무릎까지 빠졌다가 기어올랐다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B2', t:'한방 처치실 — 백 칸 서랍',
  x:`처치실 벽에 약재 서랍이 백 칸이다. 칸마다 이름표가 붙었다.<br><br>
    약재를 지고 고개를 넘어 본 적이 있다. 이름은 몰라도 냄새는 안다.<br>
    이름표와 냄새가 안 맞는 칸이 많다. 누가 일부러 바꿔 놓았다.<br><br>
    진짜 약을 찾는 사람을 헷갈리게 하려고.`,
  o:[
    { l:'① 이름표 말고 냄새로 찾는다.', k:'luck', dc:20,
      ok:`서랍을 하나씩 반만 열고 코를 댔다. 이름표는 안 봤다.<br><br>쉰 몇째 칸에서 손이 멈췄다. 장날 약전 골목 냄새다. 진짜 약초다. 한 뭉치 쥐었다. 다른 칸은 다 말린 잡풀이다.<br>이름표를 바꾼 사람도 냄새까지는 못 바꿨다.`,
      ng:`냄새를 맡다가 한 칸에서 코가 얼었다. 마취 냄새다.<br><br>머리가 핑 돈다. 서랍장을 짚고 버텼다. 서랍 몇 개가 쏟아지며 소리가 복도까지 갔다. 딸깍 소리가 이쪽으로 방향을 틀었다.`,
      win:{ exp:18, dream:3, item:'약초 뭉치' }, lose:{ hp:-20, mind:-16 } },
    { l:'② 이름표를 냄새대로 바로 붙인다.', k:'fix', dc:21,
      ok:`냄새대로 이름표를 하나씩 바로 붙였다. 오래 걸렸다.<br><br>마지막 이름표를 붙이자 서랍장 밑 바닥 판이 덜컥 들린다. 칸이 맞아야 열리는 장이다. 밑에 아래층 처치실로 약재를 내리는 통로가 있었다. 사람 하나 들어갈 너비다.<br>물건을 제자리에 두는 건 장사꾼이 매일 하는 일이다.`,
      ng:`붙이는 사이 정각이 됐다.<br><br>딸깍 소리가 처치실 앞에 섰다. 서랍장 뒤로 숨었다. 간호사가 서랍을 하나씩 열어 센다. 이쪽이 붙인 이름표를 하나씩 도로 뗀다. 다 떼고 나갈 때까지 숨을 못 쉬었다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B3', t:'화물칸 — 짐표 열한 장',
  x:`화물칸에 짐이 쌓였다. 트렁크, 보따리, 자루. 짐표가 하나씩 붙었다.<br><br>
    짐 싼 것을 보면 싼 사람을 안다. 급한 사람, 꼼꼼한 사람, 처음 싸 본 사람.<br>
    트렁크 하나가 이상하다. 짐표가 열한 장 붙었다. 이름이 다 다르다.<br><br>
    싼 솜씨는 하나다.`,
  o:[
    { l:'① 같은 솜씨로 잠금쇠를 연다.', k:'luck', dc:21,
      ok:`잠금쇠가 장사꾼 솜씨다. 한쪽을 누르고 비틀면 열린다. 같은 솜씨는 같은 손으로 연다.<br><br>안에 옷이 열한 벌. 크기가 다 다르다. 소매마다 승객 명단 한 줄이 꿰매져 있다. 열한 줄 중 일곱에 줄이 그어졌다.<br>빈 소매가 다섯 있다. 아직 아무 이름도 안 꿰맸다.<br><br>빈 소매 다섯을 칼로 잘라 냈다. 꿰맬 자리가 없으면 못 꿰맨다.`,
      ng:`비틀었는데 잠금쇠가 안쪽에서 잡힌다.<br><br>트렁크 안에서 무엇인가 쇠를 붙들고 있다. 손가락 끝이 틈 사이로 보인다. 놓고 물러났다.<br>트렁크가 한참 덜컹거리다 조용해졌다. 그 조용함이 열차 끝까지 따라왔다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 짐표 한 장을 떼어 제 보따리에 붙인다.', k:'hide', dc:20,
      ok:`트렁크 짐표 한 장을 떼어 이쪽 보따리에 붙였다. 같은 솜씨로 싼 것처럼 끈도 다시 맸다.<br><br>화물칸을 지나던 승무원이 보따리를 본다. 짐표를 본다. 건드리지 않는다. 그 손님 짐은 아무도 안 건드린다.<br>보따리를 지고 다음 칸으로 갔다. 아무도 이쪽 짐을 묻지 않았다.`,
      ng:`붙였는데 짐표 이름이 저절로 바뀐다. 이쪽 이름으로.<br><br>그 손님 짐에 이쪽 이름이 붙었다. 이제 그 손님이 짐을 찾으러 올 것이다. 떼어 내려니 짐표가 손톱 밑으로 파고든다. 손끝이 다 터졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'쉬는 자리 — 마지막 덤',
  x:`숨을 데를 찾아 다들 털썩 앉았다.<br><br>
    보따리가 많이 줄었다. 먹을 것은 셋이 먹을 만큼 남았다. 사람은 다섯이다.<br>
    줄 때는 덤을 얹는다. 장날 버릇이다.<br><br>
    지금 덤을 얹으면 제 몫이 없다.`,
  o:[
    { l:'① 그래도 덤을 얹는다.', k:'luck', dc:20, wake:1,
      ok:`한 사람씩 몫을 주고 끝에 조금씩 덤을 얹었다. 제 몫에서 덜어서.<br><br>다들 받는다. 하나가 덤을 도로 돌려준다. 다른 하나가 제 몫 반을 떼어 준다. 덤은 돌아온다. 오래 안 걸렸다.<br>보따리를 다시 묶으려니 바닥에 꿀 한 줌이 남아 있다. 넣은 기억이 없다.<br><br>남는 게 없는 장사가 사람을 남겼다. 무엇을 팔았는지보다 누구에게 팔았는지 세는 셈이 손에 붙었다.`,
      ng:`덤을 얹다 보니 제 몫이 바닥났다.<br><br>다들 배를 채웠다. 혼자 빈속이다. 일어설 때 무릎이 떨렸다. 덤이 돌아오는 데는 시간이 걸린다. 오늘은 그 시간이 없었다.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' }, lose:{ hp:-20, mind:-12 } },
    { l:'② 내일 몫을 묶어 두고 나눈다.', k:'steady', dc:19,
      ok:`오늘 먹을 만큼만 나눴다. 나머지는 끈으로 묶어 보따리 맨 밑에 넣었다.<br><br>다들 투덜댄다. 장사 밑천은 끝까지 안 먹는다. 이튿날 그 밑천이 다섯 사람을 일으켰다.`,
      ng:`남겼는데 남긴 것을 두고 말이 길어진다. 누가 더 배고프냐로.<br><br>끝내 아무도 제대로 못 먹었다. 묶어 둔 꾸러미만 무거웠다.`,
      win:{ exp:14, dream:2, item:'말린 고기' }, lose:{ mind:-14, spirit:-12 } }
  ] },

{ at:'B', t:'빈 사무실 — 장부와 금고',
  x:`빈 사무실에 금고가 있다. 다이얼이 셋.<br><br>
    책상 위에 장부가 펼쳐졌다. 남의 장부는 그 집 속이다.<br>
    장부 맨 뒷장에 날짜 셋에만 동그라미가 쳐 있다.<br><br>
    셋 다 같은 시각이다.`,
  o:[
    { l:'① 동그라미 친 날의 돈을 더해 돌린다.', k:'luck', dc:21,
      ok:`날짜 셋을 차례로 돌렸다. 안 열린다.<br><br>장사꾼은 날짜보다 금액을 센다. 동그라미 친 날 금액만 더했다. 세 자리씩 셋. 돌렸다. 딸깍.<br>금고 안에 돈은 없다. 열쇠 하나와 표 한 장.<br><br>이 장사의 진짜 밑천은 나가는 길이었다.`,
      ng:`돌리는데 다이얼이 한 칸씩 저절로 밀린다.<br><br>누가 안에서 돌린다. 셋째 다이얼이 이쪽 손가락을 물었다. 톱니에 손끝이 찍혔다. 장부 위에 피가 떨어졌다. 동그라미가 하나 더 생겼다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 금고를 기울여 바닥으로 연다.', k:'break', dc:21,
      ok:`금고 밑에 쇠지레를 넣고 들었다. 기울었다. 생각보다 가볍다.<br><br>가벼운 금고는 비었거나 바닥이 빠진다. 뒤집으니 바닥 판이 헐겁다. 나사 넷을 칼끝으로 풀었다.<br>정문으로 안 열리는 가게는 뒤로 연다. 안에 열쇠 하나가 굴러 나왔다.`,
      ng:`들었는데 금고가 이쪽으로 넘어왔다.<br><br>발등을 찍었다. 소리가 건물 전체를 울렸다. 계단 아래서 발소리가 올라오기 시작했다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-28, mind:-10 } },
    { l:'③ 장부를 들고 다른 창고를 찾는다.', k:'sense', dc:19,
      ok:`금고는 두고 장부만 품에 넣었다. 금고는 하나지만 장부에는 창고가 여럿이다.<br><br>장부에 적힌 둘째 창고가 이 건물 지하다. 내려가니 문이 열려 있다. 선반에 소금 덩이가 쌓였다. 장부에는 『폐기』라고 적혔다.<br>버린다고 적은 물건이 제일 오래 남는다.`,
      ng:`품에 넣는데 장부에서 종이 한 장이 떨어진다. 이쪽 일행 명단이다. 값이 적혔다.<br><br>그 값을 보느라 시간을 썼다. 계단 아래 발소리가 들렸을 때는 늦었다. 창문으로 나왔다. 물받이를 붙잡고 내려오다 손바닥이 찢어졌다.`,
      win:{ exp:16, dream:2, item:'소금 덩이' }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'골목 좌판 — 이름 값',
  x:`비 오는 골목 끝에 좌판 하나가 섰다. 장물 받는 좌판이다. 냄새로 안다.<br><br>
    좌판 임자는 이쪽 보따리를 안 본다. 이쪽 얼굴을 본다. 이름을 사겠다고 한다. 이름 하나에 나가는 길 하나.<br>
    좌판 뒤 벽에 이름표가 줄줄이 걸렸다. 글자 쪽이 벽을 향했다.<br><br>
    행상은 평생 물건 값을 매겼다. 제 이름 값은 매겨 본 적이 없다.`,
  o:[
    { l:'① 이름 값을 묻는다.', k:'luck', dc:22,
      doom:{ title:'이름 값', what:'이름이 넘어가고 있습니다', dc:18, sec:50,
        text:`얼마냐고 물었다. 묻는 순간 흥정은 시작됐다.<br><br>좌판 임자가 열쇠 하나를 내민다. 크다. 손이 저절로 간다. 받는 순간 입 안에서 무엇인가 빠져나간다. 제 이름을 불러 보려는데 첫 글자가 안 나온다.<br>벽에 이름표 하나가 걸린다. 벽을 향해서.<br><br>평생 물건을 넘겼다. 넘어가는 쪽이 되어 본 적은 없다.`,
        dieText:`열쇠는 맞았다. 문이 열렸다.<br><br>문 밖으로 나간 사람을 아무도 부르지 못했다. 이름이 없으니까.<br>좌판 임자는 새 이름표를 벽에 걸고 다음 손님을 기다린다.` },
      ok:`얼마냐고 물었다. 좌판 임자가 열쇠 하나를 내민다.<br><br>받지 않았다. 물어만 봤다. 시세를 아는 것과 파는 것은 다르다. 그 값이면 이름 말고 다른 것도 팔린다는 걸 알았다.<br>보따리에서 길에서 주운 이름표 하나를 꺼냈다. 앞서 간 누가 흘린 것이다. 좌판 임자가 들여다보고 받는다.<br><br>장물은 장물로 산다. 열쇠가 넘어왔다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 이름은 안 판다며 다른 물건을 권한다.', k:'bond', dc:20,
      ok:`"그건 안 파는 물건이오." 대신 보따리를 열었다. 쓰임을 말하고 흠도 말했다.<br><br>흠까지 말하니 좌판 임자가 믿는다. 끈 한 타래와 기름천 하나를 샀다. 비 오는 골목에서 제일 잘 팔리는 물건이다.<br>값으로 골목 뒷길을 알려 줬다. 원하는 것 말고 필요한 것을 팔았다.`,
      ng:`권했는데 좌판 임자가 고개를 젓는다. 원하는 것 말고는 안 산다고.<br><br>다시 이쪽 얼굴을 본다. 물러나는 동안 등 뒤로 누가 제 이름을 부르는 것 같았다. 대답하지 않으려고 입술을 깨물었다. 피가 났다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, spirit:-16 } },
    { l:'③ 벽의 이름표 하나를 뒤집어 본다.', k:'gaze', dc:21,
      ok:`좌판 임자가 손님을 볼 때 벽의 이름표 하나를 뒤집었다.<br><br>아는 이름이다. 앞서 들어간 사람 중 하나다. 이름표 뒤에 적혀 있다. 『나간 문 — 북쪽 셔터.』 산 이름마다 판 길이 적혀 있다.<br>이름표를 도로 뒤집었다. 길은 공짜로 알았다. 이름을 판 사람의 값으로.`,
      ng:`뒤집는데 이름표가 뜨겁다.<br><br>손바닥에 글자가 찍혔다. 남의 이름이다. 좌판 임자가 웃는다. 이제 그 이름 값도 이쪽이 치를 차례라고. 손바닥 글씨가 한참 안 지워졌다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B', t:'내려가는 계단 — 셈',
  x:`내려가기 전에 보따리를 열고 셈을 했다.<br><br>
    들고 들어온 것, 쓴 것, 바꾼 것, 버린 것. 처음보다 반이 줄었다.<br>
    그런데 값은 줄지 않았다.<br><br>
    셈이 이상하다.`,
  o:[
    { l:'① 처음부터 다시 셈한다.', k:'luck', dc:20, wake:1,
      ok:`하나씩 짚어 다시 셈했다. 물건 수는 반인데 남은 것이 다 값나가는 것이다. 싼 것을 내주고 비싼 것을 받은 셈이다. 매번.<br><br>손이 저 혼자 흥정을 했다. 머리가 알기 전에.<br><br>가벼워질수록 값이 오르는 보따리. 등짐 대신 셈을 지고 다니는 법이 손에 익었다.`,
      ng:`다시 세니 하나가 빈다.<br><br>세 번 세면 세 번 다르다. 셈이 흔들리면 사람도 흔들린다. 계단 첫 칸에 한참 주저앉아 있었다.`,
      win:{ exp:22, dream:4 }, lose:{ mind:-14, spirit:-12 } },
    { l:'② 셈을 덮고 내려간다.', k:'steady', dc:19,
      ok:`셈을 덮었다. 남는 건 남는 것이다.<br><br>보따리를 묶어 등에 지니 처음 들어올 때와 무게가 같다. 이상하다. 생각하지 않기로 했다. 계단을 내려갔다.`,
      ng:`덮었는데 자꾸 마음에 걸린다.<br><br>계단 몇 칸마다 서서 보따리를 만져 봤다. 발을 헛디뎌 난간에 옆구리를 찧었다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-20, mind:-12 } }
  ] }

]);

// ==========================================
// 🔮 점술가 (fortune) · 마력
// ==========================================
kJob('fortune', 'B', [

{ at:'B', t:'빗속 — 별이 없는 하늘',
  x:`비구름이 하늘을 덮었다. 별이 하나도 없다.<br><br>
    점술가는 별을 보고 길을 잡는 사람이다. 거리에는 네온이 별 대신 떠 있다. 붉은 것, 푸른 것, 글자 하나가 나간 것. 깜빡이는 간격이 제각각이다.<br>
    뒤쪽 골목에서 호루라기 소리가 난다.<br><br>
    길을 골라야 한다.`,
  o:[
    { l:'① 네온으로 별자리를 짓는다.', k:'luck', dc:20, wake:1,
      ok:`깜빡이는 간판을 별로 봤다. 오래 켜진 것은 밝은 별, 자주 꺼지는 것은 흐린 별.<br><br>이어 보니 국자가 나온다. 손잡이 끝이 가리키는 쪽에 불 꺼진 간판이 하나 있다. 그 아래 골목이 비었다. 호루라기 소리는 반대쪽에서 났다.<br><br>하늘이 없으면 땅의 불빛을 읽는다. 별을 보던 눈이 사람이 켠 불에서도 갈래를 보기 시작했다.`,
      ng:`잇는데 간판 하나가 꺼졌다 켜질 때마다 별자리가 바뀐다.<br><br>국자가 뒤집혔다. 뒤집힌 국자를 따라간 골목 끝에 호루라기를 문 사람이 서 있었다. 돌아서 뛰다 물웅덩이에 발목을 접질렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 마력을 실어 산가지를 던진다.', k:'gaze', dc:20, cost:{ mana:22 },
      ok:`처마 밑에서 산가지 다섯 개에 마력을 흘려 넣고 던졌다.<br><br>젖은 바닥에서 산가지가 한 번 돌고 나란히 눕는다. 빗물이 흐르는 방향과 반대다. 물을 거슬러 누운 괘는 거슬러 가라는 뜻이다.<br>빗물이 흘러오는 쪽, 언덕 위 골목으로 갔다. 호루라기 소리가 아래로 멀어졌다.<br><br>마력을 쓴 괘는 핑계가 아니라 대답이다. 값이 비쌀 뿐이다.`,
      ng:`마력을 흘리는데 빗물이 마력을 먹는다. 산가지가 젖은 나무토막이 됐다.<br><br>아무 데도 안 가리킨다. 마력만 빗물에 씻겨 갔다. 머리가 띵하다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B1', t:'3번 창고 — 양동이 물',
  x:`창고 바닥 한가운데 양동이가 놓여 있다. 회색 비옷이 들고 다니던 것이다.<br><br>
    물이 반쯤 찼다. 걸레 한 장이 걸쳐 있다. 물이 너무 맑다. 바닥을 닦은 물인데.<br>
    물거울로 먼 데를 보는 법을 안다.<br><br>
    이렇게 맑은 물은 오랜만이다.`,
  o:[
    { l:'① 양동이 물을 들여다본다.', k:'luck', dc:22,
      doom:{ title:'걸레 물', what:'양동이 물에 얼굴이 붙었습니다', dc:17, sec:55,
        text:`들여다봤다. 물에 창고 천장이 비친다. 그리고 이쪽 얼굴.<br><br>비친 얼굴 뒤로 회색 비옷이 서 있다. 돌아보지 않았다. 물속 비옷이 걸레를 집는다. 이쪽 뒤통수를 누른다. 물속에서.<br>얼굴이 물에 닿는다. 양동이는 반밖에 안 찼는데 바닥이 없다.<br><br>남의 앞날은 물에 비춰 본다. 제 앞날을 비춰 보면 그 물에 빠진다. 점술가는 그걸 알았다.`,
        dieText:`양동이가 다시 창고 바닥에 놓였다.<br><br>물이 조금 늘었다. 여전히 맑다.<br>회색 비옷이 걸레를 짜서 양동이에 걸쳐 둔다. 바닥 한 칸이 깨끗해졌다.` },
      ok:`들여다봤다. 이쪽 얼굴 너머로 창고 바닥이 비친다. 지금 바닥이 아니다. 새벽이 지난 바닥이다.<br><br>바닥에 물자국이 한 줄 나 있다. 쪽문 쪽에서 셔터 쪽으로. 비옷이 닦으며 지나간 길이다. 셔터 앞은 맨 마지막에 닦는다.<br><br>눈을 뗐다. 비옷이 닦을 순서를 알았다. 닦기 전의 길로 다니면 된다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 걸레를 짜서 물을 가늠한다.', k:'sense', dc:20,
      ok:`걸레를 짰다. 물이 손목을 타고 내려간다. 냄새가 없다. 바닷물도 고인 물도 아니다.<br><br>냄새 없는 물은 길어 온 물이 아니라 받은 물이다. 창고 안 어딘가에 빗물 받는 데가 있다. 지붕 홈통 끝, 드럼통 하나.<br>뚜껑을 열자 빗물이 가득했다. 마실 수 있는 물이다.`,
      ng:`짜는데 걸레에서 물 말고 다른 것이 떨어진다. 손톱이다. 여러 개.<br><br>손을 털었다. 털어도 손바닥에 무엇인가 붙어 있는 느낌이 남았다. 그 뒤로 한참 손 씻을 데만 찾았다.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ mind:-16, spirit:-16 } },
    { l:'③ 양동이를 걷어차 엎는다.', k:'break', dc:21,
      ok:`발로 양동이를 찼다. 물이 바닥에 쏟아진다. 맑은 물이 금방 먼지에 흐려진다.<br><br>엎은 물거울은 아무것도 못 비춘다. 이쪽도, 저쪽도. 저쪽은 이 양동이로 무엇인가 보고 있었다. 이제 못 본다.<br>멀리서 장화 소리가 멈췄다. 한참 안 움직였다.`,
      ng:`찼는데 양동이가 꿈쩍 안 한다. 바닥에 붙었다.<br><br>발끝이 꺾였다. 물이 출렁이며 이쪽 얼굴을 비춘다. 비친 얼굴이 먼저 아파한다. 발가락이 퉁퉁 부었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B2', t:'병실 — 차트의 맨 아래 줄',
  x:`침대 발치에 차트가 걸려 있다. 이쪽 침대다. 이름은 모르는 이름이다.<br><br>
    날짜와 시각이 한 줄씩 적혀 있다. 체온, 맥박, 투약. 맨 아래 줄은 아직 오지 않은 시각이다. 『04:00 — 퇴원.』<br>
    남의 날을 받아 주는 일을 해 왔다.<br><br>
    누가 이쪽 날을 먼저 받아 놓았다.`,
  o:[
    { l:'① 맨 아래 줄의 글씨를 읽는다.', k:'luck', dc:21,
      ok:`글씨를 봤다. 위 줄들은 볼펜 자국이 깊게 눌렸다. 맨 아래 줄만 가볍다. 다른 손이 썼다. 아니면 같은 손이 겁먹고 썼다.<br><br>겁먹고 받은 날은 흔들린다. 흔들리는 날은 비킬 수 있다. 시각 옆에 작은 점이 하나 찍혀 있다. 정각 점검 표시다.<br><br>점검을 비키면 날도 비킨다. 네 시 정각에는 이 침대에 없기로 했다.`,
      ng:`읽는데 줄이 하나 늘어난다. 지금 시각이다. 『— 차트를 읽음.』<br><br>누가 지금 적고 있다. 복도 끝에서 볼펜 누르는 소리가 났다. 딸깍. 그 뒤로 한참 숨을 고르지 못했다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 마력을 실어 맨 아래 줄을 흐린다.', k:'fix', dc:20, cost:{ mana:24 },
      ok:`손끝에 마력을 모아 맨 아래 줄 위에 댔다. 받아 놓은 날을 흐리는 것은 제일 비싼 일이다.<br><br>글씨가 물에 젖은 것처럼 번진다. 『퇴원』이 읽히지 않게 됐다. 시각도.<br>다음 점검 때 간호사가 차트 앞에 한참 서 있었다. 그러다 그냥 지나갔다. 안 읽히는 날은 아무도 못 받는다.`,
      ng:`마력을 대는데 글씨가 마력을 밀어낸다. 볼펜 자국이 더 깊어진다.<br><br>손끝이 데었다. 맨 아래 줄 밑에 한 줄이 더 생겼다. 『— 저항함.』`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'9호차 — 바뀌지 않는 손금',
  x:`앞 좌석 등받이에 긁힌 글씨가 있다. 옆에 선 얼굴을 믿지 마.<br><br>
    일행이 서로 얼굴을 본다. 다 아는 얼굴이다. 그런데 열차에 오른 사람은 다섯이었고 지금 이 자리에는 여섯이 앉아 있다.<br>
    얼굴은 빌릴 수 있다.<br><br>
    점술가는 얼굴 말고 손을 본다. 손금은 남의 것을 빌리기 어렵다.`,
  o:[
    { l:'① 심심풀이라며 손바닥을 펴 보이게 한다.', k:'luck', dc:21, wake:1,
      ok:`한 사람씩 손바닥을 받았다.<br><br>다섯 손금은 다 기억난다. 들어오면서 한 번씩 봐 줬다. 여섯째 손바닥에는 선이 없다. 매끈하다. 아무것도 적히지 않은 손이다. 얼굴만 빌리고 손은 못 빌렸다.<br>그 손이 이쪽 손목을 잡기 전에 일행이 그를 객차 문 밖으로 밀어냈다.<br><br>얼굴 대신 손바닥을 읽었다. 남의 날을 보던 눈이 남의 가짜를 가리기 시작했다. 손금 보는 눈이 한 겹 깊어졌다.`,
      ng:`손바닥을 받는데 여섯 손금이 다 똑같다.<br><br>이쪽 손금이다. 여섯 모두 이쪽 손금을 하고 있다. 누가 진짜인지 모르겠다. 제 손바닥을 들여다봤다. 선 하나가 모자랐다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 마력을 엷게 펴 온기를 읽는다.', k:'sense', dc:20, cost:{ mana:25 },
      ok:`마력을 객차 안에 엷게 폈다. 산 사람은 따뜻하다. 마력이 따뜻한 데서 조금씩 떤다.<br><br>다섯 자리에서 떤다. 여섯째 자리에서만 마력이 미끄러진다. 차다. 창유리만큼.<br>그 자리를 두고 다섯이 다른 칸으로 옮겼다. 여섯째는 따라오지 않았다. 창에 비친 얼굴만 따라왔다.`,
      ng:`펴는데 객차 전체가 차다. 다섯 다 차다. 여섯째만 따뜻하다.<br><br>마력이 거꾸로 읽혔다. 아니면 거꾸로 된 게 이쪽이다. 머리가 깨질 듯 아팠다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'③ 아무것도 묻지 않고 자리만 바꾼다.', k:'evade', dc:19,
      ok:`묻지 않았다. 앉은 순서를 바꾸자고만 했다. 창가와 통로를.<br><br>다섯은 그냥 일어나 바꿨다. 여섯째는 일어나기 전에 다른 사람들을 한 번 봤다. 바꾸는 법을 보고 따라 한 것이다. 한 박자 늦다.<br>그 한 박자 늦은 사람 곁에는 아무도 앉지 않았다.`,
      ng:`바꾸는 사이 하나가 이쪽 옆자리에 앉았다.<br><br>손을 무릎에 올린다. 손바닥이 위로. 선이 없다. 그 손이 이쪽 무릎을 짚고 일어설 때까지 숨이 멎어 있었다. 무릎에 언 자국이 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B', t:'어두운 복도 — 다섯 걸음 뒤',
  x:`복도 뒤에서 발소리가 따라온다.<br><br>
    멈추면 멈추고 걸으면 걷는다.<br>
    가끔 몇 걸음 앞이 먼저 보인다. 눈을 감으면 더 잘 보인다.<br><br>
    이번엔 앞이 아니라 뒤를 봐야 한다.`,
  o:[
    { l:'① 눈을 감고 뒤의 다섯 걸음을 본다.', k:'luck', dc:21,
      ok:`눈을 감았다. 뒤가 보인다. 다섯 걸음 뒤에 무엇인가 있다. 사람 모양인데 무릎이 거꾸로 접힌다.<br><br>넷째 걸음에 그것이 뛴다. 그 전에 옆문으로 빠졌다.<br>문 너머로 뛰는 소리가 지나간다. 이쪽이 서 있던 자리에 무엇인가 부딪쳤다. 본 그대로다.`,
      ng:`감았는데 뒤가 아니라 앞이 보인다. 앞 다섯 걸음 자리에 이쪽이 쓰러져 있다.<br><br>눈을 떴다. 뒤에서 발소리가 바로 붙었다. 뛰었다. 다섯째 걸음에 정말 넘어졌다. 턱을 바닥에 찧었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 마력으로 발소리를 뒤로 흘려보낸다.', k:'hide', dc:20, cost:{ mana:22 },
      ok:`손바닥을 등 뒤로 펴고 마력을 깔았다. 이쪽 발소리를 뒤로 흘려보냈다.<br><br>쫓는 쪽은 앞에서 나는 발소리를 따라온다. 그런데 발소리가 저쪽 뒤에서 난다. 저쪽이 돌아선다.<br>돌아선 것 뒤로 이쪽은 계단을 내려갔다. 소리를 내지 않고.`,
      ng:`흘려보내는데 마력이 발소리를 둘로 쪼갠다.<br><br>앞에서도 뒤에서도 이쪽 발소리가 난다. 쫓는 것이 망설이다 가운데로 왔다. 가운데가 이쪽이었다. 어깨를 잡혔다가 뿌리쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B1', t:'경매장 — 한쪽을 보는 눈',
  x:`경매장 수조에 생선이 가득하다. 죽은 것도 산 것도.<br><br>
    눈이 전부 한쪽을 본다. 짐승이 보는 쪽으로 점을 친 적이 있다. 짐승은 사람보다 먼저 안다.<br>
    생선 눈이 보는 쪽은 바다 쪽 문이다.<br><br>
    반대쪽은 경매사가 선 단상이다.`,
  o:[
    { l:'① 생선 눈이 보는 쪽으로 간다.', k:'luck', dc:20,
      ok:`바다 쪽 문으로 갔다. 생선은 돌아가고 싶은 쪽을 본다. 바다로 가는 문은 사람에게도 나가는 문이다.<br><br>문을 밀자 하역장 처마가 나왔다. 비가 들이친다. 노란 비옷들은 단상 쪽에 몰려 있다. 아무도 이쪽을 안 본다.<br>처마 밑 물통에 민물고기 한 마리가 살아 있었다. 그것도 바다 쪽을 보고 있었다.`,
      ng:`갔는데 문 앞에 노란 비옷이 서 있다. 생선 눈은 비옷을 보고 있었다.<br><br>생선은 바다를 보는 게 아니라 저를 잡아 온 사람을 본다. 그걸 너무 늦게 알았다. 갈고리 장대가 팔을 긁고 지나갔다.`,
      win:{ exp:18, dream:3, item:'민물고기' }, lose:{ hp:-24, mind:-12 } },
    { l:'② 혼자 반대쪽을 보는 눈을 찾는다.', k:'gaze', dc:21,
      ok:`수조를 하나씩 봤다. 아흔아홉 마리가 바다 쪽을 본다. 한 마리만 단상 쪽을 본다.<br><br>그 수조 바닥에 무엇인가 가라앉아 있다. 번호표다. 경매에 올릴 자루 번호. 이쪽 번호.<br>소매를 걷고 꺼냈다. 번호표가 없으면 자루도 없다. 생선 하나가 눈을 돌려 알려 줬다.`,
      ng:`찾는데 생선 눈이 한꺼번에 이쪽으로 돌아간다.<br><br>수백 개 눈이 이쪽을 본다. 경매사 노래가 멈췄다. 단상 위에서 누가 이쪽으로 손가락을 든다. 수조 사이로 기어 나오다 깨진 유리에 무릎을 베었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B2', t:'복도 — 깜빡이는 형광등',
  x:`복도 형광등 하나가 깜빡인다. 일정하게. 일곱 번 깜빡이고 한 번 길게 꺼진다.<br><br>
    촛불점을 친다. 불이 떠는 수로 날을 센다. 형광등도 불이다.<br>
    길게 꺼질 때마다 복도 끝 문이 조금 열린다.<br><br>
    그 안에 누가 서 있다.`,
  o:[
    { l:'① 길게 꺼지는 때에 복도를 지난다.', k:'luck', dc:22,
      doom:{ title:'긴 어둠', what:'어둠 속으로 끌려갑니다', dc:17, sec:55,
        text:`일곱을 세고 뛰었다. 불이 길게 꺼진다.<br><br>어둠 속에서 복도가 길어진다. 다섯 걸음이면 될 데가 열 걸음이 돼도 안 끝난다. 끝 문이 열리는 소리. 손 하나가 이쪽 손목을 잡는다. 차고 가볍다.<br>불이 다시 켜지기 전에 끌려간다.<br><br>촛불점에서 길게 꺼진 불은 그날이 끝났다는 뜻이다. 그 뜻을 손님에게 말해 준 적은 없다.`,
        dieText:`형광등이 다시 켜졌다.<br><br>복도는 비었다. 끝 문은 닫혔다.<br>화이트보드 숫자가 하나 줄었다. 누가 볼펜으로 고쳐 맞췄다.` },
      ok:`일곱을 세고 뛰었다. 불이 길게 꺼진다.<br><br>어둠 속에서 끝 문이 열리는 소리가 났다. 이쪽은 끝 문 쪽이 아니라 옆 병실로 꺾었다. 꺼진 동안 문이 보는 것은 복도다. 옆은 안 본다.<br>불이 켜졌을 때는 옆 병실 커튼 뒤였다.<br><br>촛불점은 꺼지는 때가 아니라 꺼진 동안 무엇이 움직이는지 보는 점이다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 마력으로 불을 붙들어 둔다.', k:'steady', dc:20, cost:{ mana:26 },
      ok:`손을 들어 형광등 쪽으로 마력을 밀었다. 촛불이 꺼지지 않게 붙드는 법과 같다.<br><br>일곱 번 깜빡이고, 길게 꺼질 차례에 불이 버틴다. 끝 문이 열리다 멈춘다. 빛 속으로는 안 나온다.<br>복도를 다 지날 때까지 불을 붙들었다. 손을 내리자 등 뒤에서 길게 꺼졌다. 끝 문이 열리는 소리가 났다. 늦었다. 그쪽이.`,
      ng:`밀었는데 형광등이 터진다. 유리가 쏟아진다.<br><br>이제 깜빡이지도 않는다. 꺼졌다. 복도 끝 문이 활짝 열리는 소리. 유리 조각을 밟으며 뒤로 뛰었다. 발바닥이 다 찢어졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-12 } },
    { l:'③ 복도를 버리고 천장 덕트로 간다.', k:'evade', dc:21,
      ok:`병실 천장 판을 밀어 올렸다. 덕트가 있다. 기어 들어갔다.<br><br>아래로 복도가 지나간다. 틈으로 형광등이 깜빡인다. 길게 꺼질 때 아래에서 무엇인가 천천히 걸어갔다. 이쪽이 지나갔을 자리를.<br>덕트 끝에서 내려왔다. 복도 반대편이다.`,
      ng:`기어 가는데 덕트가 이쪽 무게에 휜다. 소리가 난다.<br><br>아래 복도에서 걸음이 멈췄다. 형광등이 깜빡일 때마다 덕트 틈으로 얼굴 하나가 보였다. 올려다보는 얼굴. 뒷걸음질로 기어 나오다 팔꿈치가 쇠판에 찢겼다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B3', t:'식당칸 — 찻잔 바닥',
  x:`식당칸 식탁에 찻잔이 하나 놓여 있다. 다 마신 잔이다. 바닥에 찻잎이 붙었다.<br><br>
    앉았던 사람은 없다. 의자가 아직 따뜻하다.<br>
    찻잎으로도 점을 친다. 마신 사람이 남긴 모양이 마신 사람의 다음을 말한다.<br><br>
    마신 사람이 누구였는지는 모른다.`,
  o:[
    { l:'① 찻잎을 읽는다.', k:'luck', dc:21, wake:1,
      ok:`잔을 돌려 찻잎을 봤다. 칼 모양 하나, 문 모양 하나, 숫자 같은 것 하나. 4.<br><br>칼은 위험, 문은 길, 4는 칸이다. 이 잔을 마신 사람은 4호차 문 앞에서 칼을 만난다. 아니면 칼을 쥐고 기다린다.<br>4호차 문 대신 지붕으로 넘기로 했다.<br><br>남이 남긴 잔에서 남의 다음을 읽었다. 앞에 앉은 손님이 없어도 점이 선다. 점이 사람보다 먼저 와 있다는 걸 알았다.`,
      ng:`잔을 돌렸는데 찻잎이 잔 안에서 저절로 돈다.<br><br>모양이 만들어졌다 흩어진다. 마지막에 남은 모양은 이쪽 얼굴이다. 손이 떨려 잔이 식탁에서 굴렀다. 깨지는 소리에 식당칸 사람들이 다 돌아봤다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 의자의 온기를 따라간다.', k:'sense', dc:20,
      ok:`의자를 짚었다. 따뜻하다. 방금 일어났다.<br><br>통로 바닥에 젖은 발자국이 있다. 주방 쪽. 주방 문틈으로 김이 샌다. 안에는 아무도 없고 냄비만 끓는다. 냄비 옆에 썰다 만 고기가 있다.<br>사람은 다른 데로 갔다. 고기만 챙겨 나왔다.`,
      ng:`따라가는데 발자국이 이쪽 뒤로 돌아온다.<br><br>이쪽을 따라온 발자국이었다. 돌아보니 식탁의 그 잔이 다시 차 있다. 김이 오른다. 앉으라는 듯. 앉지 않고 뛰다 의자 다리에 걸려 넘어졌다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B', t:'은신처 — 가로지르는 선',
  x:`쉬는 사이 일행 하나가 손을 내민다. 봐 달라는 것이다. 심심풀이로.<br><br>
    손바닥을 등불에 비췄다. 생명선이 길다. 아주 길다.<br>
    그런데 손바닥 한가운데로 가로선 하나가 지나간다.<br><br>
    남을 끊는 선이다.`,
  o:[
    { l:'① 본 대로 말하지 않고 다른 선을 짚어 준다.', k:'luck', dc:21, wake:1,
      ok:`"재물선이 좋소." 웃으며 엄지 밑을 짚어 줬다.<br><br>그 사람도 웃는다. 손을 거둔다. 그 손이 품 안의 무엇인가를 만졌다. 쇠 소리가 났다.<br>그 뒤로 그 사람을 맨 앞에 세웠다. 남을 끊는 선은 뒤에 선 사람을 끊는다. 앞에 서면 끊을 사람이 없다.<br><br>읽은 것을 다 말하지 않는 법. 말하지 않은 괘로 사람을 움직이는 법. 손금 보는 일이 한 겹 깊어졌다.`,
      ng:`다른 선을 짚었는데 그 사람이 웃지 않는다.<br><br>"가로선은 왜 말 안 하오." 그도 손금을 볼 줄 안다. 둘 다 아무 말 안 했다. 그날 밤 이쪽 짐에서 물병이 없어졌다. 목이 말라 잠을 못 잤다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 누구를 끊기로 했는지 묻는다.', k:'bond', dc:20,
      ok:`"누구를 끊기로 했소."<br><br>그가 굳는다. 오래 말이 없다가 손을 오므린다. 들어오기 전에 누가 약속을 했다고. 하나를 두고 나오면 하나는 내보내 준다고. 아직 누구를 둘지는 안 정했다고.<br>"정하지 마시오. 선은 그어야 선이오." 그가 고개를 떨군다. 가로선은 아직 흐렸다.`,
      ng:`물었다. 그가 웃는다. 점쟁이 말을 누가 믿냐고.<br><br>다음 날 그가 문을 하나 열었다. 이쪽이 지나갈 때. 문 뒤에 무엇인가 있었다. 어깨를 찢기며 빠져나왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'③ 아무 말 없이 그 손을 접어 준다.', k:'steady', dc:19,
      ok:`아무 말 없이 그 손을 접어 줬다. 주먹이 되게.<br><br>"좋은 손이오." 그것만 말했다. 그가 한참 제 주먹을 본다. 무엇인가를 쥐고 있던 손이 빈손이 된 것처럼.<br>그 뒤로 그는 이쪽을 피했다. 피하는 사람은 끊지 않는다.`,
      ng:`접어 주는데 그가 손을 확 뺀다.<br><br>무엇을 봤냐는 눈이다. 대답을 안 하니 더 의심한다. 그날 내내 등 뒤가 서늘했다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B1', t:'야적장 — 번호로 친 괘',
  x:`야적장 컨테이너마다 번호가 찍혔다. 여섯 자리.<br><br>
    숫자가 괘로 보인다. 홀수는 이은 줄, 짝수는 끊은 줄. 여섯 줄이면 괘 하나다.<br>
    수백 개 중 괘가 다 같은 것이 셋 있다. 셋 다 바다 쪽으로 열려 있다.<br><br>
    크레인 탐조등이 그 셋을 차례로 비추고 지나간다.`,
  o:[
    { l:'① 괘가 다른 하나를 찾아 피한다.', k:'luck', dc:20,
      ok:`다 같은 괘 사이에 하나가 다르다. 맨 윗줄만 끊겼다. 위가 막힌 괘다. 들어가면 안 나오는 괘.<br><br>그 컨테이너만 피했다. 나머지 사이로 바다 쪽 담장까지 갔다. 철조망 한 군데가 끊겨 있다.<br>피할 데를 아는 것이 갈 데를 아는 것보다 쓸모가 많다.`,
      ng:`찾는데 번호가 빗물에 번져 짝수와 홀수가 섞인다.<br><br>괘가 다 같아 보인다. 아무것도 피하지 못했다. 컨테이너 문 하나가 바람에 열리며 옆구리를 쳤다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 마력을 실어 야적장 전체로 괘를 세운다.', k:'fix', dc:21, cost:{ mana:24 },
      ok:`바닥에 산가지를 늘어놓고 마력을 실었다. 이 야적장 전체를 놓고 친 괘다.<br><br>산가지가 저절로 줄을 맞춘다. 셋째 줄이 움직이는 줄이다. 셋째 열, 셋째 칸.<br>그 자리 컨테이너 문이 반쯤 열려 있다. 안에 지붕으로 오르는 사다리가 걸려 있다. 탐조등이 닿지 않는 높이로 야적장을 건넜다.`,
      ng:`마력을 싣는데 빗물이 산가지를 쓸어 간다.<br><br>셋이 남았다. 반쪽 괘는 반만 맞는다. 반만 믿고 들어간 칸에서 탐조등에 걸렸다. 빛을 피해 엎드리다 턱을 찧었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B2', t:'기록 보관실 — 오늘 날짜 상자',
  x:`기록 보관실 선반에 상자가 날짜별로 꽂혔다. 맨 끝 상자에 오늘 날짜.<br><br>
    상자 안에 서류철이 일행 수만큼 들었다. 맨 위 철에 이쪽 사진이 붙어 있다.<br>
    남의 앞날을 보는 일을 해 왔다.<br><br>
    남이 적어 둔 이쪽 앞날은 처음 본다.`,
  o:[
    { l:'① 끝까지 넘겨 읽는다.', k:'luck', dc:22,
      doom:{ title:'끝 장', what:'서류 속으로 빨려 들고 있습니다', dc:18, sec:50,
        text:`한 장씩 넘겼다. 입원, 점검, 투약, 그리고 지금 이 시각. 『기록 보관실에서 자기 기록을 읽음.』<br><br>다음 장이 있다. 넘기면 안 된다는 걸 안다. 손이 넘긴다. 평생 앞날이 궁금한 사람이었다.<br>다음 장 글씨가 이쪽 눈으로 기어든다. 읽는 게 아니라 읽힌다.<br><br>서류철이 이쪽을 철한다.`,
        dieText:`상자 뚜껑이 닫혔다.<br><br>맨 끝 선반에 상자가 하나 더 꽂혔다. 오늘 날짜다. 두껍다.<br>기록 보관실 불이 꺼졌다. 다음 날짜 상자는 아직 비었다.` },
      ok:`한 장씩 넘겼다. 지금 이 시각까지 적혀 있다. 다음 장에 손가락을 댔다. 넘기지 않았다.<br><br>대신 마지막 장의 받는 사람 칸만 봤다. 『1층 당직실.』 이 기록은 아래로 내려간다. 내려가는 길이 기록에 적혀 있다. 승강기가 아니라 서류 내리는 통.<br><br>앞날은 안 읽고 앞날이 가는 길만 읽었다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 서류철을 세단기에 먹인다.', k:'break', dc:20,
      ok:`이쪽 서류철을 뽑아 구석 세단기에 넣었다. 기계가 종이를 먹는다.<br><br>적힌 앞날은 갈리면 실오라기가 된다. 실오라기로는 아무것도 못 정한다. 다른 일행 철도 넣었다.<br>세단기 통이 차자 바닥 판이 열렸다. 종이 부스러기가 아래층으로 쏟아진다. 그 구멍이 사람 하나 들어갈 만했다.`,
      ng:`넣는데 세단기가 종이가 아니라 소매를 먹는다.<br><br>팔이 끌려 들어간다. 전원 줄을 뽑았다. 소매가 갈가리 찢겨 나왔다. 팔뚝에 톱니 자국이 줄줄이 남았다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-28, mind:-10 } }
  ] },

{ at:'B3', t:'9호차 — 시간표의 빈칸',
  x:`객차 끝 문 위에 시간표가 있다. 역 이름 여섯 줄. 맨 아래 종착 04:44.<br><br>
    종착역 이름 칸이 비었다.<br>
    이름이 없는 것이 제일 싫다. 이름이 있어야 날을 받는다.<br><br>
    종착역 이름을 알면 종착이 무엇인지 안다.`,
  o:[
    { l:'① 잠든 손님들 표를 모아 맞춘다.', k:'luck', dc:21,
      ok:`잠든 손님들 무릎 위 표를 하나씩 봤다. 행선지 칸이 다 비었다. 그런데 한 표만 글자가 비쳐 보인다. 뒤에서 눌러 쓴 자국이다.<br><br>등불에 비스듬히 비췄다. 두 글자. 누가 종착역 이름을 표 뒤에 적었다가 지웠다.<br>그 두 글자를 일행에게 말하지 않았다. 알면 무서운 이름이 있다. 그 역 하나 전에 내려야 한다는 것만 말했다.`,
      ng:`모으는데 손님 하나가 깬다. 표를 낚아챈다.<br><br>깬 얼굴이 이쪽 얼굴로 바뀐다. 표를 쥔 손이 이쪽 손목을 꺾었다. 놓고 물러났다. 손목이 한참 안 돌았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 마력을 실어 빈칸을 비춘다.', k:'gaze', dc:21, cost:{ mana:26 },
      ok:`빈칸에 손바닥을 대고 마력을 흘렸다. 빈칸은 이름이 없는 게 아니라 지워진 것이다. 지운 자리에는 흔적이 남는다.<br><br>손바닥 밑이 뜨거워진다. 글자가 아니라 시각이 떠오른다. 04:44 위에 희미하게 04:31. 그 전 역 시각이다.<br>내릴 시각을 알았다. 이름은 몰라도 된다.`,
      ng:`흘리는데 빈칸이 마력을 빨아들인다. 끝이 없다.<br><br>손을 뗐다. 손바닥이 하얗다. 핏기가 다 빠졌다. 빈칸은 여전히 비었다. 조금 더 커졌다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B', t:'잠긴 방 — 산가지 다섯',
  x:`문이 셋이다. 시계가 하나. 하나만 열린다고 적혀 있다.<br><br>
    이럴 때 산가지를 던진다.<br>
    던지기 전에 손을 비볐다. 손이 젖었다. 산가지가 미끄럽다.<br><br>
    시계 초침이 빠르다.`,
  o:[
    { l:'① 산가지를 던진다.', k:'luck', dc:20,
      ok:`던졌다. 셋이 눕고 둘이 섰다. 선 둘이 가리키는 문.<br><br>열었다. 열렸다. 문 너머 계단에 젖은 발자국이 있다. 앞서 간 사람도 같은 괘를 뽑았다.<br>괘는 길을 정해 주지 않는다. 고를 핑계를 준다. 시계가 빠를 때 핑계는 빨리 고르게 해 준다.`,
      ng:`던졌는데 다섯이 다 섰다.<br><br>그런 괘는 없다. 처음 보는 괘 앞에서 한참 섰다. 초침이 열두 시에 닿았다. 셋 다 잠기는 소리. 환기창을 비틀어 열고 나오는 데 손가락이 다 까졌다.`,
      win:{ exp:16, dream:3 }, lose:{ hp:-22, spirit:-14 } },
    { l:'② 괘 대신 문손잡이를 본다.', k:'gaze', dc:19,
      ok:`산가지는 넣었다. 문손잡이 셋을 봤다. 둘은 먼지가 앉았다. 하나만 반들반들하다.<br><br>많이 잡힌 손잡이는 많이 열린 손잡이다. 아니면 많이 잡히고 안 열린 손잡이다. 손잡이 밑 바닥을 봤다. 긁힌 자국이 문 밖으로 나 있다. 열린 문이다.<br>점을 안 치고 고른 것도 점이다. 눈이 친 점.`,
      ng:`보는데 반들반들한 손잡이가 돌아간다. 안쪽에서.<br><br>문이 조금 열리고 손가락 넷이 문틈을 쥔다. 다른 문으로 뛰었다. 잠겼다. 셋째 문에 어깨를 박고 들어갔다. 어깨가 빠질 뻔했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-10 } }
  ] },

{ at:'B1', t:'방파제 — 물때',
  x:`방파제에 파도가 넘친다. 물이 들어오는 중이다. 해무호는 물이 다 차야 뜬다.<br><br>
    날을 받는 사람에게 물때도 날의 일부다. 달이 안 보여도 물은 달을 따라간다.<br>
    방파제 끝까지 가려면 파도와 파도 사이를 건너야 한다.<br><br>
    칠판에는 다섯 시 십 분이라고 적혀 있었다.`,
  o:[
    { l:'① 파도의 박자를 읽는다.', k:'luck', dc:21, wake:1,
      ok:`파도를 셌다. 큰 것 하나, 작은 것 셋. 다시 큰 것 하나. 달이 보이지 않아도 물은 박자를 지킨다.<br><br>작은 것 셋 사이에 뛰었다. 발목까지만 젖었다. 큰 것이 등 뒤 방파제를 덮었다. 이쪽이 서 있던 자리였다.<br>물때를 손가락으로 셈해 보니 물이 다 차는 시각이 다섯 시 칠 분이다. 칠판의 십 분은 거짓말이었다.<br><br>하늘이 없어도 하늘이 움직이는 것은 읽힌다. 물에 실린 달의 박자를 읽는 눈이 생겼다.`,
      ng:`세는데 큰 것이 둘 연달아 온다.<br><br>박자가 깨졌다. 방파제에서 미끄러졌다. 돌 틈을 붙잡고 버텼다. 손바닥이 따개비에 갈렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 마력을 실어 파도 하나를 늦춘다.', k:'steady', dc:21, cost:{ mana:28 },
      ok:`방파제 돌에 손을 대고 마력을 흘렸다. 물의 날을 한 박자만 늦췄다.<br><br>큰 파도가 올 자리에 작은 파도가 왔다. 일행이 다 건넜다.<br>손을 떼자 등 뒤에서 큰 파도 둘이 한꺼번에 덮쳤다. 늦춘 한 박자는 딱 그만큼이었다.`,
      ng:`흘리는데 바닷물이 마력을 삼킨다. 바다는 날을 받지 않는다.<br><br>손을 뗀 순간 파도가 정강이를 쳤다. 넘어졌다. 일행이 옷깃을 잡아 끌어 올렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-12 } },
    { l:'③ 배가 뜰 때까지 처마 밑에서 기다린다.', k:'sense', dc:19,
      ok:`기다렸다. 물이 차는 동안 방파제 옆 창고 처마 밑에서.<br><br>물이 다 차면 해무호가 뜨고, 배가 뜬 뒤 방파제는 넓다. 배를 놓치는 것이 나가는 길이다.<br>처마 밑 드럼통에 빗물이 차 있었다. 기다리는 동안 한 병 받았다.`,
      ng:`기다리는데 처마 밑으로 장화 소리가 온다.<br><br>기다리는 사람을 찾는 쪽도 기다린다. 처마를 나와 파도 속으로 뛰었다. 허리까지 젖었다. 이가 딱딱 부딪쳤다.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B2', t:'휴게실 — 손을 내민 노파',
  x:`휴게실 구석에 노파가 앉아 있다. 환자복. 손을 내민다.<br><br>
    점을 봐 달라고 한다. 나갈 수 있겠느냐고.<br>
    손바닥이 차다. 생명선이 손목까지 내려가 있다. 손목에 이름표 팔찌. 이름 칸이 비었다.<br><br>
    괘는 그대로 말할 수도 있고 다르게 말할 수도 있다.`,
  o:[
    { l:'① 선을 사람 쪽으로 기울여 읽어 준다.', k:'luck', dc:20, wake:1,
      ok:`"선이 손목을 넘었소. 이 손은 이 방보다 길게 사오."<br><br>틀린 말이 아니다. 손금은 손바닥에서 끝나지 않는다. 그렇게 읽을 수도 있다.<br>노파가 웃는다. 여기 와서 처음 웃는다고 한다. 손을 거두며 화분 흙을 가리킨다. 파 보니 열쇠 하나와 꿀 봉지 둘.<br><br>읽은 괘를 사람 쪽으로 기울여 읽었다. 말 하나가 사람을 일으킨다. 괘를 읽는 입이 한 겹 깊어졌다.`,
      ng:`말하는데 목소리가 떨린다.<br><br>노파가 손을 거둔다. 점쟁이가 떨면 듣는 사람은 더 떤다. 노파가 소리 없이 운다. 정각 점검이 와서 노파 앞에 오래 섰다. 그걸 끝까지 봐야 했다.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 본 대로 말한다.', k:'gaze', dc:19,
      ok:`"이 손은 여기서 끝나오."<br><br>노파가 고개를 끄덕인다. 알고 있었다고. 그래서 물은 것이라고. 아는 걸 남에게 들어야 마음이 놓인다.<br>노파가 팔찌를 풀어 준다. 이름 칸이 빈 팔찌. 이걸 차면 점검에서 한 번은 빠진다고. 노파 몫의 한 번이다.`,
      ng:`말했는데 노파가 이쪽 손을 잡는다.<br><br>그럼 네 손도 보자고. 노파가 이쪽 손금을 오래 본다. 아무 말도 안 한다. 그 침묵이 오래 따라왔다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B3', t:'특실 7호실 — 거꾸로 가는 시계',
  x:`특실 7호실 벽시계가 거꾸로 간다. 초침이 왼쪽으로 돈다.<br><br>
    침대에 손님이 누워 있다. 얼굴을 벽으로 돌렸다.<br>
    시계가 거꾸로 가는 방에서 친 괘는 거꾸로 맞는다고 배웠다.<br><br>
    점술가는 그 말을 시험해 볼 날이 올 줄 몰랐다.`,
  o:[
    { l:'① 괘를 거꾸로 읽는다.', k:'luck', dc:21,
      ok:`산가지를 던졌다. 나온 괘를 거꾸로 읽었다. 흉은 길로, 끝은 처음으로.<br><br>거꾸로 읽은 괘가 말한다. 들어온 문으로 나가라. 들어온 문은 복도 쪽이 아니다. 침대 밑이다. 침대 밑에 바닥 문이 있다. 아래 칸으로 이어진다.<br>손님은 끝까지 벽을 보고 있었다. 내려가는 동안 초침 소리가 바로 가기 시작했다.`,
      ng:`거꾸로 읽었는데 괘가 바로 서 있다. 거꾸로 읽은 것을 거꾸로 읽은 셈이다.<br><br>머리가 꼬인다. 손님이 돌아눕는다. 얼굴이 이쪽 얼굴이다. 늙었다. 아주 많이. 방을 뛰쳐나오다 문틀에 이마를 찧었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-14 } },
    { l:'② 시계 바늘을 바로 돌려놓는다.', k:'fix', dc:20,
      ok:`시계 유리를 열고 바늘을 손가락으로 붙잡았다. 한 칸씩 바로 돌렸다.<br><br>침대 손님이 움찔한다. 거꾸로 가는 시간 속에 있던 사람이다. 시간이 바로 가자 잠꼬대처럼 중얼거린다. 다음 칸 연결문은 안에서만 열린다고.<br>그 말을 들었다. 손님은 다시 잠들었다. 바늘은 멈췄다.`,
      ng:`붙잡았는데 바늘이 손가락을 밀어낸다. 힘이 세다.<br><br>손톱이 꺾였다. 바늘이 더 빨리 거꾸로 돈다. 방 안 공기가 차가워진다. 숨을 쉬는데 입김이 거꾸로 들어왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B', t:'쉬는 자리 — 젖은 산가지',
  x:`산가지가 다 젖었다. 다섯 개 중 하나는 부러졌다.<br><br>
    산가지로 먹고산 사람이다. 넷으로는 괘가 반만 선다.<br>
    다들 지쳐 앉았다. 누가 묻는다.<br><br>
    남은 길이 얼마냐고.`,
  o:[
    { l:'① 넷으로 괘를 세운다.', k:'luck', dc:20, wake:1,
      ok:`넷을 던졌다. 반쪽 괘가 나왔다. 나머지 반은 부러진 하나 자리다.<br><br>부러진 자리를 비워 두고 읽었다. 비워 둔 자리가 대답이다. 아직 정해지지 않은 길이 하나 남았다. 정해지지 않았으니 이쪽이 정할 수 있다.<br>"반은 정해졌고 반은 우리 거요." 다들 고개를 든다.<br><br>산가지가 모자라도 괘는 선다. 빈 줄을 읽는 법이 손에 붙었다.`,
      ng:`넷을 던졌는데 넷이 다 부러진 쪽을 가리킨다.<br><br>아무 뜻도 없다. 그런데 다들 그쪽을 쳐다봤다. 아무도 그 뒤로 말을 안 했다. 쉬어도 쉬어지지 않았다.`,
      win:{ exp:22, dream:3, mind:6 }, lose:{ mind:-14, spirit:-14 } },
    { l:'② 괘 없이 제 손금을 보여 준다.', k:'steady', dc:19,
      ok:`산가지를 내려놓고 제 손바닥을 등불에 비췄다. 손은 늘 가지고 다닌다.<br><br>생명선이 길다. 들어오기 전보다 조금 길어진 것 같다. 기분 탓이다. 기분 탓이라도 좋다.<br>"남은 길은 이만하오." 손바닥을 보여 줬다. 다들 웃었다. 웃고 나니 조금 쉬어졌다.`,
      ng:`비췄는데 손바닥 선이 젖은 손에서 번져 보인다.<br><br>생명선이 끊겨 보인다. 물기 때문이다. 알면서도 한참 쳐다봤다. 다들 이쪽 얼굴을 봤다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-12, spirit:-16 } }
  ] },

{ at:'B', t:'시계 둘 — 분을 받는 일',
  x:`벽시계와 손목시계가 십 분 다르다.<br><br>
    다들 이쪽을 본다. 날을 받는 사람이니 시각도 받으라고.<br>
    시각을 받아 본 적은 없다.<br><br>
    날이 아니라 분이다.`,
  o:[
    { l:'① 산가지로 분을 짚는다.', k:'luck', dc:21,
      ok:`산가지를 손가락 사이에 끼우고 하나씩 꺾어 셌다. 날 받는 셈을 분으로 줄였다.<br><br>셈이 섰다. 남은 시간은 두 시계 다보다 적다. 둘 다 이쪽을 느긋하게 하려는 시계다.<br>바로 출발했다. 문 앞에 닿았을 때 멀리서 종이 울렸다. 셈이 맞았다.`,
      ng:`꺾어 세는데 셈이 날로 넘어간다. 분을 세려는데 손가락이 날을 센다.<br><br>버릇이다. 사흘이라는 셈이 나왔다. 사흘은 없다. 그 셈에 매달린 사이 다들 떠났다. 뒤쫓다 계단을 헛디뎠다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 마력으로 두 시계를 거쳐 간 손을 읽는다.', k:'gaze', dc:20, cost:{ mana:22 },
      ok:`손바닥을 시계 둘에 차례로 댔다. 마력을 흘리면 물건을 거쳐 간 손이 느껴진다.<br><br>손목시계는 들어오기 전에 누가 채워 준 것이다. 손이 차다. 벽시계는 여기 사람이 감은 것이다. 손이 축축하다. 둘 다 남의 손이다.<br>둘 다 믿지 않고 빗소리와 맥박으로 셌다. 시계를 읽고 시계를 버렸다.`,
      ng:`대는데 손목시계에서 남의 손이 이쪽 손목을 쥐는 느낌이 든다.<br><br>시계 줄이 조인다. 버클이 안 열린다. 손목이 퍼렇게 됐을 때 겨우 풀었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B', t:'젖은 방 — 이쪽 점을 치는 사람',
  x:`방 한가운데 상이 있다. 맞은편에 누가 앉아 산가지를 던진다.<br><br>
    비옷을 입었다. 모자챙에서 물이 떨어진다. 이쪽 점을 치고 있다.<br>
    산가지가 떨어질 때마다 일행 하나가 기침을 한다.<br><br>
    남이 나를 점치면 내 날이 그 사람 손에 간다.`,
  o:[
    { l:'① 먼저 그쪽 점을 친다.', k:'luck', dc:22,
      doom:{ title:'읽히는 쪽', what:'날을 빼앗기고 있습니다', dc:18, sec:50,
        text:`이쪽도 산가지를 던졌다. 저쪽 괘를 읽으려고.<br><br>나온 괘가 저쪽 것이 아니다. 이쪽 것이다. 저쪽이 이쪽 괘를 하나씩 집어 간다. 집어 갈 때마다 내일이 흐려진다.<br><br>점술가는 앞날을 보는 사람이다. 앞날이 없는 점술가는 볼 것이 없다.`,
        dieText:`산가지가 다 넘어갔다.<br><br>저쪽이 일어선다. 비옷 모자챙에서 물이 떨어진다.<br>상 위에 이쪽 산가지가 남았다. 저쪽이 그것까지 챙겨 넣었다. 다음 손님 점을 칠 때 쓸 것이다.` },
      ok:`저쪽보다 먼저 던졌다. 저쪽 괘가 나왔다.<br><br>텅 빈 괘다. 저쪽은 앞날이 없다. 그래서 남의 것을 친다. 읽힌 것을 알자 저쪽 손이 멈췄다. 모자챙에서 떨어지던 물이 멎는다.<br>저쪽이 산가지를 놓고 물러났다. 일행 기침이 멎었다.<br><br>먼저 읽는 쪽이 이긴다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 마력을 실어 상을 내리쳐 괘를 흩는다.', k:'break', dc:21, cost:{ mana:25 },
      ok:`마력을 손바닥에 모아 상을 내리쳤다. 산가지가 사방으로 흩어진다.<br><br>흩어진 괘는 아무도 못 읽는다. 저쪽도 이쪽도. 저쪽이 흩어진 산가지를 주우러 바닥을 기어간다.<br>그 틈에 방을 나왔다. 기침은 계단 하나를 내려가서야 멎었다.`,
      ng:`내리쳤는데 산가지가 그대로다. 마력이 상에 먹혔다.<br><br>저쪽이 이쪽을 보고 천천히 웃는다. 방을 나오는 데 다리가 무거웠다. 일행 하나는 한참 기침을 했다. 피가 섞여 나왔다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'③ 손바닥으로 제 괘를 덮는다.', k:'steady', dc:20,
      ok:`상 위 이쪽 괘 자리에 손바닥을 덮었다. 안 보여 주겠다는 뜻이다.<br><br>저쪽 손이 멈춘다. 덮인 괘는 읽을 수 없다. 한참 그대로 있었다. 손바닥 밑이 뜨겁다. 버텼다.<br>저쪽이 산가지를 거두고 일어섰다. 남의 앞날을 보는 것보다 제 앞날을 쥐고 있는 것이 먼저다.`,
      ng:`덮었는데 손등 위로 괘가 비쳐 보인다.<br><br>저쪽이 다 읽었다. 무엇을 읽었는지는 모른다. 한동안 내일 생각이 잘 안 났다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B', t:'내려가는 계단 — 마지막 괘',
  x:`계단 앞에서 산가지를 꺼냈다.<br><br>
    내려가기 전에 한 괘. 들어올 때와 같다.<br>
    산가지 끝이 닳았다. 여기서 많이 던졌다.<br><br>
    이번엔 손이 떨리지 않는다.`,
  o:[
    { l:'① 아래층의 괘를 뽑는다.', k:'luck', dc:21, wake:1,
      ok:`던졌다. 다섯 개가 한 줄로 누웠다.<br><br>그런 괘는 처음이다. 그런데 읽힌다. 아래 어디쯤에서 무엇을 만나고, 어디서 돌아서야 하는지. 괘가 앞을 말하는 게 아니라 앞이 괘를 빌려 말을 거는 것 같았다.<br><br>처음 보는 괘를 겁 없이 읽었다. 괘가 모르는 모양으로 나와도 눈이 따라간다. 그 눈이 오늘 한 뼘 자랐다.`,
      ng:`던졌는데 하나가 계단 아래로 굴러간다.<br><br>주우러 가지 않았다. 아래층이 먼저 받아 간 괘다. 넷으로 읽는 괘는 반쯤만 맞는다. 내려가는 내내 반쯤 불안했다.`,
      win:{ exp:22, dream:4 }, lose:{ mind:-14, spirit:-14 } },
    { l:'② 괘를 뽑지 않고 내려간다.', k:'steady', dc:19,
      ok:`산가지를 도로 넣었다. 모르고 내려가는 것도 한 번쯤은 괜찮다.<br><br>계단은 생각보다 짧았다. 모르고 내려간 길은 무섭지만 빨리 끝난다.`,
      ng:`안 뽑고 내려가는데 자꾸 불안하다. 모르는 것을 제일 못 견딘다.<br><br>계단 중간에 주저앉아 숨을 골랐다. 그사이 위에서 문 닫히는 소리가 났다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-14, spirit:-12 } },
    { l:'③ 일행에게 산가지를 하나씩 쥐여 준다.', k:'bond', dc:20,
      ok:`산가지 다섯을 일행에게 하나씩 나눠 줬다. 이제 혼자서는 괘를 칠 수 없다.<br><br>대신 아래층에서 길을 고를 때마다 차례로 한 사람씩 제 산가지를 세워 고르자고 했다. 다섯이 하나씩 고르면 다섯이 같이 친 괘다.<br>혼자 보는 점보다 덜 맞을지 모른다. 덜 외롭다.`,
      ng:`나눠 주는데 하나가 안 받는다. 점은 점쟁이 몫이라고.<br><br>남은 넷을 쥔 손들이 하나씩 산가지를 놓았다. 계단 바닥에 산가지가 흩어졌다. 주워 담는 사이 위층 발소리가 내려왔다. 발목을 잡혔다 뿌리쳤다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-22, mind:-12 } }
  ] }

]);

// ==========================================
// 🏺 수집가 (collector) · 자원 없음
// ==========================================
kJob('collector', 'B', [

{ at:'B', t:'빗속 골목 — 흘린 단추',
  x:`젖은 길바닥에 단추가 떨어져 있다. 열 걸음마다 하나.<br><br>
    같은 단추다. 검은 뿔 단추. 누가 일부러 흘렸다. 따라오라는 표시다.<br>
    수집가는 같은 것들 사이에서 다른 하나를 찾는 사람이다.<br><br>
    일곱째 단추만 구멍이 셋이다. 나머지는 넷.`,
  o:[
    { l:'① 구멍 셋짜리 단추를 다시 본다.', k:'luck', dc:20, wake:1,
      ok:`일곱째 단추를 주웠다. 구멍이 셋. 같은 공방 것이 아니다. 누가 하나를 바꿔 놓았다.<br><br>그 자리에서 길이 갈린다. 단추 줄은 왼쪽으로 이어진다. 구멍 셋짜리는 오른쪽 골목 입구에 떨어져 있었다. 오른쪽으로 갔다. 앞서 간 누가 쫓기면서 진짜 길을 알리려고 하나를 바꿔 둔 것이다.<br>왼쪽 골목 끝에서는 누가 기다리고 있었을 것이다. 확인은 안 했다.<br><br>같은 것 열 개 중 다른 하나가 말하는 걸 들었다. 모으는 손이 아니라 가려 읽는 눈이 한 칸 자랐다.`,
      ng:`주우려는데 단추가 빗물에 밀려 하수구로 굴러간다.<br><br>쫓아 손을 넣었다. 철망에 손등이 찢겼다. 단추는 놓쳤다. 남은 단추를 따라 왼쪽으로 갔다. 막다른 데서 한참 돌아 나왔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 단추를 다 주워 끝까지 센다.', k:'sense', dc:19,
      ok:`하나씩 주우며 갔다. 떨어진 걸 그냥 못 지나친다.<br><br>열두 개째에서 단추가 끝난다. 끝난 자리에 하수구 뚜껑이 반쯤 열려 있다. 단추 주인이 거기로 들어갔다. 아니면 거기로 끌려갔다. 물소리 말고 다른 소리는 안 난다.<br>뚜껑을 닫고 반대쪽으로 갔다. 주머니에서 단추 열두 개가 짤랑거렸다.`,
      ng:`줍다가 허리를 펴는데 뒤에 누가 서 있다. 단추 줍는 사람을 기다리던 사람이다.<br><br>단추를 던지고 뛰었다. 빗길에 무릎을 깼다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B1', t:'냉동 창고 — 성에 낀 선반',
  x:`냉동 창고 안쪽 벽에 선반이 있다. 성에가 꼈다.<br><br>
    선반마다 물건이 하나씩 놓였다. 신발 한 짝, 안경, 반지, 출근 카드. 이름표가 붙었고 날짜가 적혔다.<br>
    한눈에 안다. 창고 물건이 아니다. 누군가의 수집이다. 사람마다 하나씩.<br><br>
    맨 끝 칸이 비었다. 이름표만 있다.`,
  o:[
    { l:'① 맨 끝 이름표를 들여다본다.', k:'luck', dc:22,
      doom:{ title:'빈 칸', what:'선반에 올려지고 있습니다', dc:17, sec:55,
        text:`이름표를 들여다봤다. 이쪽 이름이다. 날짜는 오늘.<br><br>손이 이름표에 붙었다. 얼었다. 떼려니 선반이 당긴다. 등 뒤로 장화 소리가 온다. 서두르지 않는다. 회색 비옷이 양동이를 내려놓는다.<br><br>수집가는 평생 물건을 선반에 올렸다. 제가 올라가는 것은 처음이다. 등 뒤에서 누가 흡족하게 숨을 쉰다.`,
        dieText:`맨 끝 칸에 물건이 하나 놓였다. 이쪽이 끼던 것이다.<br><br>이름표 옆에 날짜가 마저 적혔다. 시각까지.<br>선반 끝에 빈 칸이 하나 새로 생겼다. 다음 사람 몫이다.` },
      ok:`이름표를 들여다봤다. 이쪽 이름이다. 손대지 않았다. 남의 진열에는 손을 대지 않는다.<br><br>대신 날짜를 봤다. 다른 칸 시각은 다 다섯 시 십 분 전이다. 넘긴 칸은 하나도 없다. 이 사람은 다섯 시 십 분이 지나면 못 모은다.<br>선반 맨 아래에 이름표 없는 열쇠 하나가 놓여 있다. 수집에서 빠진 것이다.<br><br>그것만 집어 왔다. 냉동 창고 뒷문 열쇠였다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 제일 오래된 칸을 본다.', k:'gaze', dc:20,
      ok:`날짜가 제일 오래된 칸을 봤다. 낡은 우산 손잡이다. 이름표 이름이 지워졌다.<br><br>첫 수집품이다. 모으는 사람은 첫 것을 제일 아낀다. 이 사람도 그렇다. 손잡이 밑에 쪽지가 깔렸다. 첫 사람이 남긴 것이다. 『셔터 사슬 바깥 자물쇠는 가짜다.』<br>첫 것을 보면 모은 사람을 안다. 모은 사람을 알면 피할 수 있다.`,
      ng:`오래된 칸을 보는데 성에가 손등에 옮겨붙는다.<br><br>손이 하얗게 얼었다. 손가락이 안 움직인다. 녹이는 데 한참 걸렸다. 녹은 손등이 터졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'③ 진열은 두고 얼음 사이 먹을 것을 찾는다.', k:'sense', dc:19,
      ok:`진열은 두고 다른 선반을 훑었다. 진짜 사이 잡것도 본다.<br><br>얼음 덩이 사이에 짐승 고기 한 덩이가 끼어 있다. 생선 창고에 짐승 고기는 드물다. 하역부 누가 숨겨 둔 몫이다. 꽁꽁 얼었다. 품에 넣어 녹이며 걸었다.`,
      ng:`훑다가 얼음 선반이 무너졌다.<br><br>얼음 덩이가 발등을 찍었다. 소리가 창고 안에 오래 울렸다. 멀리서 장화 소리가 방향을 바꿨다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-26, spirit:-10 } }
  ] },

{ at:'B2', t:'간호사실 — 분실물 상자',
  x:`간호사실 구석에 상자가 있다. 『분실물』.<br><br>
    안에 열쇠가 수십 개다. 환자들이 들어올 때 맡긴 것이다. 집 열쇠, 자전거 열쇠, 사물함 열쇠.<br>
    비상문 열쇠도 어딘가 섞여 있다고들 한다.<br><br>
    열쇠는 많이 쓴 것과 안 쓴 것이 다르다.`,
  o:[
    { l:'① 눈을 감고 손에 걸리는 열쇠를 집는다.', k:'luck', dc:20,
      ok:`상자에 손을 넣고 눈을 감았다. 손끝이 먼저 고른다.<br><br>걸린 것은 이가 뭉툭한 열쇠다. 매일 쓴 열쇠다. 고리에 병원 번호 표가 달렸다. 환자 열쇠가 아니다. 직원 열쇠가 환자 물건 사이에 숨어 있었다.<br>물건이 사람을 고르는 날이 있다.`,
      ng:`손을 넣는데 상자 바닥에서 무엇인가 손가락을 감는다. 고무줄이다. 아니다.<br><br>손을 뺐다. 손가락에 머리카락이 감겨 나왔다. 길다. 한참 풀었다. 풀어도 감겼던 자리가 따끔거렸다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 하나씩 비춰 닳은 자리를 본다.', k:'gaze', dc:21,
      ok:`하나씩 등불에 비췄다. 대부분 녹슬었다. 안 쓴 지 오래다. 여기 들어온 사람은 집에 다시 안 갔다.<br><br>하나만 이가 반짝인다. 최근까지 쓴 것이다. 고리에 아무 표도 없다. 표를 떼어 낸 열쇠다. 비상문 열쇠는 그런 식으로 숨긴다.<br>시간이 걸렸다. 정각 전에 끝냈다.`,
      ng:`비추는 사이 정각이 됐다.<br><br>딸깍 소리가 간호사실 문 앞에 섰다. 상자를 끌어안고 책상 밑으로 들어갔다. 열쇠끼리 부딪는 소리가 났다. 간호사가 책상 앞에 오래 섰다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B3', t:'9호차 — 바뀌지 않는 물건',
  x:`얼굴을 바꾸는 손님이 있다. 다들 얼굴을 보며 의심한다.<br><br>
    얼굴 대신 물건을 본다. 사람은 바뀌어도 가진 물건은 그대로다. 시계, 반지, 구두, 넥타이핀.<br>
    객차 안 승객 열한 명. 아까 본 것과 하나가 다르다.<br><br>
    창가 늙은 손님이 끼던 은반지가 지금 통로 쪽 젊은 손님 손에 있다.`,
  o:[
    { l:'① 지나가는 척 반지를 가까이서 본다.', k:'luck', dc:21, wake:1,
      ok:`지나가는 척하며 반지를 봤다. 은이다. 안쪽 새김이 닳았다. 수십 년 낀 반지다.<br><br>젊은 손가락에는 반지 자국이 없다. 반지는 늙은 손가락에 맞게 늘어나 헐겁다. 얼굴은 빌렸고 반지는 훔쳤다. 반지는 아직 주인을 기억한다.<br>그 자리를 지날 때마다 일행에게 눈짓했다. 아무도 그 옆에 앉지 않았다.<br><br>얼굴이 바뀌는 데서 물건을 붙잡고 사람을 셌다. 물건의 기억을 읽는 눈이 한 칸 깊어졌다.`,
      ng:`보는데 젊은 손님이 손을 접는다. 반지가 사라진다.<br><br>다시 펴니 반지가 없다. 대신 이쪽 손가락이 차갑다. 이쪽 손에 낯선 반지가 끼워져 있다. 빼는 데 손가락 마디가 벗겨졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-20, spirit:-16 } },
    { l:'② 고개를 숙이고 구두만 센다.', k:'sense', dc:20,
      ok:`고개를 숙이고 구두만 봤다. 얼굴보다 구두가 정직하다. 구두는 잘 안 바꾼다.<br><br>열한 켤레. 열 켤레는 젖었다. 비 오는 승강장에서 탄 구두다. 한 켤레만 말랐다. 이 열차 밖에 나가 본 적 없는 구두다.<br>마른 구두 주인은 앞쪽 연결문 곁에 앉았다. 그 문 앞을 지나지 않고 지붕 사다리로 넘었다.`,
      ng:`숙이고 세는데 구두 하나가 이쪽 구두 앞에 와 선다.<br><br>고개를 들었다. 이쪽 구두와 똑같은 구두다. 얼굴도 그렇다. 물러서다 좌석 팔걸이에 옆구리를 찧었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'③ 물건을 보라고 일행에게만 속삭인다.', k:'bond', dc:19,
      ok:`일행을 모아 속삭였다. 얼굴 말고 물건을 보라고. 시계가 몇 시인지, 반지가 어느 손가락에 있는지.<br><br>일행 하나가 곧 알아챘다. 어떤 손님 손목시계가 아까 다른 손님 시계와 똑같이 칠 분 늦다. 같은 손님이었다.<br>다들 그 근처를 피했다. 하나가 보는 것보다 다섯이 보는 게 낫다.`,
      ng:`속삭이는데 일행 하나가 이쪽 손을 본다.<br><br>이쪽 손에 반지가 하나 있다. 원래 있던 것이다. 그런데 일행은 처음 본다고 한다. 의심이 이쪽으로 왔다. 풀리기까지 한참 걸렸다. 그동안 아무도 이쪽 옆에 앉지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B', t:'잠긴 문 — 열쇠 서른 개',
  x:`잠긴 문 옆 못에 열쇠 꾸러미가 걸렸다. 서른 개쯤. 다 비슷하다.<br><br>
    발소리가 계단 아래서 올라온다.<br>
    하나씩 넣어 볼 시간은 없다.<br><br>
    맞는 열쇠는 닳은 데가 다르다.`,
  o:[
    { l:'① 손에 처음 걸리는 것을 넣는다.', k:'luck', dc:21,
      ok:`꾸러미를 흔들어 손에 처음 걸린 것을 넣었다. 돌았다. 한 번에.<br><br>이런 날이 있다는 걸 안다. 물건이 사람을 고르는 날. 오늘 같은 날은 오래 안 간다. 그러니 오늘 써야 한다.`,
      ng:`넣었는데 열쇠가 안에서 부러졌다.<br><br>이제 서른 개 다 소용없다. 발소리가 계단참까지 왔다. 창문으로 나갔다. 창틀에 걸려 바지가 찢기고 정강이가 길게 그였다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 이 끝이 뭉툭한 것을 고른다.', k:'gaze', dc:20,
      ok:`꾸러미를 손바닥에 펼쳤다. 대부분 이가 반짝인다. 안 쓴 것이다. 하나만 이 끝이 뭉툭하다. 매일 쓴 것이다.<br><br>넣었다. 돌았다. 등 뒤에서 발소리가 계단참에 닿았다. 문을 닫고 안에서 잠갔다.<br>꾸러미는 챙겼다. 서른 개 다. 쓸모가 없어도 모은다.`,
      ng:`펼치는데 다 닳았다. 다 쓴 열쇠다.<br><br>하나씩 넣어 보는 사이 발소리가 바로 뒤에 왔다. 열여덟째가 맞았다. 문틈으로 손 하나가 들어오다 끼었다. 밀어내다 손목을 긁혔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B1', t:'경매장 — 진주 한 줄',
  x:`경매장 구석 탁자에 압수품 상자가 있다. 목걸이, 시계, 반지가 엉켰다.<br><br>
    다 가짜다. 칠한 쇠, 유리알. 한 줄만 다르다. 진주 목걸이. 알 하나하나 모양이 다르다. 진짜 진주는 고르지 않다.<br>
    상자 옆에 쪽지가 있다. 『낙찰 — 해무호 선장』.<br><br>
    선장이 가짜 더미 속에서 진짜 하나를 사 갔다.`,
  o:[
    { l:'① 진주를 앞니에 문질러 본다.', k:'luck', dc:20,
      ok:`알 하나를 앞니에 문질렀다. 까끌하다. 진짜다. 가짜는 매끄럽다.<br><br>목걸이를 들자 알 사이 매듭 하나가 유난히 굵다. 매듭 안에 접힌 종이가 끼어 있다. 선장에게 가는 쪽지다. 『다섯 명 확인. 방파제 끝.』<br>진주는 두고 쪽지만 가졌다. 진짜 물건은 진짜 소식을 품는다.`,
      ng:`문지르는데 이가 시리다. 알이 얼음처럼 차다.<br><br>얼음이었다. 진주 모양 얼음. 녹은 물이 턱을 타고 흐른다. 뒤에서 노란 비옷이 웃는다. 가짜를 가려내는 사람을 가려내려고 둔 것이다. 어깨를 잡혔다가 뿌리쳤다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 가짜 더미를 뒤진다.', k:'sense', dc:21,
      ok:`진짜는 두고 가짜를 뒤졌다. 가짜 사이에 진짜 쓸 것이 섞일 때가 있다.<br><br>칠한 시계 하나가 무겁다. 뚜껑을 열자 톱니 대신 소금이 차 있다. 밀수꾼들이 숨긴 굵은 바닷소금. 주머니에 털어 넣었다.`,
      ng:`뒤지다 가짜 반지 하나에 손가락이 걸렸다.<br><br>반지 안쪽에 침이 있다. 찔렸다. 손가락이 저리다. 저림이 팔꿈치까지 올라왔다가 한참 뒤에 내려갔다.`,
      win:{ exp:16, dream:2, item:'소금 덩이' }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B2', t:'직원 탈의실 — 명찰 서랍',
  x:`직원 탈의실 사물함 서랍에 명찰이 가득하다. 숫자만 찍힌 명찰.<br><br>
    간호사들 가슴에 다는 것이다. 명찰을 모아 본 적이 있다. 진짜는 핀 뒤에 만든 곳 표시가 있다.<br>
    하나 달고 복도를 걸으면 계수기가 안 눌린다고 한다.<br><br>
    진짜를 달면.`,
  o:[
    { l:'① 숫자가 제일 작은 명찰을 단다.', k:'luck', dc:22,
      doom:{ title:'일 번', what:'직원으로 세어지고 있습니다', dc:17, sec:55,
        text:`1번 명찰을 달았다. 제일 오래된 번호다.<br><br>핀이 옷을 뚫고 살에 박힌다. 아프지 않다. 그게 이상하다. 복도에서 딸깍 소리가 온다. 간호사들이 이쪽 앞에 줄을 선다. 1번을 기다린 얼굴들이다.<br>계수기 하나가 이쪽 손에 쥐여진다. 엄지가 저절로 올라간다.<br><br>평생 남의 표를 모았다. 제가 표가 되는 줄은 몰랐다.`,
        dieText:`정각 점검이 돈다. 맨 앞에 1번이 선다.<br><br>계수기 소리가 정확하다. 딸깍. 딸깍.<br>탈의실 서랍에 1번 자리가 하나 비었다가 다시 찼다.` },
      ok:`1번 명찰을 들었다. 핀 뒤를 봤다. 표시가 없다. 가짜다. 제일 오래된 번호가 제일 가짜다.<br><br>내려놓았다. 대신 가운데 번호 하나를 뒤집었다. 표시가 있다. 진짜다. 달지는 않았다. 주머니에 넣었다.<br>정각 점검 때 주머니 속 명찰을 쥐고 있었다. 간호사가 이쪽 앞에서 계수기를 안 눌렀다.<br><br>달지 않아도 쥐고만 있으면 된다. 진짜는 그만큼 힘이 있다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 핀 뒤 표시를 하나씩 본다.', k:'gaze', dc:20,
      ok:`하나씩 뒤집었다. 서른 개 중 진짜는 넷. 나머지는 다 같은 가짜 공방 것이다.<br><br>진짜 넷을 일행에게 나눠 쥐였다. 하나가 모자란다. 이쪽 몫은 가짜로 했다.<br>가짜도 쥐고 있으면 진짜처럼 보인다. 둘의 차이를 아는 건 이쪽뿐이다. 간호사는 모를 것이다. 아마.`,
      ng:`뒤집는 사이 사물함 하나가 안에서 열린다.<br><br>흰 옷 하나가 걸려 있다. 걸린 게 아니라 서 있다. 명찰을 뒤집는 이쪽을 내려다본다. 뒷걸음질 치다 사물함 문에 이마를 찧었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-14 } },
    { l:'③ 명찰은 두고 사물함 바닥을 뒤진다.', k:'sense', dc:19,
      ok:`명찰은 손대지 않았다. 사물함 바닥을 봤다. 직원들이 흘린 것이 있다. 머리핀, 사탕 껍질.<br><br>맨 끝 사물함 바닥에 꿀 봉지 둘이 굴러다닌다. 배식 수레에서 빼돌린 것이다. 진짜 직원이 있었다는 흔적이다.<br>이 사물함 주인은 사람이었다. 지금은 모른다.`,
      ng:`뒤지다 사물함 문이 닫히며 손가락을 찧었다.<br><br>손톱이 까맣게 멍들었다. 소리에 탈의실 밖 딸깍 소리가 멈췄다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'우편칸 — 소인',
  x:`우편칸 분류함에 편지가 꽂혔다. 우표마다 소인이 찍혔다.<br><br>
    역 이름이 찍힌 소인이다. 소인은 모으는 물건이다. 어느 역에서, 언제.<br>
    다 이 열차 역들이다. 그런데 하나가 다르다.<br><br>
    소인 날짜가 오늘이고, 역 이름이 시간표에 없다.`,
  o:[
    { l:'① 소인을 날짜순으로 늘어놓는다.', k:'luck', dc:21, wake:1,
      ok:`소인들을 날짜순으로 늘어놓았다. 역 순서대로 찍혔다. 시간표에 없는 역은 끝에서 두 번째 역과 종착 사이에 있다.<br><br>서지 않는 역들 사이에 하나 더 있는 역이다. 편지는 거기서 부쳤다. 누가 거기 내렸다.<br>소인 찍힌 우표를 떼어 수첩에 붙였다. 모은 것이 지도가 됐다.<br><br>늘어놓자 길이 됐다. 모으는 일이 길을 찾는 일이 될 수 있다는 걸 알았다. 손에 든 것들이 처음으로 말을 했다.`,
      ng:`늘어놓는데 소인 잉크가 손가락에 묻는다. 마르지 않았다.<br><br>방금 찍은 소인이다. 분류칸 안쪽에서 도장 찍는 소리가 났다. 쿵. 쿵. 이쪽으로 가까워졌다. 편지를 놓고 나오다 문에 손가락이 끼었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 무게로 사람이 쓴 편지를 가려낸다.', k:'sense', dc:20,
      ok:`편지를 하나씩 손에 올렸다. 대부분 가볍다. 빈 봉투다. 몇 통만 무게가 있다. 사람이 쓴 편지다.<br><br>하나를 열었다. 『맨 앞 칸 화부는 뒤를 안 돈다.』 쓴 사람이 기관실 가까이까지 갔던 것이다. 접어 넣었다.`,
      ng:`무게를 다는데 한 통이 손바닥에서 무거워진다. 점점.<br><br>손목이 꺾일 때 놓았다. 편지가 바닥에 떨어지며 쿵 소리를 냈다. 우편칸 끝 그림자가 고개를 돌렸다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'추격 — 제일 아끼는 것',
  x:`뒤에서 무엇인가 따라온다. 반짝이는 것을 좇는 것 같다.<br><br>
    주머니에 모은 것이 많다. 반짝이는 것도 많다.<br>
    걸을 때마다 주머니 속에서 소리가 난다.<br><br>
    소리가 날 때마다 뒤의 것이 빨라진다.`,
  o:[
    { l:'① 제일 아끼는 것을 반대쪽으로 굴린다.', k:'luck', dc:21,
      ok:`주머니에서 제일 반짝이는 것을 꺼냈다. 유리구슬. 등불에 비추면 무지개가 뜬다. 아끼던 것이다.<br><br>반대쪽 복도 끝으로 굴렸다. 구슬이 굴러가며 반짝인다. 쫓던 것이 그쪽으로 꺾었다.<br>아끼던 것은 아끼던 만큼 일을 한다. 아깝다. 살았다.`,
      ng:`굴렸는데 구슬이 바로 앞에서 멈췄다. 바닥이 기울었다.<br><br>쫓던 것이 구슬과 이쪽을 같이 본다. 둘 다 반짝인다. 주머니를 움켜쥐고 뛰었다. 주머니 끈이 끊어지며 반이 쏟아졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-14 } },
    { l:'② 주머니를 싸매고 등불을 끈다.', k:'hide', dc:20,
      ok:`주머니를 천으로 싸맸다. 물건끼리 부딪지 않게. 소리가 사라졌다.<br><br>반짝이는 것은 빛이 있어야 반짝인다. 등불을 껐다. 어둠 속에서 쫓던 것이 옆을 지나갔다. 아주 가까이. 주머니에 손을 얹고 숨을 참았다.`,
      ng:`싸매는데 하나가 빠져 바닥에 떨어진다. 동전이다.<br><br>쨍. 쫓던 것이 바로 돌아섰다. 동전을 버리고 뛰었다. 등에 무엇인가 스쳤다. 옷이 찢어지고 살갗이 길게 쓸렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B1', t:'야적장 — 녹의 나이',
  x:`야적장 컨테이너가 다 같은 회색이다. 페인트는 같다. 녹은 다르다.<br><br>
    녹으로 쇠의 나이를 안다. 녹이 붉으면 젊고 검으면 늙었다.<br>
    컨테이너 하나만 녹이 없다. 새로 칠했다.<br><br>
    문 경첩만 반짝인다.`,
  o:[
    { l:'① 새로 칠한 것을 피해 늙은 것 뒤로 돈다.', k:'luck', dc:20,
      ok:`새로 칠한 것은 새로 쓸 것이다. 오늘 밤 쓸 것이다. 그 곁으로 안 갔다.<br><br>녹이 제일 검은 컨테이너 뒤로 돌았다. 오래된 것은 아무도 신경 안 쓴다. 바닥 판이 삭아 구멍이 났다. 그 구멍으로 야적장 반대편까지 기어갔다.`,
      ng:`피하는데 다른 컨테이너들도 경첩이 반짝인다. 오늘 다 칠했다.<br><br>어느 것을 피해야 할지 모르는 사이 탐조등이 이쪽을 훑었다. 엎드리다 녹슨 모서리에 손바닥이 찢겼다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 새 페인트를 긁어 밑글씨를 본다.', k:'gaze', dc:21,
      ok:`칼끝으로 페인트를 긁었다. 밑에 지운 글씨가 있다. 『냉장』.<br><br>냉장 컨테이너다. 무엇을 실으려고 칠했는지 안다. 긁은 자리를 손바닥으로 문질러 덮었다.<br>일행에게 그 번호를 외우게 했다. 그 번호 근처에서는 소리를 내지 말라고.`,
      ng:`긁는데 안에서 두드리는 소리가 난다. 세 번.<br><br>이쪽 칼 소리에 답한 것이다. 놀라 칼을 떨어뜨렸다. 컨테이너 밑으로 굴러 들어갔다. 꺼내려 손을 넣었다가 무엇인가에 손등을 긁혔다. 안쪽에서.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B2', t:'기록 보관실 — 다른 손의 이름표',
  x:`기록 보관실 상자마다 손으로 쓴 이름표가 붙었다.<br><br>
    이름표는 글씨를 본다. 누가 썼는지, 같은 손인지.<br>
    대부분 같은 손이다. 상자 셋만 다른 손이다.<br><br>
    그 셋은 선반 맨 아래 칸, 먼지 속에 있다.`,
  o:[
    { l:'① 다른 손이 쓴 상자를 연다.', k:'luck', dc:21,
      ok:`셋 중 하나를 열었다. 기록이 아니다. 도면이다. 병원 층별 도면. 7층에서 1층까지. 비상계단이 끊긴 자리, 세탁물 통로, 서류 내리는 통.<br><br>다른 손은 직원이 아니라 환자 손이었다. 기록 보관실에 몰래 숨긴 것이다. 같은 것들 사이에 숨기면 아무도 안 본다.<br>도면을 접어 넣었다.`,
      ng:`열었는데 상자 안에 상자가 있다. 또 열었다. 또 상자.<br><br>일곱째 상자 안에 쪽지 한 장. 『찾지 마.』 그걸 보는 사이 불이 꺼졌다. 더듬어 나오다 선반 모서리에 눈썹 위를 찢었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 같은 손 글씨의 버릇을 읽는다.', k:'gaze', dc:20,
      ok:`같은 손 글씨를 오래 봤다. 이 손은 '퇴' 자를 쓸 때 꼭 획 하나를 빼먹는다. 서두르는 손이다.<br><br>서두르는 손이 쓴 기록은 빠진 데가 있다. 빠진 날짜를 찾았다. 매달 같은 날 기록이 비었다. 그날 이 손이 자리에 없었다. 오늘이 그날이다.<br>기록이 안 되는 밤에 움직이면 안 남는다.`,
      ng:`보는데 글씨가 이쪽 글씨 같다.<br><br>이쪽 버릇이다. 이쪽도 그 획을 빼먹는다. 이 상자들을 누가 썼는지 생각하기 싫어졌다. 한참 손이 떨렸다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B3', t:'식당칸 — 은수저 한 벌',
  x:`식당칸 식탁마다 수저가 놓였다. 다 도금이다. 한 자리만 은수저다. 진짜 은.<br><br>
    그 자리에 빨간 외투의 손님이 앉아 수프를 먹는다. 얼굴이 숟가락에 비칠 때마다 다르다.<br>
    은수저를 보면 손이 간다. 진짜 은은 독에 검게 변한다.<br><br>
    수집가는 좋은 물건 앞에서 제일 약하다.`,
  o:[
    { l:'① 은수저를 슬쩍한다.', k:'luck', dc:22,
      doom:{ title:'은수저', what:'식탁에 붙들려 있습니다', dc:18, sec:50,
        text:`손님이 고개를 숙일 때 은수저를 집었다.<br><br>집은 손이 식탁에서 안 떨어진다. 손님이 고개를 든다. 수프 숟가락에 비친 얼굴이 이쪽 얼굴이다. 손님이 냅킨을 이쪽 목에 둘러 준다. 앉으라고.<br><br>평생 좋은 것을 모았다. 오늘은 좋은 것이 이쪽을 모은다.`,
        dieText:`식당칸 식탁에 손님 둘이 마주 앉았다.<br><br>둘 다 같은 얼굴로 수프를 먹는다. 은수저는 하나다.<br>다음 역에서도 열차는 서지 않았다.` },
      ok:`손님이 고개를 숙일 때 은수저를 집었다. 대신 제 주머니의 도금 숟가락을 놓았다. 모으는 사람끼리의 예의다.<br><br>손님은 모른다. 도금 숟가락으로 수프를 뜬다. 숟가락 끝이 검게 변한다. 수프에 무엇이 들었는지 이제 안다. 그 손님은 아무렇지도 않게 먹는다.<br>은수저는 품에 넣었다. 이 열차에서 먹을 것은 은으로 먼저 찔러 보기로 했다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 다른 식탁 도금 수저 끝을 본다.', k:'gaze', dc:20,
      ok:`가까이 안 갔다. 다른 식탁 도금 수저를 봤다. 끝이 거뭇하다. 도금도 독에는 조금 변한다.<br><br>식당칸 음식에 다 무엇이 들었다. 은수저 손님 수프만 깨끗하다. 그 손님은 먹는 쪽이 아니라 먹이는 쪽이다.<br>식당칸 음식은 아무도 안 먹게 했다. 주방 뒤 상자에서 날것 그대로의 산나물만 꺼냈다.`,
      ng:`보는데 손님이 은수저를 들어 이쪽을 가리킨다.<br><br>같이 먹자는 뜻이다. 거절하자 수저 끝이 식탁을 톡 친다. 식당칸 손님들이 일제히 이쪽을 본다. 등을 돌리고 칸을 빠져나오는 데 다리가 굳었다.`,
      win:{ exp:18, dream:3, item:'산나물' }, lose:{ mind:-16, spirit:-16 } },
    { l:'③ 주방 칼붙이 사이를 뒤진다.', k:'sense', dc:21,
      ok:`은수저는 두고 주방으로 갔다. 칼, 집게, 국자. 다 도금이다.<br><br>서랍 맨 안쪽 칼붙이 틈에 쇠 열쇠 하나가 끼어 있다. 칼 사이 열쇠는 요리하던 손이 숨긴 것이다. 탄수차로 가는 쪽문 열쇠다.<br>같은 것들 사이 다른 하나는 금방 눈에 띈다.`,
      ng:`뒤지다 칼날을 잡았다. 손바닥이 깊게 베였다.<br><br>피가 서랍에 떨어진다. 식당칸에서 손님이 수저를 내려놓는 소리가 났다. 냄새를 맡은 것이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-10 } }
  ] },

{ at:'B', t:'검문 창구 — 통행증 다섯 장',
  x:`철문 앞 창구다. 통행증을 보이라고 한다.<br><br>
    일행 손에 통행증 다섯 장이 있다. 들어올 때 누가 나눠 준 것이다.<br>
    종이를 안다. 종이 결, 잉크, 도장 번짐.<br><br>
    다섯 장 중 하나가 다르다.`,
  o:[
    { l:'① 다섯 장을 겹쳐 빛에 비춘다.', k:'luck', dc:21, wake:1,
      ok:`다섯 장을 겹쳐 빛에 비췄다. 네 장은 종이 결이 가로다. 한 장만 세로다. 다른 종이다.<br><br>그 한 장을 쥔 일행은 모른다. 누가 그 사람에게만 가짜를 줬다. 창구에서 걸리게. 하나가 걸리면 넷은 지나간다. 하나를 버리는 통행증이다.<br>가짜는 이쪽이 품에 넣었다. 진짜 한 장을 창구에 두 번 내밀었다. 창구 안 손은 종이만 봤지 사람은 안 셌다.<br><br>종이 한 장으로 사람 속을 셌다. 가짜를 가려내던 눈이 가짜를 만든 손까지 보기 시작했다.`,
      ng:`비추는데 다섯 장이 다 같아 보인다. 빛이 모자라다.<br><br>창구 손이 재촉한다. 아무 순서로 냈다. 넷째 장에서 창구 손이 멈췄다. 철문이 내려온다. 넷째 사람을 끌어당겨 같이 굴러 나왔다. 둘 다 무릎이 깨졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 창구 안 도장 테두리를 훔쳐본다.', k:'gaze', dc:20,
      ok:`창구 너머 책상 위 도장을 봤다. 테두리 한 군데가 깨졌다. 진짜 통행증 도장도 거기가 깨져 있어야 한다.<br><br>다섯 장 도장을 봤다. 네 장은 깨졌다. 한 장은 멀쩡하다. 너무 잘 만들었다. 그게 가짜다.<br>그 사람은 창구가 없는 다른 쪽 문으로 돌려보냈다. 다섯이 따로 나가 밖에서 만났다.`,
      ng:`훔쳐보는데 창구 안 눈과 마주쳤다.<br><br>도장을 들여다보는 사람은 도장을 흉내 내는 사람이다. 창구 안은 그렇게 생각했다. 쪽문이 열리고 손이 옷깃을 잡았다. 옷깃을 찢고 빠져나왔다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-14 } },
    { l:'③ 가짜를 쥔 일행에게 그대로 말한다.', k:'bond', dc:19,
      ok:`따로 불러 그 사람 통행증을 같이 봤다. 결이 다르다고. 누가 줬냐고.<br><br>그가 창백해진다. 들어오기 전에 친절한 사람이 줬다고. 다섯 장 중 제일 새것이라고. 새것이 가짜였다.<br>그는 고맙다고 하지 않았다. 대신 그 뒤로 이쪽 뒤를 지켰다.`,
      ng:`말했는데 그가 화를 낸다. 이쪽 것이 가짜일 수도 있지 않냐고.<br><br>둘이 다투는 소리에 창구 불이 켜졌다. 다들 흩어져 숨었다. 숨은 채로 한참 떨었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B1', t:'방파제 계단 — 뼈 손잡이 우산',
  x:`방파제 계단에 검은 우산이 펼쳐진 채 놓였다.<br><br>
    처음에 창고 앞까지 데려다준 남자의 우산과 같다. 손잡이가 뼈로 깎은 것이다.<br>
    이런 손잡이는 안다. 하나씩 깎는다. 같은 우산이 여럿이어도 손잡이는 하나뿐이다.<br><br>
    손잡이 끝에 번호가 새겨졌다.`,
  o:[
    { l:'① 손잡이 번호를 읽는다.', k:'luck', dc:20,
      ok:`번호를 읽었다. 7. 처음 그 남자 우산 손잡이는 3이었다. 같은 우산이 아니다. 같은 사람도 아니다.<br><br>우산 쓴 남자가 여럿이다. 다들 같은 우산을 받았다. 번호마다 맡은 사람이 있다. 3번이 이쪽을 맡았다.<br>7번 우산은 접어서 계단 밑에 숨겼다. 7번이 맡은 사람은 오늘 우산 없는 사람을 못 찾을 것이다.`,
      ng:`읽는데 우산이 바람에 굴러간다. 쫓아갔다.<br><br>방파제 끝까지 굴러 바다에 떨어졌다. 그 끝에 다른 우산이 서 있다. 사람이 쓴 우산이다. 이쪽을 돌아본다. 물러서다 젖은 돌에 미끄러져 꼬리뼈를 찧었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 우산 살 끝 쇠고리를 본다.', k:'sense', dc:21,
      ok:`살 끝마다 작은 쇠고리가 있다. 하나에 실이 감겼다. 실 끝이 방파제 틈으로 이어진다.<br><br>당겼다. 틈에서 기름종이 꾸러미가 딸려 나온다. 안에 말린 고기와 작은 열쇠. 배 열쇠다. 우산 쓴 남자가 오늘 쓰려고 숨겨 둔 몫이다.`,
      ng:`당겼는데 실이 끊어진다. 꾸러미는 틈 속으로 더 들어갔다.<br><br>손을 넣었다. 따개비에 손등이 다 긁혔다. 손끝에 닿기만 하고 안 잡혔다.`,
      win:{ exp:18, dream:3, item:'말린 고기' }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B2', t:'창가 침대 — 종이학',
  x:`창가 침대 환자가 종이학을 접는다. 약 봉투로.<br><br>
    머리맡에 수백 마리가 쌓였다.<br>
    하나하나 본다. 다 같은 접기다.<br><br>
    한 마리만 날개 끝을 안으로 접었다. 다른 손이 접은 것이다.`,
  o:[
    { l:'① 다른 손이 접은 학을 편다.', k:'luck', dc:20, wake:1,
      ok:`그 학을 집어 폈다. 환자가 접는 손을 멈춘다. 말리지 않는다.<br><br>안쪽에 연필 글씨가 있다. 『세탁물 투입구는 4층에서 막힌다. 막힌 데 옆 판자를 밀 것.』 먼저 간 사람이 학 수백 마리 속에 숨긴 것이다. 같은 것 속에 다른 하나.<br>환자가 다시 접기 시작한다. 이쪽에도 하나 접어 준다. 이번엔 날개 끝을 안으로.<br><br>같은 것 수백 개 속에서 다른 손을 찾았다. 모인 것들 사이에서 사람이 남긴 말을 듣는 귀가 생겼다.`,
      ng:`폈는데 안쪽이 비었다. 그냥 약 봉투다.<br><br>환자가 이쪽을 본다. 접은 걸 펴면 안 된다는 눈이다. 정각 점검 때 환자는 이쪽 침대를 가리켰다. 간호사가 이쪽을 두 번 셌다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 모으는 사람이라며 하나만 달라고 한다.', k:'bond', dc:21,
      ok:`하나만 달라고 했다. 모으는 사람이라고.<br><br>환자가 오래 본다. 모으는 사람은 모으는 사람을 알아본다. 이 환자도 모은다. 나간 사람 수만큼 학을.<br>환자가 날개 끝을 안으로 접은 학을 준다. 제일 아끼는 거라고. 펴 보면 길이 있다고. 다들 그렇게 나갔다고.`,
      ng:`달라고 했는데 환자가 학을 끌어안는다.<br><br>하나도 안 된다고. 하나가 빠지면 숫자가 안 맞는다고. 숫자가 안 맞으면 다시 센다고. 환자 비명에 복도 딸깍 소리가 빨라졌다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B3', t:'객차 — 펀치 구멍 모양',
  x:`승객들 표에 구멍이 뚫렸다. 검표 펀치 구멍.<br><br>
    표는 모으는 물건이다. 구멍 모양도 본다. 대부분 동그라미다. 몇 장만 별 모양이다.<br>
    별 모양 구멍 표를 쥔 손님들은 깨어 있다.<br><br>
    동그라미 구멍 표를 쥔 손님들은 다 잔다.`,
  o:[
    { l:'① 별 모양 표를 바꾸자고 청한다.', k:'luck', dc:21, wake:1,
      ok:`모으는 사람이라고 했다. 별 모양 구멍은 처음 본다고. 바꿔 달라고. 진짜로 모으는 사람은 그렇게 말한다.<br><br>손님이 웃는다. 이쪽 표를 받는다. 별 모양 표가 이쪽 손에 왔다. 손님은 이쪽 표를 쥐고 바로 잠이 든다.<br>별은 진짜 차장 펀치다. 동그라미는 가짜 검표원 것. 이제 이 표는 다시 못 뚫는다.<br><br>표 한 장으로 진짜와 가짜를 가렸다. 그 값을 남이 치렀다. 그 무게까지 손이 기억하게 됐다. 모으는 손이 무거워졌다.`,
      ng:`바꾸자고 했는데 손님이 고개를 젓는다. 별은 안 판다고.<br><br>손님 눈이 이쪽 표를 본다. 동그라미 구멍. 안됐다는 눈으로 웃는다. 그 눈길이 한참 따라왔다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 바닥의 펀치 부스러기를 따라간다.', k:'sense', dc:20,
      ok:`좌석 밑 바닥을 봤다. 펀치가 뚫고 떨어뜨린 종이 부스러기가 있다. 동그라미가 많다. 별은 몇 개 없다.<br><br>별 부스러기는 차장실 쪽으로 이어진다. 진짜 차장은 차장실 근처만 돈다. 그쪽으로 갔다. 차장실 문틈에 시간표 사본이 꽂혀 있었다. 역마다 몇 분 늦게 지나는지까지 적힌 것.`,
      ng:`엎드려 찾다가 좌석 밑에서 손 하나와 마주쳤다.<br><br>누가 좌석 밑에 누워 있다. 동그라미 구멍 표를 쥐었다. 이쪽 손목을 잡았다. 차다. 뿌리치다 손목이 꺾였다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B', t:'쉬는 자리 — 주머니 정리',
  x:`쉬는 자리에서 주머니를 털었다.<br><br>
    너무 많이 모았다. 걸음이 느려졌다. 뛰어야 하는 밤에 무거우면 진다.<br>
    반은 버려야 한다.<br><br>
    수집가에게 버리는 일은 고르는 일보다 어렵다.`,
  o:[
    { l:'① 진짜만 남긴다.', k:'luck', dc:20, wake:1,
      ok:`하나씩 손바닥에 올려 무게와 결을 봤다.<br><br>진짜는 셋. 열쇠 하나, 쪽지 하나, 단추 하나. 나머지는 다 흉내거나 잡것이다. 셋만 남기고 다 놓았다. 주머니가 가벼워졌는데 값은 그대로다.<br><br>무엇이 진짜인지 아는 사람은 버리는 것이 아깝지 않다. 버린 무게만큼 걸음이 빨라졌다. 고르는 일을 손이 끝까지 해냈다.`,
      ng:`보다가 눈이 흐려진다. 지쳤다.<br><br>진짜를 버리고 흉내를 남겼다. 한참 뒤에 그걸 알았다. 버린 자리로 돌아갈 수는 없었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-14, spirit:-14 } },
    { l:'② 쓸모로 고른다.', k:'steady', dc:19,
      ok:`예쁜 것은 버리고 쓸 것만 남겼다.<br><br>남긴 끈 묶음 속에서 말린 약초 한 다발이 나왔다. 언제 주웠는지 모른다. 쓸모로 고르면 쓸 것이 나온다.`,
      ng:`고르다 보니 다 쓸모가 있어 보인다.<br><br>결국 하나도 못 버렸다. 짐은 그대로다. 그대로 뛰다 계단에서 넘어졌다. 주머니가 터지며 반이 쏟아졌다.`,
      win:{ exp:16, dream:2, item:'약초 뭉치' }, lose:{ hp:-20, mind:-12 } }
  ] },

{ at:'B', t:'옷걸이 — 같은 외투 다섯',
  x:`문 옆 옷걸이에 외투 다섯이 걸렸다. 같은 색, 같은 단추.<br><br>
    물기가 떨어진다. 방금 들어온 사람들 것이다.<br>
    방 안에는 아무도 없다.<br><br>
    같은 물건 다섯이 있으면 다섯이 어떻게 다른지부터 본다.`,
  o:[
    { l:'① 다섯 주머니에 차례로 손을 넣는다.', k:'luck', dc:21,
      ok:`다섯 주머니에 손을 넣었다. 넷은 비었다. 하나에 성냥갑이 있다.<br><br>성냥갑 뒷면에 주소 대신 시각이 적혔다. 넷은 시킨 대로 온 사람이고 하나는 시키는 사람이다. 시키는 사람만 시각을 들고 다닌다.<br>성냥갑은 도로 넣었다. 그 외투 단추 하나를 떼어 왔다. 나중에 그 외투를 보면 알아볼 것이다.`,
      ng:`넣는데 외투 안이 따뜻하다. 사람이 입은 온기다.<br><br>외투가 움직였다. 안에 누가 있다. 걸린 게 아니라 서 있었다. 손을 빼고 문 밖으로 뛰었다. 소매가 문에 끼어 어깨가 젖혀졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 단추를 단 실을 본다.', k:'gaze', dc:20,
      ok:`단추를 봤다. 다섯 다 같은 단추. 실이 다르다. 넷은 공장 실. 하나는 손으로 다시 단 실이다. 떨어진 걸 제 손으로 단 것이다.<br><br>그 외투만 오래 입었다. 오래 입은 외투 주인이 우두머리다. 나머지는 새로 받은 옷이다.<br>오래 입은 외투가 어느 문으로 나가는지만 보면 된다. 그 문만 피했다.`,
      ng:`보는데 단추 하나가 툭 떨어진다. 이쪽 발밑에.<br><br>주우려 숙이는데 방문이 열렸다. 다섯이 돌아왔다. 이쪽은 옷걸이 뒤에 섰다. 한 사람이 단추 떨어진 외투를 들고 오래 바닥을 봤다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'진열실 — 이름표 다섯 장',
  x:`방 벽마다 선반이다. 젖은 신발, 깨진 손목시계, 출입증, 머리끈. 하나같이 사람이 쓰던 것이다.<br><br>
    이름표마다 날짜와 시각이 적혀 있다.<br>
    이런 진열은 안다. 제 방에도 이런 선반이 있다.<br><br>
    맨 끝 선반이 비었다. 이름표가 다섯 장 놓였다.`,
  o:[
    { l:'① 진열실 주인을 찾는다.', k:'gaze', dc:22,
      doom:{ title:'빈 선반', what:'선반에 올려지고 있습니다', dc:18, sec:50,
        text:`이름표를 떼려고 손을 뻗었다.<br><br>손이 이름표에 붙었다. 떼려니 선반이 당긴다. 발이 바닥에서 뜬다. 선반 높이로 올라간다.<br><br>평생 물건을 선반에 올렸다. 제가 올라가는 것은 처음이다. 등 뒤에서 누가 흡족하게 고개를 끄덕이는 것 같다.`,
        dieText:`맨 끝 선반에 하나가 찼다.<br><br>이름표 옆에 날짜와 시각이 적혔다. 오늘이다.<br>나머지 이름표 넷이 선반 위에서 기다린다.` },
      ok:`선반 말고 바닥을 봤다. 먼지에 발자국이 있다. 한 사람 것이다. 아주 오래 오갔다.<br><br>발자국이 선반 뒤로 사라진다. 선반을 밀었다. 뒤에 좁은 통로가 있다. 주인이 드나들던 길이다. 주인은 이미 진열됐다. 맨 첫 선반에.<br>이름표 다섯 장을 떼어 주머니에 넣고 통로로 나왔다.<br><br>남의 손에 모이지 않는 것도 모으는 사람의 솜씨다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 제일 오래된 것 하나를 가져온다.', k:'luck', dc:21,
      ok:`날짜가 제일 오래된 것을 골랐다. 낡은 놋 호루라기.<br><br>불어 보니 소리가 맑다. 진짜 놋이다. 이 방에서 유일하게 좋은 손이 만든 물건이다. 다른 것들은 다 흉내다. 진열한 사람도 진짜를 몰랐다.<br>그냥 모은 사람이다. 그런 사람 선반에는 올라갈 이유가 없다.`,
      ng:`집었는데 이름표가 같이 딸려 온다.<br><br>이름표 뒤에 이쪽 이름이 또 적혀 있다. 도로 놓고 나왔다. 등이 서늘했다. 그 이름표가 언제부터 거기 있었는지 생각하지 않으려 했다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'③ 일행의 물건을 몰래 빼 온다.', k:'hide', dc:20,
      ok:`선반 가운데 낯익은 물건이 있다. 일행 하나가 아까 잃어버렸다던 장갑. 이름표에 시각이 아직 안 적혔다.<br><br>조용히 집어 품에 넣었다. 이름표는 떼어 찢었다. 아직 안 끝난 진열은 빼 올 수 있다.<br>장갑을 돌려주니 일행 얼굴이 하얘졌다. 어디서 찾았냐고 묻지 않았다.`,
      ng:`집는데 선반 전체가 덜컹한다. 하나가 빠지면 진열이 무너진다.<br><br>물건들이 쏟아졌다. 쏟아진 물건에 발이 걸렸다. 넘어지며 깨진 시계 유리에 손바닥을 찔렸다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B', t:'내려가는 계단 — 목록',
  x:`계단 앞에서 목록을 적었다.<br><br>
    주운 것을 하나하나. 어디서, 언제, 어떻게.<br>
    다 적고 보니 목록에 하나가 더 있다.<br><br>
    적은 기억이 없는 줄이다. 이쪽 글씨다.`,
  o:[
    { l:'① 목록과 물건을 하나씩 맞춰 본다.', k:'luck', dc:20, wake:1,
      ok:`물건을 하나씩 꺼내 목록에 짚었다.<br><br>마지막 줄에 맞는 물건이 주머니 바닥에 있다. 주운 기억이 없다. 그런데 손에 익다. 진짜다. 물건이 스스로 목록에 들어왔다.<br><br>진짜는 진짜를 알아보는 사람에게 모인다. 모으는 손보다 가려내는 눈이 먼저 움직이게 됐다.`,
      ng:`맞추다 보니 마지막 줄에 맞는 물건이 없다.<br><br>목록에는 있는데 없다. 아니면 아직 안 주운 것이다. 계단 아래가 갑자기 깊어 보였다.`,
      win:{ exp:22, dream:4 }, lose:{ mind:-16, spirit:-12 } },
    { l:'② 모르는 줄을 지운다.', k:'steady', dc:19,
      ok:`모르는 줄에 줄을 그었다. 모르는 것은 모르는 것이다. 목록을 거짓으로 채우지 않는다.<br><br>목록을 접고 내려갔다. 계단이 생각보다 단단했다.`,
      ng:`줄을 그었는데 그 줄만 안 지워진다. 몇 번을 그어도 그대로다.<br><br>손이 떨려 목록을 접었다. 계단 셋째 칸에서 발을 헛디뎠다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-20, mind:-12 } },
    { l:'③ 목록을 일행에게 소리 내 읽어 준다.', k:'bond', dc:21,
      ok:`목록을 소리 내 읽었다. 어디서 무엇을 주웠는지.<br><br>일행이 하나씩 끼어든다. 그건 내가 봤다, 그건 내가 넘겨줬다. 목록이 다섯 사람 기억으로 채워진다. 모르는 줄도 누가 안다. 일행 하나가 몰래 넣어 준 것이었다. 고맙다는 말 대신.<br><br>혼자 모은 것이 아니었다.`,
      ng:`읽는데 일행 하나가 고개를 젓는다. 그건 자기 거라고.<br><br>목록 한 줄을 두고 다툼이 길어졌다. 계단 위에서 문 열리는 소리가 날 때까지 다퉜다. 다 같이 굴러 내려갔다.`,
      win:{ exp:18, dream:3, mind:6 }, lose:{ hp:-24, mind:-12 } }
  ] }

]);

// ==========================================
// 🥣 거지 (beggar) · 내공
// ==========================================
kJob('beggar', 'B', [

{ at:'B', t:'빗속 처마 — 아무도 안 보는 사람',
  x:`비가 억수같이 온다. 골목 끝에서 손전등 둘이 이쪽으로 온다. 사람을 찾는다.<br><br>
    일행은 숨을 데를 찾아 흩어진다.<br>
    거지는 숨지 않는다. 평생 숨을 필요가 없었다. 사람들은 거지를 안 본다.<br><br>
    처마 밑에 그릇을 내려놓았다.`,
  o:[
    { l:'① 그릇을 앞에 두고 쪼그려 앉는다.', k:'luck', dc:20, wake:1,
      ok:`무릎을 끌어안고 고개를 숙였다. 그릇에 빗물이 고인다.<br><br>손전등이 처마 밑을 훑는다. 그릇에서 한 번, 정수리에서 한 번 멈춘다. 그리고 지나간다. 찾는 건 사람이다. 빌어먹는 사람은 사람으로 안 친다.<br>손전등이 지나간 뒤 일어섰다. 일행 숨은 데를 돌며 알려 줬다. 손전등은 다 엉뚱한 데로 갔다고.<br><br>안 보이는 사람이 되는 법을 처음으로 남을 위해 썼다. 쪼그려 앉는 자세 하나가 숨는 법이 되고, 숨는 법이 지키는 법이 됐다.`,
      ng:`쪼그려 앉았는데 손전등이 그릇에서 안 떠난다.<br><br>그릇이 너무 깨끗하다. 비가 씻었다. 깨끗한 그릇은 빌어먹는 그릇이 아니다. 손전등이 얼굴로 올라왔다. 뛰었다. 젖은 바닥에 손바닥을 갈았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 내공을 끌어내려 숨을 죽인다.', k:'hide', dc:20, cost:{ qi:22 },
      ok:`처마 그림자에 붙어 내공을 아랫배로 끌어내렸다. 숨이 길어진다. 몇 번 안 쉬어도 된다.<br><br>손전등이 바로 앞을 지나간다. 숨 쉬지 않는 것은 벽이다. 벽은 아무도 안 본다.<br>손전등이 골목 끝으로 사라진 뒤에야 숨을 한 번 내쉬었다. 입김이 길었다.`,
      ng:`끌어내리는데 빗물이 목덜미로 들어간다. 차다.<br><br>숨이 터졌다. 기침이 났다. 손전등 둘이 동시에 이쪽을 비췄다. 처마를 차고 뛰었다. 정강이가 계단 모서리에 찍혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 세는 손가락',
  x:`창고 구석에서 회색 비옷이 일행을 센다. 멀리서. 손가락을 하나씩 접는다.<br><br>
    칠판에 적힌 숫자는 다섯이다. 일행은 다섯이다. 빌어먹는 사람까지 쳐서.<br>
    사람들이 셀 때 저를 빼먹는 걸 평생 봤다.<br><br>
    저 비옷은 빼먹지 않는다.`,
  o:[
    { l:'① 셈에서 빠지려고 쓰레기 더미에 눕는다.', k:'luck', dc:22,
      doom:{ title:'치울 것', what:'쓰레기와 함께 쓸려 갑니다', dc:17, sec:55,
        text:`쓰레기 더미에 누웠다. 젖은 상자, 생선 비늘, 찢긴 그물. 평생 덮고 잔 이불과 같다.<br><br>장화 소리가 온다. 비옷이 더미 앞에 선다. 세지 않는다. 대신 빗자루를 든다.<br>더미째 쓸린다. 셈에서 빠진 것은 사람이 아니라 쓰레기다. 쓰레기는 치운다. 비옷이 하는 일이 그것이다.<br><br>거지는 그걸 너무 늦게 알았다.`,
        dieText:`창고 바닥이 깨끗하다.<br><br>쓰레기 더미가 있던 자리에 물자국만 남았다. 바다 쪽으로 한 줄.<br>칠판 숫자는 그대로다. 다섯. 비옷이 손가락을 하나 더 접는다.` },
      ok:`쓰레기 더미에 누웠다. 젖은 상자, 생선 비늘, 찢긴 그물.<br><br>장화 소리가 온다. 비옷이 더미 앞에 선다. 빗자루를 든다. 빗자루 소리는 먼저 안다. 평생 쓸려 다녔다.<br>쓸리기 전에 굴러 나왔다. 더미가 쓸려 가는 쪽과 반대로.<br><br>비옷은 더미만 쓸었다. 손가락은 넷에서 멈췄다. 쓰레기 속에서 쓰레기 하나가 굴러 나간 것까지는 안 센다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 비옷이 세는 버릇을 본다.', k:'gaze', dc:20,
      ok:`비옷은 오른쪽부터 센다. 하나 셀 때마다 고개를 끄덕인다.<br><br>끄덕일 때 눈을 감는다. 아주 잠깐. 그 틈에 일행 둘이 자리를 바꾸게 했다. 비옷은 다시 세야 한다. 다시 셀 때마다 시간이 간다.<br>다섯 시 십 분까지 비옷은 세 번 다시 셌다. 셈은 끝내 안 맞았다.`,
      ng:`보는데 비옷 손가락이 이쪽을 가리킨 채 멈춘다.<br><br>이쪽이 보고 있다는 것을 셌다. 비옷이 고개를 끄덕인다. 확실히 셌다는 끄덕임이다. 그 뒤로 등 뒤에서 장화 소리가 끊이지 않았다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'③ 구석 버린 상자를 뒤진다.', k:'sense', dc:19,
      ok:`세는 건 세게 두고 구석 버린 상자를 뒤졌다. 버린 데서 사는 사람이다.<br><br>생선 상자 밑바닥에 말린 고기 꾸러미가 깔려 있다. 하역부 누가 숨겨 두고 못 가져간 것이다. 품에 넣었다.<br>버린 것을 아는 사람이 숨긴 것도 안다.`,
      ng:`뒤지다 상자 사이 쥐덫을 짚었다.<br><br>손가락이 물렸다. 쇠 소리가 창고에 울렸다. 비옷의 손가락이 이쪽에서 멈췄다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B2', t:'정각 — 세어지지 않는 자리',
  x:`정각이다. 간호사가 계수기를 누르며 온다.<br><br>
    평생 세어지지 않았다. 그릇 앞을 지나는 사람들은 빌어먹는 사람을 세지 않는다.<br>
    그런데 여기서는 세어지지 않는 것이 더 위험하다.<br><br>
    숫자가 안 맞으면 맞을 때까지 센다.`,
  o:[
    { l:'① 침대 밑, 늘 자던 자리에 눕는다.', k:'luck', dc:21,
      ok:`침대 밑으로 들어갔다. 침대 밑은 평생 자던 자리다. 위에는 일행이 누웠다.<br><br>간호사가 침대 하나에 하나를 센다. 침대 밑은 안 센다. 침대는 하나다. 하나를 셌다.<br>숫자는 맞았다. 다섯 침대, 다섯 사람. 침대 밑 하나는 처음부터 없는 사람이다. 그 자리를 평생 알았다.`,
      ng:`들어갔는데 침대 밑에 먼저 누가 있다.<br><br>이쪽을 보고 손가락을 입에 댄다. 쉿. 그 손가락이 차다. 간호사가 침대 밑을 들여다본다. 둘을 센다. 딸깍, 딸깍. 숫자가 넘쳤다. 그 뒤로 정각마다 이쪽 침대 앞에서 오래 멈췄다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 먼저 크게 대답해 확실히 세어진다.', k:'steady', dc:19,
      ok:`간호사가 이름을 부르기 전에 먼저 대답했다. 크게. 지나가는 사람을 불러 세우는 목소리로.<br><br>간호사가 멈칫한다. 세는 사람은 먼저 나서는 사람을 제일 확실하게 센다. 딸깍. 이쪽은 확실하게 하나다.<br>세어지는 것이 무섭지 않았다. 처음 겪는 일이다. 나쁘지 않았다.`,
      ng:`대답했는데 목소리가 쉬었다. 비에 목이 상했다.<br><br>간호사가 다시 부른다. 대답했다. 또 부른다. 세 번째 대답할 때 간호사가 계수기를 두 번 눌렀다. 셋으로 세어졌는지 하나로 세어졌는지 모르겠다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B3', t:'9호차 — 표 없는 손님',
  x:`검표원이 객차 끝에서 온다. 펀치 소리가 일정하다.<br><br>
    손에 표가 없다. 처음부터 없었다. 열차를 공짜로 타 본 적은 많다.<br>
    표 없는 사람이 열차에서 숨는 데는 세 군데다.<br><br>
    의자 밑, 칸 사이, 그리고 검표원 눈앞.`,
  o:[
    { l:'① 칸 사이 연결판으로 나간다.', k:'luck', dc:21, wake:1,
      ok:`객차 문을 열고 칸 사이로 나갔다. 연결판이 흔들린다. 비가 옆에서 친다.<br><br>검표원은 칸 안만 돈다. 칸 사이는 열차가 아니다. 열차가 아닌 데는 표가 필요 없다. 펀치 소리가 안에서 지나간다.<br>다음 칸 문이 안 잠겨 있었다. 검표가 끝난 칸이다. 일행을 하나씩 칸 사이로 불러냈다.<br><br>혼자 몰래 하던 일을 여럿이서 했다. 혼자 살아남던 버릇이 무리를 살리는 버릇으로 바뀌었다.`,
      ng:`연결판에 섰는데 열차가 크게 꺾인다.<br><br>판이 미끄러졌다. 난간을 붙잡았다. 손바닥이 쇠에 쓸려 벗겨졌다. 빗물에 피가 씻겨 내려갔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 빈자리 의자 밑에 눕는다.', k:'hide', dc:20,
      ok:`빈자리 의자 밑으로 기어 들어갔다. 다리를 접었다. 좁은 데서 잘 잔다.<br><br>검표원 구두가 지나간다. 의자 위 표만 뚫는다. 의자 밑은 안 본다. 의자 밑에서 사는 사람이 있다는 걸 모른다.`,
      ng:`기어 들어갔는데 의자 밑에 이미 표가 있다. 구멍이 둘 뚫린 표.<br><br>표 주인은 안 보인다. 표만 있다. 검표원 구두가 멈췄다. 표를 집으려 손이 내려온다. 이쪽 손과 닿았다. 차다. 손등이 한참 얼얼했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-16 } },
    { l:'③ 표 대신 손바닥을 내민다.', k:'bond', dc:22,
      ok:`일어서서 손바닥을 내밀었다. 표 대신. 평생 내민 손이다.<br><br>검표원이 멈춘다. 표 없는 손님은 많다. 동냥하는 손님은 처음이다. 펀치가 손바닥 위에서 망설인다.<br>검표원이 주머니에서 무엇인가 꺼내 손바닥에 놓았다. 별 모양 구멍이 뚫린 표 조각이다. 쥐고 있으면 다음 검표원이 안 뚫는다고 한다. 동냥 값이다.`,
      ng:`손을 내밀었는데 펀치가 손바닥에 내려왔다.<br><br>딸깍. 손바닥에 구멍이 뚫렸다. 피는 안 난다. 손바닥이 한참 남의 것 같았다. 쥐어지지 않았다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B', t:'골목 벽 — 무릎 높이의 분필',
  x:`골목 벽 아래, 무릎 높이에 분필 자국이 있다.<br><br>
    다른 사람은 낙서로 본다. 아니다. 동그라미 하나에 가로줄 둘. 같은 업이 남기는 표식이다.<br>
    동그라미는 사람 있음. 줄 둘은 두 번 꺾어.<br><br>
    빗물이 분필을 조금씩 지우고 있다.`,
  o:[
    { l:'① 표식대로 두 번 꺾는다.', k:'luck', dc:20,
      ok:`두 번 꺾었다. 세 번째 골목은 안 들어갔다.<br><br>꺾은 끝에 무너진 담장이 있다. 담장 밑으로 기어 나가면 큰길이다. 먼저 간 누가 뒤에 올 사람을 위해 남겼다. 얼굴도 모르는 사람이다.<br>담장 밑 마른 자리에 꿀 한 줌이 기름종이에 싸여 있었다. 표식 남긴 사람이 같이 두고 간 것이다.`,
      ng:`꺾었는데 표식이 빗물에 번져 줄이 셋으로 보였다.<br><br>세 번 꺾었다. 세 번째 골목 끝에 손전등이 서 있었다. 돌아 나오다 쓰레기통에 무릎을 박았다.`,
      win:{ exp:18, dream:3, item:'꿀 한 줌' }, lose:{ hp:-22, mind:-12 } },
    { l:'② 제 표식을 덧그려 남긴다.', k:'bond', dc:19,
      ok:`주운 분필로 표식 옆에 하나를 더 그었다. 세모. 조심. 그 밑에 손전등 그림.<br><br>뒤에 올 사람을 위한 것이다. 받은 만큼 남긴다.<br>그리고 표식대로 갔다. 그은 세모를 보고 일행 하나가 처음으로 그게 뭐냐고 물었다. 알려 줬다. 표식을 아는 사람이 하나 늘었다.`,
      ng:`긋는데 분필이 부러진다. 세모가 반만 그려졌다.<br><br>반쪽 세모는 여기서 자라는 뜻이다. 뒤에 올 사람에게 미안해졌다. 고치다 손전등에 들킬 뻔했다. 몸을 날려 숨다 팔꿈치를 찧었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B1', t:'어시장 뒤 — 버린 생선 통',
  x:`경매장 뒤에 버린 생선 통이 줄지어 있다. 비린내가 진동한다.<br><br>
    일행은 코를 막고 지나간다. 코를 안 막는다. 버린 통은 장터다.<br>
    버린 것 중에 안 버려도 될 것이 있다.<br><br>
    그걸 아는 코가 있다.`,
  o:[
    { l:'① 제일 무거운 통 바닥까지 손을 넣는다.', k:'luck', dc:21,
      ok:`팔을 걷고 제일 무거운 통에 넣었다. 미끄러운 것들 사이로 손바닥이 더듬는다.<br><br>바닥에 아직 숨 쉬는 것이 있다. 민물고기다. 바닷고기 사이에 왜 섞였는지 모른다. 살아 있다. 꺼냈다.<br>버린 것들 바닥에서 산 것을 건졌다. 이 손은 바닥에서 산다.`,
      ng:`넣었는데 통 안에서 갈고리 하나가 손등을 긁는다.<br><br>버린 게 아니라 숨겨 둔 것이다. 갈고리 끝에 무엇이 걸려 있다. 꺼내 보지 않았다. 손등이 깊이 패였다.`,
      win:{ exp:18, dream:3, item:'민물고기' }, lose:{ hp:-26, mind:-12 } },
    { l:'② 내공을 코끝에 모아 성한 것을 가린다.', k:'sense', dc:20, cost:{ qi:22 },
      ok:`숨을 가라앉히고 내공을 코끝으로 모았다.<br><br>비린내 사이로 짠 냄새, 마른 냄새가 갈라진다. 통 셋째 줄 맨 끝. 썩은 것 밑에 소금 덩이가 깔려 있다. 하역부들이 몰래 생선을 절이던 것이다.<br>소금 덩이를 털어 챙겼다. 썩은 냄새 속에서 안 썩은 것을 맡는 코는 배고픔이 길러 줬고, 내공이 조금 보탰다.`,
      ng:`모으는데 썩은 기운이 같이 올라온다.<br><br>내공이 냄새를 다 끌어들였다. 속이 뒤집혔다. 통 옆에 엎드려 한참 토했다. 노란 비옷 하나가 멀리서 그걸 봤다.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B2', t:'복도 벽 — 세탁물 투입구',
  x:`복도 벽에 세탁물 투입구가 있다. 쇠 뚜껑을 열면 아래로 통이 뚫렸다. 사람 하나 들어갈 만하다.<br><br>
    이런 데는 안다. 쓰레기 통로, 석탄 통로, 빨래 통로. 사람이 안 다니는 길이 제일 빠르다.<br>
    통 안에서 바람이 올라온다.<br><br>
    바닥이 얼마나 깊은지는 모른다.`,
  o:[
    { l:'① 뛰어든다.', k:'luck', dc:22,
      doom:{ title:'빨래 통', what:'통로 속으로 빨려 내려갑니다', dc:17, sec:55,
        text:`뛰어들었다. 미끄러진다. 빠르다. 생각보다 빠르다.<br><br>아래층 투입구를 지나친다. 또 지나친다. 4층에서 막힌다던 통이 막히지 않는다. 내려갈수록 통이 좁아진다. 어깨가 낀다.<br><br>좁은 데서 잘 자는 몸이다. 평생 그랬다. 이번에는 깨어날 일이 없을 것 같다.`,
        dieText:`지하 세탁실 바구니에 빨래가 쏟아졌다.<br><br>흰 시트, 흰 환자복, 그리고 낡은 옷 한 벌.<br>세탁부가 낡은 옷을 집어 들고 한참 본다. 그리고 소각로 쪽 바구니에 던졌다.` },
      ok:`뛰어들기 전에 시트 두 장을 묶어 뚜껑 경첩에 걸었다. 아무 데나 뛰어들지 않는다. 끈부터 맨다.<br><br>시트를 쥐고 천천히 내려갔다. 4층 투입구에서 통이 막혀 있다. 막힌 데 옆 판자를 밀었다. 4층 복도로 굴러 나왔다.<br>시트는 그대로 두었다. 뒤에 올 일행이 쓸 것이다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 통에 귀를 대고 깊이를 잰다.', k:'sense', dc:20,
      ok:`귀를 댔다. 빨래 떨어지는 소리가 툭툭 끊긴다. 층마다 꺾이는 데가 있다. 네 번 꺾이고 멈춘다.<br><br>4층이다. 그 아래로는 소리가 안 간다. 막혔다. 막힌 데까지는 갈 수 있다.<br>일행에게 하나씩, 발부터 내려가라고 일렀다. 머리부터 들어가면 꺾이는 데서 목이 꺾인다. 쓰레기 통로에서 배운 것이다.`,
      ng:`귀를 대는데 통 안에서 누가 올라온다. 기어서.<br><br>숨소리가 가까워진다. 뚜껑을 닫았다. 쇠 뚜껑을 안에서 두드린다. 한참. 뚜껑을 누른 팔이 저리도록 버텼다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, spirit:-16 } },
    { l:'③ 빨래 더미에 섞여 세탁 수레를 탄다.', k:'hide', dc:21,
      ok:`복도 끝 세탁 수레에 빨래가 산더미다. 그 속에 파고들었다. 남의 옷 속에서 자 본 적이 많다.<br><br>세탁부가 수레를 민다. 화물 승강기다. 위로만 간다던 승강기가 빨래는 아래로 내린다. 빨래 속에서 숨을 죽였다.<br>3층에서 수레가 멈췄을 때 빠져나왔다.`,
      ng:`파고드는데 빨래가 젖어 있다. 차다. 무엇인가 묻어 있다.<br><br>그 냄새에 재채기를 했다. 세탁부가 빨래를 뒤적인다. 손이 발목을 잡았다. 차고 젖은 손이다. 뿌리치고 굴러 나오다 수레 모서리에 갈비뼈를 찧었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B3', t:'식당칸 — 세 숟가락',
  x:`식당칸 식탁마다 먹다 남긴 접시가 있다. 고기, 빵, 수프. 손님들은 다 자리를 비웠다.<br><br>
    남긴 접시는 그냥 못 지나간다.<br>
    그런데 이 열차에서 남긴 음식은 다 같은 데까지만 먹었다.<br><br>
    세 숟가락. 모두 세 숟가락에서 멈췄다.`,
  o:[
    { l:'① 아무도 손대지 않은 접시를 찾는다.', k:'luck', dc:21,
      ok:`식탁을 하나씩 봤다. 세 숟가락, 세 숟가락. 맨 끝 식탁 접시 하나만 숟가락 자국이 없다.<br><br>먹지 않은 사람은 먹으면 안 되는 걸 알았던 사람이다. 접시 밑에 냅킨이 깔려 있다. 냅킨에 『주방 뒤 상자』.<br>주방 뒤 상자에 말린 고기가 있었다. 열차에 오르기 전에 누가 사 둔 것이다.`,
      ng:`찾는데 세 숟가락 접시에서 냄새가 너무 좋다.<br><br>한 숟가락만 떴다. 배는 튼튼하다. 그런데 두 번째 숟가락을 뜨고 싶다. 세 번째도. 일행이 숟가락을 빼앗았다. 그 뒤로 한참 손이 접시 쪽으로 갔다.`,
      win:{ exp:18, dream:3, item:'말린 고기' }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 빵 껍질만 모은다.', k:'steady', dc:20,
      ok:`수프도 고기도 안 먹었다. 빵 껍질만 모았다. 빵 속보다 껍질을 믿는다. 껍질은 굽는 손 말고는 아무도 안 만진다.<br><br>껍질을 씹었다. 아무 일도 없다. 일행에게 껍질만 나눠 줬다. 배가 조금 찼다.<br>남긴 음식도 남긴 까닭이 다 다르다. 그걸 보는 눈이 빌어먹는 사람의 눈이다.`,
      ng:`모으는데 껍질 안쪽에 수프가 배어 있다.<br><br>씹고 나서 알았다. 머리가 무거워진다. 의자에 앉아 한참 눈을 감았다. 깨어 보니 한 역이 지나 있었다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B', t:'다리 밑 — 진흙',
  x:`뒤에서 여럿이 쫓아온다. 숨을 데가 없다.<br><br>
    다리 밑에 진흙이 고였다.<br>
    진흙에서 자 본 적이 있다. 진흙을 덮으면 사람이 아니라 땅이 된다.<br><br>
    다리 위로 발소리가 가까워진다.`,
  o:[
    { l:'① 진흙을 뒤집어쓰고 다 같이 눕는다.', k:'luck', dc:21, wake:1,
      ok:`진흙을 얼굴까지 발랐다. 다리 기둥 밑에 웅크렸다. 일행에게도 시켰다. 다들 질색하다가 따랐다.<br><br>쫓는 발소리가 다리 위를 지나간다. 손전등이 다리 밑을 훑는다. 진흙 덩이 다섯. 지나간다.<br>쫓던 것들이 사라진 뒤 진흙 덩이 다섯이 일어섰다. 다들 이쪽을 봤다. 처음으로 이 몰골을 부러워하는 얼굴이었다.<br><br>혼자 살던 법을 무리에게 나눴다. 하나가 무리 하나가 되는 길이 손에 잡혔다.`,
      ng:`바르는데 진흙이 차다. 이가 딱딱 부딪친다.<br><br>그 소리를 손전등이 들었다. 다리 밑을 비춘다. 진흙 덩이 하나가 떨고 있다. 손이 내려와 옷깃을 잡았다. 진흙이 미끄러워 빠져나왔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 내공을 돌려 찬물 속에서 버틴다.', k:'steady', dc:20, cost:{ qi:24 },
      ok:`다리 기둥 뒤 물웅덩이에 몸을 담갔다. 내공을 돌렸다. 배꼽 밑에서 열이 인다.<br><br>찬물 속에서 몸이 버틴다. 손전등은 물속까지 안 비춘다. 쫓던 것들이 지나갈 때까지 머리만 내놓고 있었다.<br>내공은 이불이다. 물속에서도.`,
      ng:`돌리는데 찬물이 기를 끊는다.<br><br>가슴이 결린다. 숨이 가빠진다. 물 위로 입김이 올라왔다. 손전등이 그 입김을 따라왔다. 물에서 기어 나와 뛰었다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B1', t:'방파제 밑 — 먼저 자고 간 자리',
  x:`방파제 밑 콘크리트 틈에 마른 데가 있다. 바다 쪽에서도, 위에서도 안 보인다.<br><br>
    잠자리는 한눈에 안다.<br>
    누가 먼저 자고 간 흔적이 있다. 거적 한 장, 깨진 그릇 하나.<br><br>
    그릇에 빗물이 고였다.`,
  o:[
    { l:'① 먼저 잔 사람의 흔적을 읽는다.', k:'luck', dc:20, wake:1,
      ok:`거적을 들췄다. 밑에 손톱으로 긁은 줄이 있다. 날짜를 센 줄이다. 마지막 줄 옆에 그림이 하나. 배 모양. 그 위에 가위표.<br><br>해무호에는 타지 말라는 뜻이다. 먼저 잔 사람이 알았다.<br>그릇의 빗물은 마셨다. 거적은 도로 덮었다. 다음 사람도 읽어야 한다.<br><br>얼굴도 모르는 사람이 남긴 줄을 읽었다. 흩어진 사람들을 잇는 줄이 어딘가 길게 이어져 있다는 것이 처음으로 눈에 보였다.`,
      ng:`들췄는데 거적 밑에서 무엇인가 꿈틀한다. 게다. 수십 마리.<br><br>손등을 물렸다. 놀라 일어서다 콘크리트 천장에 머리를 박았다. 한참 눈앞이 하얬다.`,
      win:{ exp:22, dream:3, item:'맑은 물' }, lose:{ hp:-22, mind:-12 } },
    { l:'② 일행을 거기 재운다.', k:'bond', dc:21,
      ok:`다섯을 틈에 밀어 넣었다. 좁다. 등을 맞대게 했다. 머리는 바람 반대쪽.<br><br>다들 어색해하다 곧 잠든다. 한 시간. 해무호 출항 전까지 한 시간을 잤다. 그 한 시간이 마지막 방파제를 건너게 했다.<br>혼자만 안 잤다. 남이 잘 때 지키는 것도 제 몫이다.`,
      ng:`밀어 넣는데 하나가 거부한다. 빌어먹는 사람 잠자리에서는 못 잔다고.<br><br>실랑이 소리가 방파제 위로 올라갔다. 장화 소리가 위에서 멈췄다. 다들 숨을 죽인 채 한 시간을 떨었다. 아무도 못 잤다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B2', t:'배식 수레 뒤 — 남은 죽',
  x:`밤 배식 수레가 지나간 자리에 죽 그릇이 남았다. 먹다 만 것이다. 식었다.<br><br>
    남이 남긴 죽은 평생 먹었다.<br>
    그런데 여기 죽은 다들 반만 먹고 잠들었다.<br><br>
    나머지 반에 무엇이 들었는지 안다.`,
  o:[
    { l:'① 위의 반만 걷어 먹는다.', k:'luck', dc:20,
      ok:`숟가락으로 죽 위를 살살 걷었다. 약은 무거워서 가라앉는다. 위의 반만 먹었다.<br><br>배가 조금 찼다. 졸리지 않다. 바닥 반은 쏟아 버렸다.<br>수레 밑칸을 꼭 본다. 배식원이 흘리고 간 꿀 봉지 하나가 굴러다녔다. 그것도 챙겼다.`,
      ng:`걷는데 죽이 섞인다. 위아래가 없다. 휘저어 놓은 죽이다.<br><br>한 숟가락 먹었다. 눈꺼풀이 무겁다. 벽에 기대 한참 졸았다. 깨어 보니 손등에 번호가 적혀 있었다.`,
      win:{ exp:18, dream:3, item:'꿀 한 줌' }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 배식원을 따라가 손을 내민다.', k:'bond', dc:21,
      ok:`수레 미는 배식원 뒤를 따라갔다. 손을 내밀었다. 남은 것 있으면 달라고.<br><br>배식원이 돌아본다. 동냥하는 환자는 처음이다. 웃는 눈이 처음으로 진짜 웃는다. 수레 밑에서 약 안 넣은 빵 하나를 꺼내 준다. 자기 몫이었다고.<br>배식원도 배가 고프다. 배고픈 사람끼리는 안다.`,
      ng:`내밀었는데 배식원이 손바닥에 알약을 올린다.<br><br>먹으라는 눈이다. 거절하자 배식원 손이 턱을 쥔다. 뿌리치다 수레에 허리를 찧었다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B3', t:'객차 지붕 — 바람',
  x:`연결문이 잠겼다. 다음 칸으로 가려면 지붕이다. 사다리가 칸 끝에 붙어 있다.<br><br>
    바람이 세다. 비가 칼처럼 옆으로 친다.<br>
    화물열차 지붕을 타 본 적이 있다. 엎드려야 한다. 일어서면 바람이 데려간다.<br><br>
    멀리 터널 입구가 검게 다가온다.`,
  o:[
    { l:'① 지붕을 뛰어 건넌다.', k:'luck', dc:22,
      doom:{ title:'바람', what:'지붕에서 바람에 끌려갑니다', dc:18, sec:50,
        text:`일어서서 뛰었다. 빠르면 바람도 못 잡는다고 생각했다.<br><br>세 걸음째에 바람이 옷자락을 잡았다. 몸이 뜬다. 지붕 가장자리로 끌려간다. 손이 환기구 덮개를 붙잡았다. 덮개가 들썩인다.<br><br>터널이 다가온다. 터널이 오면 납작 엎드려야 한다는 걸 안다. 지금은 엎드릴 수가 없다.`,
        dieText:`열차가 터널을 빠져나왔다.<br><br>지붕 위에 환기구 덮개 하나가 열려 덜컹거린다.<br>객차 창에 빗물이 비스듬히 흘렀다. 안에서는 아무도 지붕 소리를 못 들었다.` },
      ok:`일어서서 뛰려다 그만뒀다. 몸이 먼저 기억했다. 엎드려 기었다.<br><br>바람이 등 위로 지나간다. 납작하면 바람이 못 잡는다. 터널이 오기 전에 다음 칸 사다리에 닿았다. 터널 속에서 지붕 바람 소리가 비명처럼 울렸다.<br>사다리를 내려와 다음 칸에 들어갔다. 안에서 연결문 잠금쇠를 풀었다. 일행이 걸어서 건너왔다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 내공을 손바닥에 모아 철판에 붙는다.', k:'steady', dc:21, cost:{ qi:26 },
      ok:`엎드려 손바닥과 무릎에 내공을 모았다. 젖은 철판에 손바닥이 붙는다. 미끄러지지 않는다.<br><br>한 뼘씩 기었다. 바람이 아무리 당겨도 손이 안 떨어진다. 터널 속에서도 철판에 붙어 있었다.<br>사다리로 내려왔을 때 손바닥이 벌겋게 부었다. 내공이 손바닥을 지붕에 꿰매 놓았던 셈이다.`,
      ng:`모으는데 빗물이 손바닥과 철판 사이에 낀다.<br><br>손이 미끄러진다. 지붕 가장자리까지 밀렸다. 발끝이 허공에 떴다. 일행이 사다리에서 손목을 잡아당겼다. 어깨가 빠질 뻔했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-12 } },
    { l:'③ 지붕 대신 칸 사이 밑으로 기어간다.', k:'evade', dc:20,
      ok:`지붕 대신 연결판 밑을 봤다. 쇠 틀 사이로 사람 하나 지나갈 틈이 있다. 위보다 밑을 먼저 본다.<br><br>쇠 틀을 붙잡고 기었다. 발밑에 선로가 흘러간다. 보지 않았다. 다음 칸 바닥 점검구로 나왔다. 기름이 온몸에 묻었다.<br>기름은 씻으면 된다.`,
      ng:`기는데 쇠 틀이 덜컹하며 틈이 좁아진다. 어깨가 끼었다.<br><br>열차가 꺾일 때마다 틀이 조인다. 겨우 빠져나왔을 때 어깨에 시퍼런 자국이 났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B', t:'은신처 — 그릇에 든 쪽지',
  x:`쉬는 사이 그릇을 내려놓았다. 버릇이다.<br><br>
    잠깐 눈을 붙이고 뜨니 그릇에 무엇인가 들었다. 접힌 쪽지 하나와 동전 하나.<br>
    일행 중 누가 넣었다.<br><br>
    누가 넣었는지는 묻지 않는 게 빌어먹는 사람의 법이다.`,
  o:[
    { l:'① 쪽지를 펴 읽는다.', k:'luck', dc:21, wake:1,
      ok:`폈다. 떨리는 글씨다. 『우리 중 하나가 판다. 너는 아무도 안 본다. 그러니 너는 봐라.』<br><br>쪽지를 품에 넣고 눈을 감은 척했다. 빌어먹는 사람 앞에서는 다들 경계를 푼다. 사람으로 안 치니까.<br>한 시간 뒤 일행 하나가 문가에서 바깥에 대고 손가락 넷을 펴 보였다. 보았다. 그 손가락을 기억했다. 그 사람을 맨 앞에 세웠다.<br><br>아무도 안 보는 자리에서 다 보는 법. 그 자리가 제 자리라는 걸 처음으로 떳떳하게 알았다.`,
      ng:`폈는데 글씨가 젖어 번졌다. 한 줄도 안 읽힌다.<br><br>누가 무엇을 알리려 했는지 모른다. 그 뒤로 일행 하나하나가 다 수상해 보였다. 쉬어도 쉬어지지 않았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 동전의 주인을 가린다.', k:'gaze', dc:20,
      ok:`동전을 봤다. 반짝인다. 새것이다. 일행 중 새 동전을 가진 사람은 하나뿐이다. 들어올 때 빈손이던 사람.<br><br>쪽지는 다른 사람이 넣었다. 동전은 그 사람이 넣었다. 동냥이 아니라 입막음이다. 동냥과 입막음의 차이는 손바닥이 안다.<br>동전을 그 사람 앞에 조용히 돌려놓았다. 그 사람이 굳었다.`,
      ng:`보는데 동전이 그릇 안에서 데굴데굴 구른다. 멈추지 않는다.<br><br>소리가 크다. 다들 깼다. 다들 그릇을 본다. 누가 넣었냐는 말이 나왔다. 아무도 대답하지 않았다. 의심만 남았다.`,
      win:{ exp:18, dream:3 }, lose:{ mind:-14, spirit:-16 } },
    { l:'③ 그릇을 엎어 둔다.', k:'steady', dc:19,
      ok:`그릇을 엎었다. 빌어먹는 사람들 사이에서 엎은 그릇은 받지 않음이다.<br><br>아무것도 안 받은 사람은 아무 편도 아니다. 쪽지 넣은 사람도 동전 넣은 사람도 그걸 알아들었다. 둘 다 건드리지 않았다.<br>남의 싸움에 그릇을 엎는 것도 사는 법이다.`,
      ng:`엎었는데 그릇 밑에서 쪽지가 빠져나와 바닥에 떨어진다.<br><br>누가 집어 들었다. 읽었다. 얼굴이 변했다. 그 뒤로 일행이 둘로 갈렸다. 가운데 앉아 양쪽 눈치를 보다 밀쳐져 벽에 머리를 찧었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B1', t:'야적장 — 컨테이너 틈의 주인',
  x:`컨테이너 사이 틈이 좁다. 사람 하나 옆으로 들어갈 만하다. 탐조등이 그 위를 훑는다.<br><br>
    틈 바닥에 비닐이 깔렸고 빈 깡통이 몇 개 놓였다.<br>
    누가 여기서 잔다.<br><br>
    이런 틈엔 주인이 있다.`,
  o:[
    { l:'① 깡통을 피해 디디며 지나간다.', k:'luck', dc:21,
      ok:`깡통을 건드리지 않게 발을 디뎠다. 깡통은 경보다. 잠자리 둘레에 깡통을 놓는 법은 어디나 같다.<br><br>틈 끝까지 갔다. 끝에 컨테이너 밑으로 파 놓은 구멍이 있다. 주인이 판 길이다. 철조망 밖으로 이어진다.<br>빠져나가며 깡통 하나에 말린 고기 한 조각을 넣어 두었다. 길 값이다.`,
      ng:`디뎠는데 깡통이 굴렀다.<br><br>소리가 컨테이너 벽을 타고 울린다. 탐조등이 틈 위에서 멈췄다. 틈 끝에서 누가 일어선다. 주인이다. 이쪽보다 더 놀랐다. 둘 다 반대로 뛰었다. 컨테이너 모서리에 이마가 찢겼다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 입구에 쪼그려 주인을 기다린다.', k:'bond', dc:20,
      ok:`틈 입구에 쪼그려 앉아 기다렸다. 잠자리 주인에게는 먼저 인사하는 게 법이다.<br><br>주인이 돌아왔다. 늙은 하역부다. 이쪽 그릇을 보고 고개를 끄덕인다. 같은 업은 그릇으로 안다.<br>주인이 구멍을 알려 줬다. 대신 나가거든 이 틈 얘기는 하지 말라고. 이런 약속은 지킨다.`,
      ng:`기다리는데 탐조등이 틈 입구를 비춘다.<br><br>기다리던 자리가 밝아졌다. 주인 대신 노란 비옷이 왔다. 깡통을 걷어차며 뛰었다. 비옷 장대가 등을 긁고 지나갔다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B2', t:'비상계단 — 4층 계단참',
  x:`비상계단이 4층에서 끊겼다. 벽돌로 막았다.<br><br>
    계단참에 이불이 깔려 있다. 환자 하나가 산다. 병실에서 도망 나와 몇 달을 여기서 살았다고 한다. 정각에 계단참은 아무도 안 센다.<br>
    한눈에 알았다.<br><br>
    병원에서 빌어먹는 사람이 된 사람이다.`,
  o:[
    { l:'① 곁에 앉아 그릇을 나란히 놓는다.', k:'luck', dc:20, wake:1,
      ok:`그 사람 옆에 쪼그려 앉았다. 그릇을 나란히 놓았다. 말없이.<br><br>한참 뒤 그 사람이 벽돌 하나를 가리킨다. 헐겁다. 빼니 바람이 들어온다. 3층 계단참으로 통하는 구멍이다. 혼자서는 못 빠져나갔다고 한다. 혼자 빌어먹는 사람은 겁이 많다고.<br>둘이 벽돌을 뺐다. 그 사람도 같이 내려왔다.<br><br>그릇 옆에 그릇 하나가 더 놓였다. 둘이 빌면 무리다. 무리를 만드는 손이 처음 움직였다.`,
      ng:`옆에 앉았는데 그 사람이 그릇을 끌어안고 물러난다.<br><br>자리를 뺏으러 온 줄 안다. 소리를 지른다. 계단 위아래로 울린다. 4층 문 너머 딸깍 소리가 빨라졌다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 그 사람이 졸 때 이불 밑을 본다.', k:'sense', dc:21,
      ok:`그 사람이 졸 때 이불 가장자리를 들췄다. 이불 밑에 전 재산을 둔다는 걸 안다.<br><br>약초 뭉치 하나와 볼펜으로 그린 계단 도면. 4층에서 1층까지 끊긴 곳마다 동그라미.<br>약초는 두고 도면만 외웠다. 빌어먹는 사람 재산은 훔치면 안 된다. 보는 건 괜찮다.`,
      ng:`들추는데 그 사람이 눈을 뜬다.<br><br>같은 처지 이불을 들췄다. 제일 나쁜 짓이다. 그 사람이 손톱으로 손등을 긁었다. 깊게. 할 말이 없었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B3', t:'2호차 — 입마개 한 개들',
  x:`2호차는 화물칸이다. 쇠 우리에 개들이 갇혔다. 입마개를 했다. 짖지 못한다.<br><br>
    이쪽을 보고 우리에 몸을 부딪는다. 우리 문이 헐겁다.<br>
    개는 안다. 평생 개한테 쫓겼다.<br><br>
    쫓긴 사람이 개를 제일 잘 안다.`,
  o:[
    { l:'① 품의 먹을 것을 반대쪽 구석에 던진다.', k:'luck', dc:21,
      ok:`품에서 말린 고기 껍질을 꺼냈다. 우리 앞에 놓지 않았다. 반대쪽 구석에 던졌다.<br><br>개들이 그쪽으로 몰린다. 우리가 그쪽으로 기운다. 반대쪽으로 지나갔다. 개들은 냄새만 쫓았다.<br>개는 배고픔을 못 이긴다. 그건 이쪽도 안다. 그래서 개와는 서로를 안다.`,
      ng:`던졌는데 개들이 안 간다. 이쪽 손에서 더 진한 냄새가 난다.<br><br>우리 문이 덜컹 열렸다. 입마개 한 주둥이가 정강이를 들이받았다. 넘어졌다. 등에 발톱 자국이 남았다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, mind:-12 } },
    { l:'② 내공을 끌어올려 기세로 누른다.', k:'steady', dc:20, cost:{ qi:24 },
      ok:`발을 바닥에 박고 내공을 배꼽 아래로 모았다. 내쉬었다. 낮게.<br><br>사람의 숨이 아니다. 개들이 귀를 젖힌다. 몸을 부딪던 것이 멈춘다. 하나씩 우리 안쪽으로 물러나 엎드린다.<br>기세는 짖는 것보다 멀리 간다. 2호차를 지나는 동안 개들은 고개를 들지 않았다.`,
      ng:`모으는데 배가 꼬르륵 운다.<br><br>개들이 그 소리를 들었다. 기세가 아니라 허기라는 걸 안 것이다. 우리 문이 들썩였다. 뛰어 지나가다 우리 모서리에 허벅지가 찢겼다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B', t:'쉬는 자리 — 먼저 나누는 법',
  x:`쉬는 자리에서 품을 열었다. 여기저기서 얻고 주운 것들이 나온다. 꽤 된다.<br><br>
    일행은 다 떨어졌다. 다들 이쪽 품을 본다.<br>
    빌어먹는 사람에게는 먼저 먹는 법과 먼저 나누는 법이 있다.<br><br>
    거지는 평생 먼저 먹는 법으로 살았다.`,
  o:[
    { l:'① 먼저 나눈다.', k:'luck', dc:20, wake:1,
      ok:`제 몫을 남기기 전에 다 나눴다. 다친 사람 먼저.<br><br>남은 것이 제 몫이다. 적다. 그런데 다 먹고 나니 배가 부르다. 일행 하나가 제 몫을 반 떼어 밀어 준다. 다른 하나도.<br><br>얻어먹던 사람이 무리를 먹였다. 무리가 그를 먹였다. 서로를 먹이는 무리가 되는 법이 손에 붙었다.`,
      ng:`나누다 보니 제 몫이 하나도 없다.<br><br>아무도 눈치를 못 챘다. 말을 안 했다. 배가 고파 일어설 때 다리가 후들거렸다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 내일 몫을 품 깊이 남긴다.', k:'sense', dc:19,
      ok:`오늘 먹을 것만 꺼내고 나머지는 품 깊이 넣었다. 내일이 오늘보다 나쁠 걸 안다.<br><br>품 깊은 데서 손에 걸리는 게 하나 더 있었다. 잊고 있던 약초 뭉치다.`,
      ng:`넣다가 떨어뜨린 걸 쥐가 물고 갔다.<br><br>아끼다 잃었다. 제일 싫어하는 일이다. 쫓다가 벽에 어깨를 박았다.`,
      win:{ exp:16, dream:2, item:'약초 뭉치' }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B', t:'처마 끝 — 그릇 하나의 물',
  x:`마실 물이 떨어졌다. 비는 오는데 마실 물이 없다.<br><br>
    고인 물에는 기름이 떴다.<br>
    그릇을 하늘로 들었다. 비를 받는 법은 안다.<br><br>
    그릇 하나로는 한 사람 몫이다.`,
  o:[
    { l:'① 처마마다 낙숫물 줄기를 고른다.', k:'luck', dc:20,
      ok:`처마마다 떨어지는 줄기가 다르다. 녹슨 홈통 줄기는 붉다. 기와 끝 줄기는 맑다.<br><br>맑은 줄기 밑에 그릇을 받쳤다. 금방 찬다. 일행에게 돌렸다. 다섯 번 받았다. 다섯 번 돌았다.<br>그릇은 전부다. 전부를 나눠 쓰는 것도 사는 법이다.`,
      ng:`고른 줄기가 맑은데 쓰다. 지붕에 무엇이 칠해져 있었다.<br><br>마신 사람들이 다 배를 움켜쥐었다. 이쪽 탓이라는 눈길이 왔다. 할 말이 없었다.`,
      win:{ exp:18, dream:3, item:'맑은 물' }, lose:{ hp:-22, mind:-14 } },
    { l:'② 내공으로 고인 물을 데워 거른다.', k:'fix', dc:21, cost:{ qi:22 },
      ok:`고인 물을 그릇에 뜨고 두 손으로 감쌌다. 내공을 손바닥으로 밀었다.<br><br>그릇이 데워진다. 김이 오른다. 기름은 위로 뜬다. 걷어 냈다. 한 번 더.<br>끓인 물은 조금 비렸다. 탈은 안 났다. 내공은 불이기도 하다.`,
      ng:`미는데 그릇에 금이 간다. 평생 들고 다닌 그릇이다.<br><br>물이 금 사이로 샌다. 손바닥이 데었다. 금 간 그릇을 한참 쳐다봤다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B', t:'방 구석 — 그릇을 내민 것',
  x:`방 구석에 무엇인가 쪼그려 앉아 그릇을 내민다.<br><br>
    젖은 옷, 이 빠진 사기 그릇. 이쪽 것과 똑같다.<br>
    고개를 숙여서 얼굴이 안 보인다.<br><br>
    문은 하나다. 그것 앞을 지나야 문이다.`,
  o:[
    { l:'① 그릇 속을 들여다본다.', k:'gaze', dc:22,
      doom:{ title:'같은 그릇', what:'그릇 속으로 빨려 들고 있습니다', dc:18, sec:50,
        text:`그릇 속을 봤다. 바닥에 이쪽 얼굴이 있다.<br><br>얼굴이 점점 커진다. 아니다. 이쪽이 그릇 쪽으로 기울고 있다. 그릇을 든 것이 고개를 든다. 얼굴이 없다. 이쪽 얼굴을 기다리고 있었다.<br><br>그릇은 전부다. 전부를 들여다보면 전부가 들여다본다.`,
        dieText:`방 구석에 누가 쪼그려 앉아 있다.<br><br>그릇을 내밀고 있다. 고개를 숙여서 얼굴이 안 보인다.<br>안 보이는 게 아니라 없다.` },
      ok:`그릇 속을 봤다. 바닥에 금이 있다. 이쪽 그릇과 같은 자리에 같은 금.<br><br>같은 그릇이 아니라 이쪽 그릇의 그림자다. 그림자가 그릇을 내밀고 있었다.<br>제 그릇을 들어 보이자 그것이 고개를 숙이고 흐려졌다. 흐려진 자리 너머로 문이 보였다.`,
      win:{ exp:22, dream:4 } },
    { l:'② 가진 것을 그 그릇에 넣는다.', k:'luck', dc:21,
      ok:`품에서 제일 아끼던 것을 꺼내 그릇에 넣었다.<br><br>그것이 고개를 든다. 얼굴이 없다. 그래도 웃는 것 같다. 그릇을 엎어 이쪽 그릇에 쏟는다. 넣은 것보다 많이 돌아왔다. 그리고 비켜 앉는다.<br>빌어먹는 사람이 베풀었다. 받은 것은 돌아온다.`,
      ng:`넣었는데 그것이 그릇째 내민다. 더 달라는 것이다.<br><br>또 넣었다. 또 내민다. 품이 비었다. 빈 품으로 그것 옆을 지났다. 지나는 동안 등이 계속 차가웠다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'③ 내공으로 발소리를 지우고 지나친다.', k:'hide', dc:20, cost:{ qi:22 },
      ok:`숨을 죽이고 내공으로 발소리를 지웠다.<br><br>그것 앞을 지났다. 그릇이 따라 움직이지 않는다. 못 본 척 지나가는 것은 평생 당하던 일이다. 이번엔 이쪽이 했다. 조금 미안했다.`,
      ng:`지웠는데 배가 운다.<br><br>그릇이 이쪽으로 돌아선다. 그 앞을 지나는 동안 그릇이 계속 따라왔다. 문을 나서는데 발목을 무엇인가 스쳤다. 살갗이 하얗게 얼었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'내려가는 계단 — 허리끈 매듭',
  x:`계단 앞에서 허리를 만졌다.<br><br>
    허리끈에 매듭을 지어 날을 센다. 여기 들어와서 매듭이 많이 늘었다.<br>
    하룻밤인데 매듭이 일곱이다.<br><br>
    위험을 넘을 때마다 하나씩 지었다.`,
  o:[
    { l:'① 매듭을 하나씩 짚어 센다.', k:'luck', dc:20, wake:1,
      ok:`하나씩 짚었다. 처마 밑, 쓰레기 더미, 지붕, 계단참. 매듭마다 같이 넘은 사람이 있다.<br><br>혼자 넘은 매듭이 하나도 없다. 평생 혼자 지은 매듭만 있던 끈이다.<br>끈 끝을 조금 남겨 두었다. 다음 사람 매듭 지을 자리.<br><br>같이 다닐 사람이 생기면 끈도 길어진다. 끈 하나에 무리가 걸리기 시작했다.`,
      ng:`짚는데 매듭 하나가 풀려 있다. 누가 풀었다.<br><br>어느 고비 매듭인지 모르겠다. 하나가 빈다. 그 하나를 생각하며 계단을 내려갔다. 발을 헛디뎠다.`,
      win:{ exp:22, dream:4 }, lose:{ mind:-14, spirit:-14 } },
    { l:'② 끈을 고쳐 매고 내려간다.', k:'steady', dc:19,
      ok:`끈을 풀어 다시 맸다. 단단하게. 매듭이 늘면 끈이 짧아진다. 짧아진 만큼 허리가 단단하다.<br><br>계단을 내려갔다. 다리가 가볍다.`,
      ng:`고쳐 매다 끈이 끊어졌다.<br><br>매듭 일곱이 계단으로 흩어졌다. 주워 담는 데 한참 걸렸다. 다 못 주웠다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-14, spirit:-12 } },
    { l:'③ 일행 허리에도 끈 한 토막씩 매어 준다.', k:'bond', dc:21,
      ok:`끈을 끊어 다섯 토막으로 나눴다. 하나씩 일행 허리에 매 줬다. 매듭 하나씩.<br><br>빌어먹는 사람 끈이다. 다들 웃는다. 그래도 푼 사람은 없다. 내려가는 내내 다들 가끔 허리를 만졌다.`,
      ng:`매 주는데 하나가 손을 뿌리친다. 그런 끈은 싫다고.<br><br>그 사람 허리만 비었다. 계단 아래서 그 사람이 제일 먼저 헛디뎠다. 붙잡다 같이 굴렀다.`,
      win:{ exp:18, dream:3, mind:6 }, lose:{ hp:-24, mind:-12 } }
  ] }

]);

